export enum PaymentStatus {
  PENDING = 'PENDING',
  PAID = 'PAID',
}

export interface Attendee {
  id: string;
  name: string;
  email?: string;
  phone?: string;
  status: PaymentStatus;
  registrationDate: string;
}

export interface Expense {
  id: string;
  description: string;
  amount: number;
}

export interface ExtraExpense {
  id: string;
  description: string;
  amount: number;
  date: string;
}

export interface AppEvent {
  id: string;
  title: string;
  description: string;
  date: string;
  time: string;
  location: string;
  cost: number; // Ticket price per person
  maxAttendees?: number; // Optional capacity limit
  expenses: Expense[]; // List of operational costs
  attendees: Attendee[];
  createdAt: string;
}

export type ViewState = 
  | { type: 'DASHBOARD' }
  | { type: 'CREATE_EVENT' }
  | { type: 'EDIT_EVENT'; eventId: string }
  | { type: 'EVENT_DETAILS'; eventId: string }
  | { type: 'SETTINGS' }
  | { type: 'PARTICIPANTS' };

import { AppEvent, Attendee, Expense, ExtraExpense, PaymentStatus } from '../types';
import { initializeApp, getApps, getApp } from "firebase/app";
import { getFirestore, collection, getDocs, doc, setDoc, deleteDoc, getDoc, updateDoc } from "firebase/firestore";

const STORAGE_KEY = 'onbeventi_data_v1';
const EXTRA_EXPENSES_KEY = 'onbeventi_extra_expenses_v1';
const FIREBASE_CONFIG_KEY = 'onbeventi_firebase_config';

const getDb = () => {
  const configStr = localStorage.getItem(FIREBASE_CONFIG_KEY);
  if (!configStr) return null;
  try {
    const firebaseConfig = JSON.parse(configStr);
    const app = !getApps().length ? initializeApp(firebaseConfig) : getApp();
    return getFirestore(app);
  } catch (e) {
    console.error("Firebase config error", e);
    return null;
  }
};

export const generateId = (): string => {
  return Date.now().toString(36) + Math.random().toString(36).substring(2, 9);
};

// --- EVENTS ---
export const getEvents = async (): Promise<AppEvent[]> => {
  const db = getDb();
  if (db) {
    try {
      const querySnapshot = await getDocs(collection(db, "events"));
      const events: AppEvent[] = [];
      querySnapshot.forEach((doc) => { events.push(doc.data() as AppEvent); });
      return events;
    } catch (e) { return []; }
  } else {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  }
};

export const saveEvent = async (event: AppEvent): Promise<void> => {
  const db = getDb();
  if (db) {
    await setDoc(doc(db, "events", event.id), event);
  } else {
    const events = (await getEvents());
    const idx = events.findIndex(e => e.id === event.id);
    if (idx >= 0) events[idx] = event; else events.push(event);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(events));
  }
};

export const deleteEvent = async (eventId: string): Promise<void> => {
  const db = getDb();
  if (db) {
    await deleteDoc(doc(db, "events", eventId));
  } else {
    const events = (await getEvents()).filter(e => e.id !== eventId);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(events));
  }
};

// --- EXTRA EXPENSES ---
export const getExtraExpenses = async (): Promise<ExtraExpense[]> => {
  const db = getDb();
  if (db) {
    try {
      const querySnapshot = await getDocs(collection(db, "extra_expenses"));
      const list: ExtraExpense[] = [];
      querySnapshot.forEach((doc) => { list.push(doc.data() as ExtraExpense); });
      return list;
    } catch (e) { return []; }
  } else {
    const data = localStorage.getItem(EXTRA_EXPENSES_KEY);
    return data ? JSON.parse(data) : [];
  }
};

export const saveExtraExpense = async (expense: ExtraExpense): Promise<void> => {
  const db = getDb();
  if (db) {
    await setDoc(doc(db, "extra_expenses", expense.id), expense);
  } else {
    const list = await getExtraExpenses();
    list.push(expense);
    localStorage.setItem(EXTRA_EXPENSES_KEY, JSON.stringify(list));
  }
};

export const deleteExtraExpense = async (id: string): Promise<void> => {
  const db = getDb();
  if (db) {
    await deleteDoc(doc(db, "extra_expenses", id));
  } else {
    const list = (await getExtraExpenses()).filter(e => e.id !== id);
    localStorage.setItem(EXTRA_EXPENSES_KEY, JSON.stringify(list));
  }
};

// --- HELPERS ---
const updateSingleEvent = async (eventId: string, updateFn: (event: AppEvent) => AppEvent): Promise<AppEvent | null> => {
  const db = getDb();
  if (db) {
    const docRef = doc(db, "events", eventId);
    const docSnap = await getDoc(docRef);
    if (docSnap.exists()) {
      const event = docSnap.data() as AppEvent;
      const updatedEvent = updateFn(event);
      await setDoc(docRef, updatedEvent);
      return updatedEvent;
    }
    return null;
  } else {
    const events = (await getEvents());
    const idx = events.findIndex(e => e.id === eventId);
    if (idx === -1) return null;
    const updated = updateFn(events[idx]);
    events[idx] = updated;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(events));
    return updated;
  }
};

export const addAttendee = async (eventId: string, attendee: Attendee): Promise<AppEvent | null> => {
  return updateSingleEvent(eventId, (event) => {
    event.attendees.push(attendee);
    return event;
  });
};

export const updateAttendee = async (eventId: string, updatedAttendee: Attendee): Promise<AppEvent | null> => {
  return updateSingleEvent(eventId, (event) => {
    const index = event.attendees.findIndex(a => a.id === updatedAttendee.id);
    if (index !== -1) event.attendees[index] = updatedAttendee;
    return event;
  });
};

export const togglePaymentStatus = async (eventId: string, attendeeId: string): Promise<AppEvent | null> => {
  return updateSingleEvent(eventId, (event) => {
    const index = event.attendees.findIndex(a => a.id === attendeeId);
    if (index !== -1) {
      event.attendees[index].status = event.attendees[index].status === PaymentStatus.PAID ? PaymentStatus.PENDING : PaymentStatus.PAID;
    }
    return event;
  });
};

export const deleteAttendee = async (eventId: string, attendeeId: string): Promise<AppEvent | null> => {
  return updateSingleEvent(eventId, (event) => {
    event.attendees = event.attendees.filter(a => a.id !== attendeeId);
    return event;
  });
};

export const addExpense = async (eventId: string, expense: Expense): Promise<AppEvent | null> => {
  return updateSingleEvent(eventId, (event) => {
    if (!event.expenses) event.expenses = [];
    event.expenses.push(expense);
    return event;
  });
};

export const updateExpense = async (eventId: string, updatedExpense: Expense): Promise<AppEvent | null> => {
  return updateSingleEvent(eventId, (event) => {
    if (event.expenses) {
      const index = event.expenses.findIndex(e => e.id === updatedExpense.id);
      if (index !== -1) event.expenses[index] = updatedExpense;
    }
    return event;
  });
};

export const deleteExpense = async (eventId: string, expenseId: string): Promise<AppEvent | null> => {
  return updateSingleEvent(eventId, (event) => {
    if (event.expenses) event.expenses = event.expenses.filter(e => e.id !== expenseId);
    return event;
  });
};

export const isCloudEnabled = (): boolean => !!localStorage.getItem(FIREBASE_CONFIG_KEY);

import React, { useMemo, useState } from 'react';
import { AppEvent, ExtraExpense, PaymentStatus } from '../types';
import { Calendar, DollarSign, Users, Plus, ArrowRight, MapPin, Clock, Ticket, TrendingDown, Wallet, History, Receipt, Trash2, Save } from 'lucide-react';
import { Button } from './Button';
import { generateId, saveExtraExpense, deleteExtraExpense } from '../services/storageService';

interface DashboardProps {
  events: AppEvent[];
  extraExpenses: ExtraExpense[];
  onCreateClick: () => void;
  onEventClick: (id: string) => void;
  onRefresh: () => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ events, extraExpenses, onCreateClick, onEventClick, onRefresh }) => {
  const [showAddExtra, setShowAddExtra] = useState(false);
  const [newExtra, setNewExtra] = useState({ description: '', amount: '' });
  const [loading, setLoading] = useState(false);

  const stats = useMemo(() => {
    const today = new Date();
    today.setHours(0,0,0,0);

    const upcoming = events
      .filter(e => new Date(e.date) >= today)
      .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    const past = events
      .filter(e => new Date(e.date) < today)
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    // GLOBAL STATS (All time)
    const totalRevenue = events.reduce((acc, curr) => {
      const paidAttendees = curr.attendees.filter(a => a.status === PaymentStatus.PAID).length;
      return acc + (paidAttendees * curr.cost);
    }, 0);

    const totalEventExpenses = events.reduce((acc, curr) => {
      return acc + (curr.expenses || []).reduce((sum, exp) => sum + exp.amount, 0);
    }, 0);

    const totalExtraExpenses = extraExpenses.reduce((acc, curr) => acc + curr.amount, 0);
    const totalExpenses = totalEventExpenses + totalExtraExpenses;
    const totalProfit = totalRevenue - totalExpenses;

    return { upcoming, past, totalRevenue, totalExpenses, totalProfit };
  }, [events, extraExpenses]);

  const handleAddExtra = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newExtra.description || !newExtra.amount) return;
    setLoading(true);
    try {
      await saveExtraExpense({
        id: generateId(),
        description: newExtra.description,
        amount: Number(newExtra.amount),
        date: new Date().toISOString()
      });
      setNewExtra({ description: '', amount: '' });
      setShowAddExtra(false);
      onRefresh();
    } finally {
      setLoading(false);
    }
  };

  const handleRemoveExtra = async (id: string) => {
    if (!confirm("Eliminare questa spesa extra?")) return;
    await deleteExtraExpense(id);
    onRefresh();
  };

  const renderEventItem = (event: AppEvent) => (
    <div 
      key={event.id} 
      className="p-6 hover:bg-gray-50 transition-all cursor-pointer group border-l-4 border-transparent hover:border-pink-500" 
      onClick={() => onEventClick(event.id)}
    >
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
        <div className="flex items-start gap-4 flex-1">
          <div className="hidden md:flex flex-col items-center justify-center w-16 h-16 bg-indigo-50 rounded-2xl border border-indigo-100 text-indigo-900 shrink-0">
            <span className="text-xs font-bold uppercase">{new Date(event.date).toLocaleDateString('it-IT', { month: 'short' })}</span>
            <span className="text-2xl font-bold">{new Date(event.date).getDate()}</span>
          </div>
          <div>
            <h3 className="text-lg font-bold text-gray-900 group-hover:text-pink-600 transition-colors">{event.title}</h3>
