    setIsCloud(isCloudEnabled());
    try {
      const [eventsData, expensesData] = await Promise.all([
        getEvents(),
        getExtraExpenses()
      ]);
      setEvents(eventsData);
      setExtraExpenses(expensesData);
    } catch (e) {
      console.error("Failed to load data", e);
    } finally {
      setIsLoading(false);
    }
  };

  const navigateToDashboard = () => {
    setViewState({ type: 'DASHBOARD' });
    refreshData();
  };

  const handleEventSaved = async (event: AppEvent) => {
    setIsLoading(true);
    await saveEvent(event);
    setViewState({ type: 'EVENT_DETAILS', eventId: event.id });
    await refreshData();
  };

  const handleEventUpdated = async (updatedEvent: AppEvent) => {
    setEvents(prev => prev.map(e => e.id === updatedEvent.id ? updatedEvent : e));
  };

  const renderContent = () => {
    if (isLoading && events.length === 0) {
      return (
        <div className="flex h-[50vh] items-center justify-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-pink-600"></div>
        </div>
      );
    }

    switch (viewState.type) {
      case 'DASHBOARD':
        return (
          <Dashboard 
            events={events} 
            extraExpenses={extraExpenses}
            onCreateClick={() => setViewState({ type: 'CREATE_EVENT' })}
            onEventClick={(id) => setViewState({ type: 'EVENT_DETAILS', eventId: id })}
            onRefresh={refreshData}
          />
        );

      case 'PARTICIPANTS':
        return <ParticipantsList events={events} onBack={navigateToDashboard} />;

      case 'CREATE_EVENT':
        return <EventForm onSave={handleEventSaved} onCancel={navigateToDashboard} />;

      case 'EDIT_EVENT':
        const eventToEdit = events.find(e => e.id === viewState.eventId);
        if (!eventToEdit) return <div>Evento non trovato</div>;
        return (
          <EventForm
            initialData={eventToEdit}
            onSave={handleEventSaved}
            onCancel={() => setViewState({ type: 'EVENT_DETAILS', eventId: eventToEdit.id })}
          />
        );

      case 'EVENT_DETAILS':
        const event = events.find(e => e.id === viewState.eventId);
        if (!event) return <div>Evento non trovato</div>;
        return (
          <EventDetails 
            event={event} 
            allEvents={events}
            onBack={navigateToDashboard}
            onUpdate={handleEventUpdated}
            onDelete={navigateToDashboard}
            onEditEvent={() => setViewState({ type: 'EDIT_EVENT', eventId: event.id })}
          />
        );

      case 'SETTINGS':
        return <Settings onBack={navigateToDashboard} />;

      default:
        return <div>View not found</div>;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row font-sans">
      {/* Sidebar Navigation */}
      <aside className="bg-indigo-950 text-white w-full md:w-64 flex-shrink-0 flex flex-col shadow-2xl z-20 relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none opacity-20">
             <div className="absolute top-[-50px] left-[-50px] w-40 h-40 bg-pink-600 rounded-full blur-[60px]"></div>
        </div>

        <div className="p-6 relative z-10">
          <div className="flex items-center justify-center md:justify-start mb-10 mt-2">
             <div className="relative group cursor-default select-none">
               <div className="absolute -inset-1 bg-gradient-to-r from-pink-500 to-purple-500 rounded-xl blur opacity-40"></div>
               <div className="relative flex items-center bg-indigo-950 border border-indigo-800/50 rounded-xl px-5 py-3 shadow-2xl">
                 <div className="flex flex-col leading-none">
                    <div className="flex items-baseline gap-0.5">
                      <span className="text-2xl font-black text-pink-400">ON</span>
                      <span className="text-2xl font-black text-yellow-400">BEVENTI</span>
                    </div>
                    <span className="text-[0.5rem] font-bold text-indigo-300 uppercase tracking-widest text-right">Event Manager</span>
                 </div>
               </div>
             </div>
          </div>

          <nav className="space-y-3">
            <button 
              onClick={navigateToDashboard}
              className={`w-full flex items-center px-4 py-3.5 rounded-xl transition-all duration-300 font-medium ${
                viewState.type === 'DASHBOARD' || viewState.type === 'EVENT_DETAILS' || viewState.type === 'CREATE_EVENT' || viewState.type === 'EDIT_EVENT'
                  ? 'bg-gradient-to-r from-pink-600 to-purple-700 text-white shadow-lg border border-pink-500/30' 
                  : 'text-indigo-200 hover:bg-white/5 hover:text-white border border-transparent'
              }`}
            >
              <LayoutDashboard className="w-5 h-5 mr-3" />
              Dashboard
            </button>

            <button 
              onClick={() => setViewState({ type: 'PARTICIPANTS' })}
              className={`w-full flex items-center px-4 py-3.5 rounded-xl transition-all duration-300 font-medium ${
                viewState.type === 'PARTICIPANTS' 
                  ? 'bg-gradient-to-r from-pink-600 to-purple-700 text-white shadow-lg border border-pink-500/30' 
                  : 'text-indigo-200 hover:bg-white/5 hover:text-white border border-transparent'
              }`}
            >
              <Users className="w-5 h-5 mr-3" />
              Partecipanti
            </button>

            <button 
              onClick={() => setViewState({ type: 'SETTINGS' })}
              className={`w-full flex items-center px-4 py-3.5 rounded-xl transition-all duration-300 font-medium ${
                viewState.type === 'SETTINGS' 
                  ? 'bg-gradient-to-r from-pink-600 to-purple-700 text-white shadow-lg border border-pink-500/30' 
                  : 'text-indigo-200 hover:bg-white/5 hover:text-white border border-transparent'
              }`}
            >
              <SettingsIcon className="w-5 h-5 mr-3" />
              Impostazioni
            </button>
          </nav>
        </div>

        <div className="p-6 mt-auto relative z-10">
          <div className="bg-indigo-900/40 border border-indigo-800/50 rounded-xl p-4 backdrop-blur-sm">
            <div className="flex items-center justify-between mb-2">
               <p className="text-[10px] text-indigo-300 font-bold uppercase tracking-wider">Sync Status</p>
               {isCloud ? <Cloud className="w-3 h-3 text-green-400" /> : <CloudOff className="w-3 h-3 text-gray-400" />}
            </div>
            <div className="text-[10px] text-indigo-200 font-medium flex items-center justify-between">
               {isCloud ? 'Cloud Sync' : 'Local Only'}
               <button onClick={refreshData} className="hover:text-white transition-colors">
                 <RefreshCw className={`w-3 h-3 ${isLoading ? 'animate-spin' : ''}`} />
               </button>
            </div>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-4 md:p-8 overflow-y-auto h-screen bg-slate-50/50">
        <div className="max-w-7xl mx-auto pb-10">
          {renderContent()}
        </div>
      </main>
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { AppEvent, Attendee, Expense, PaymentStatus } from '../types';
import { Button } from './Button';
import { 
  ArrowLeft, UserPlus, CheckCircle, XCircle, Trash2, 
  Calendar, MapPin, Euro, Clock, Edit2, Plus, 
  TrendingUp, TrendingDown, Wallet, Users, Save, X, AlertTriangle, Phone, Mail, UserCheck
} from 'lucide-react';
import { 
  addAttendee, togglePaymentStatus, deleteAttendee, 
  deleteEvent, addExpense, deleteExpense, updateAttendee, updateExpense, generateId
} from '../services/storageService';

interface EventDetailsProps {
  event: AppEvent;
  allEvents: AppEvent[]; // Added to provide context for suggestions
  onBack: () => void;
  onUpdate: (updatedEvent: AppEvent) => void;
  onDelete: () => void;
  onEditEvent: () => void;
}

export const EventDetails: React.FC<EventDetailsProps> = ({ event, allEvents, onBack, onUpdate, onDelete, onEditEvent }) => {
  const [showAddAttendee, setShowAddAttendee] = useState(false);
  const [showAddExpense, setShowAddExpense] = useState(false);
  const [loading, setLoading] = useState(false);

  // State for new Attendee
  const [newAttendee, setNewAttendee] = useState({ name: '', email: '', phone: '' });
  const [suggestions, setSuggestions] = useState<Attendee[]>([]);

  // State for editing Attendee
  const [editingAttendeeId, setEditingAttendeeId] = useState<string | null>(null);
  const [editAttendeeData, setEditAttendeeData] = useState({ name: '', email: '', phone: '' });

  // State for new Expense
  const [newExpense, setNewExpense] = useState({ description: '', amount: '' });

  // State for editing Expense
  const [editingExpenseId, setEditingExpenseId] = useState<string | null>(null);
  const [editExpenseData, setEditExpenseData] = useState({ description: '', amount: '' });

  // --- CONFIRMATION MODAL STATE ---
  const [confirmModal, setConfirmModal] = useState<{
    isOpen: boolean;
    type: 'DELETE_EVENT' | 'DELETE_ATTENDEE' | 'DELETE_EXPENSE' | null;
    itemId?: string;
    message: string;
  }>({
    isOpen: false,
    type: null,
    message: ''
  });

  // --- SUGGESTIONS LOGIC ---
  const globalParticipants = useMemo(() => {
    const map = new Map<string, Attendee>();
    allEvents.forEach(ev => {
      ev.attendees.forEach(at => {
        const key = (at.email || at.phone || at.name).toLowerCase().trim();
        // Keep the most recent or any instance
        map.set(key, at);
      });
    });
    return Array.from(map.values());
  }, [allEvents]);

  const handleNameChange = (val: string) => {
    setNewAttendee(prev => ({ ...prev, name: val }));
    if (val.length >= 2) {
      const filtered = globalParticipants.filter(p => 
        p.name.toLowerCase().includes(val.toLowerCase())
      ).slice(0, 5); // Limit to top 5 suggestions
      setSuggestions(filtered);
    } else {
      setSuggestions([]);
    }
  };

  const selectSuggestion = (p: Attendee) => {
    setNewAttendee({
      name: p.name,
      email: p.email || '',
      phone: p.phone || ''
    });
    setSuggestions([]);
  };

  // --- ATTENDEE LOGIC ---

  const handleAddAttendee = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    // Check limit
    if (event.maxAttendees && event.attendees.length >= event.maxAttendees) {
      alert("Numero massimo di partecipanti raggiunto.");
      setLoading(false);
      return;
    }

    const attendee: Attendee = {
      id: generateId(),
      name: newAttendee.name,
      email: newAttendee.email,
      phone: newAttendee.phone,
      status: PaymentStatus.PENDING,
      registrationDate: new Date().toISOString()
    };

    try {
      const updated = await addAttendee(event.id, attendee);
      if (updated) {
        onUpdate(updated);
        setNewAttendee({ name: '', email: '', phone: '' });
        setShowAddAttendee(false);
        setSuggestions([]);
      }
    } finally {
      setLoading(false);
    }
  };

  const startEditingAttendee = (attendee: Attendee) => {
    setEditingAttendeeId(attendee.id);
    setEditAttendeeData({ 
      name: attendee.name, 
      email: attendee.email || '', 
      phone: attendee.phone || '' 
    });
  };

  const cancelEditingAttendee = () => {
    setEditingAttendeeId(null);
    setEditAttendeeData({ name: '', email: '', phone: '' });
  };

  const saveEditedAttendee = async (originalAttendee: Attendee) => {
    const updatedAttendee: Attendee = {
      ...originalAttendee,
      name: editAttendeeData.name,
      email: editAttendeeData.email,
      phone: editAttendeeData.phone,
    };
    setLoading(true);
    try {
      const updatedEvent = await updateAttendee(event.id, updatedAttendee);
      if (updatedEvent) {
        onUpdate(updatedEvent);
        setEditingAttendeeId(null);
      }
    } finally {
      setLoading(false);
    }
  };

  const handleTogglePayment = async (attendeeId: string) => {
    setLoading(true);
    try {
      const updated = await togglePaymentStatus(event.id, attendeeId);
      if (updated) onUpdate(updated);
    } finally {
      setLoading(false);
    }
  };

  // --- DELETE REQUESTS (Open Modal) ---

  const requestDeleteAttendee = (attendeeId: string) => {
    setConfirmModal({
      isOpen: true,
      type: 'DELETE_ATTENDEE',
      itemId: attendeeId,
      message: 'Sei sicuro di voler rimuovere questo partecipante dalla lista?'
    });
  };

  const requestDeleteExpense = (expenseId: string) => {
    setConfirmModal({
      isOpen: true,
      type: 'DELETE_EXPENSE',
      itemId: expenseId,
      message: 'Sei sicuro di voler eliminare questa voce di spesa?'
    });
  };

  const requestDeleteEvent = () => {
    setConfirmModal({
      isOpen: true,
      type: 'DELETE_EVENT',
      message: 'ATTENZIONE: Stai per eliminare definitivamente questo evento e tutti i dati associati. Sei sicuro?'
    });
  };

  // --- EXECUTE DELETE (Called from Modal) ---

  const executeDelete = async () => {
    setLoading(true);
    try {
      if (confirmModal.type === 'DELETE_EVENT') {
        await deleteEvent(event.id);
        onDelete(); // Navigates back to dashboard
      } 
      else if (confirmModal.type === 'DELETE_ATTENDEE' && confirmModal.itemId) {
        const updated = await deleteAttendee(event.id, confirmModal.itemId);
        if (updated) onUpdate(updated);
      } 
      else if (confirmModal.type === 'DELETE_EXPENSE' && confirmModal.itemId) {
        const updated = await deleteExpense(event.id, confirmModal.itemId);
        if (updated) onUpdate(updated);
      }
    } finally {
      setLoading(false);
      setConfirmModal({ isOpen: false, type: null, message: '' });
    }
  };

  // --- EXPENSE LOGIC ---

  const handleAddExpense = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    const expense: Expense = {
      id: generateId(),
      description: newExpense.description,
      amount: Number(newExpense.amount)
    };

    try {
      const updated = await addExpense(event.id, expense);
      if (updated) {
        onUpdate(updated);
        setNewExpense({ description: '', amount: '' });
        setShowAddExpense(false);
      }
    } finally {
      setLoading(false);
    }
  };

  const startEditingExpense = (expense: Expense) => {
    setEditingExpenseId(expense.id);
    setEditExpenseData({ 
      description: expense.description, 
      amount: expense.amount.toString() 
    });
  };

  const cancelEditingExpense = () => {
    setEditingExpenseId(null);
    setEditExpenseData({ description: '', amount: '' });
  };

  const saveEditedExpense = async (originalExpense: Expense) => {
    if (!editExpenseData.description || !editExpenseData.amount) return;

    const updatedExpense: Expense = {
      ...originalExpense,
      description: editExpenseData.description,
      amount: Number(editExpenseData.amount)
    };

    setLoading(true);
    try {
      const updatedEvent = await updateExpense(event.id, updatedExpense);
      if (updatedEvent) {
        onUpdate(updatedEvent);
        setEditingExpenseId(null);
      }
    } finally {
      setLoading(false);
    }
  };

  // --- CALCULATIONS ---

  const totalCollected = event.attendees
    .filter(a => a.status === PaymentStatus.PAID)
    .length * event.cost;

  const totalExpenses = (event.expenses || []).reduce((acc, curr) => acc + curr.amount, 0);
  const netProfit = totalCollected - totalExpenses;
  const isProfitPositive = netProfit >= 0;

  const maxAttendees = event.maxAttendees || 0;
  const occupancyPercentage = maxAttendees > 0 
    ? Math.min((event.attendees.length / maxAttendees) * 100, 100) 
    : 0;

  return (
    <div className="space-y-8 animate-fade-in pb-10 relative">

      {loading && (
        <div className="fixed inset-0 z-[60] bg-white/50 backdrop-blur-sm flex items-center justify-center">
          <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-pink-600"></div>
        </div>
      )}

      {/* --- CUSTOM CONFIRMATION MODAL --- */}
      {confirmModal.isOpen && (
        <div className="fixed inset-0 bg-indigo-950/80 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl max-w-sm w-full p-6 animate-scale-in border border-gray-100 transform transition-all">
            <div className="flex flex-col items-center text-center mb-6">
              <div className="w-14 h-14 bg-red-50 rounded-full flex items-center justify-center mb-4 text-red-500 shadow-sm">
                <AlertTriangle className="w-7 h-7" />
              </div>
              <h3 className="text-xl font-bold text-gray-900">Conferma Eliminazione</h3>
              <p className="text-gray-500 mt-2 text-sm leading-relaxed">{confirmModal.message}</p>
            </div>
            <div className="flex gap-3 justify-center">
              <Button 
                variant="secondary" 
                onClick={() => setConfirmModal({ isOpen: false, type: null, message: '' })}
                className="w-full"
              >
                Annulla
              </Button>
              <Button 
                variant="danger" 
                onClick={executeDelete}
                className="w-full shadow-red-200"
                isLoading={loading}
              >
                Elimina
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Header */}
      <div className="flex flex-col lg:flex-row lg:items-center gap-6 justify-between bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
        <div className="flex items-start gap-5">
          <button onClick={onBack} className="p-2.5 bg-gray-50 hover:bg-gray-100 text-gray-600 rounded-xl transition-colors mt-1" type="button">
            <ArrowLeft className="w-5 h-5" />
          </button>
          <div>
            <h1 className="text-3xl font-extrabold text-gray-900 tracking-tight">{event.title}</h1>
            <div className="flex flex-wrap items-center gap-4 mt-2 text-sm text-gray-500 font-medium">
              <span className="flex items-center bg-indigo-50 text-indigo-700 px-3 py-1 rounded-full"><Calendar className="w-3.5 h-3.5 mr-1.5" /> {new Date(event.date).toLocaleDateString('it-IT')}</span>
              <span className="flex items-center bg-gray-100 text-gray-600 px-3 py-1 rounded-full"><MapPin className="w-3.5 h-3.5 mr-1.5" /> {event.location}</span>
            </div>
          </div>
        </div>
        <div className="flex gap-3">
          <Button variant="secondary" onClick={onEditEvent} type="button">
            <Edit2 className="w-4 h-4 mr-2" />
            Modifica
          </Button>
          <Button variant="danger" onClick={requestDeleteEvent} type="button">
            Elimina Evento
          </Button>
        </div>
      </div>

      {/* Stats Overview */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 relative overflow-hidden">
          <div className="absolute top-0 right-0 w-24 h-24 bg-green-50 rounded-bl-full -mr-5 -mt-5"></div>
          <div className="relative">
             <div className="flex items-center gap-3 mb-2">
                <div className="p-2 bg-green-100 text-green-600 rounded-lg shadow-sm">
                  <TrendingUp className="w-5 h-5" />
                </div>
                <p className="text-sm font-semibold text-gray-500 uppercase">Incasso</p>
              </div>
              <p className="text-3xl font-extrabold text-gray-900">€ {totalCollected.toLocaleString('it-IT', { minimumFractionDigits: 2 })}</p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 relative overflow-hidden">
          <div className="absolute top-0 right-0 w-24 h-24 bg-red-50 rounded-bl-full -mr-5 -mt-5"></div>
          <div className="relative">
            <div className="flex items-center gap-3 mb-2">
              <div className="p-2 bg-red-100 text-red-600 rounded-lg shadow-sm">
                <TrendingDown className="w-5 h-5" />
              </div>
              <p className="text-sm font-semibold text-gray-500 uppercase">Spese</p>
            </div>
            <p className="text-3xl font-extrabold text-gray-900">€ {totalExpenses.toLocaleString('it-IT', { minimumFractionDigits: 2 })}</p>
          </div>
        </div>

        <div className={`p-6 rounded-2xl shadow-lg border relative overflow-hidden flex flex-col justify-center ${
            isProfitPositive 
            ? 'bg-indigo-950 border-indigo-900 text-white' 
            : 'bg-red-50 border-red-100 text-red-900'
        }`}>
          {isProfitPositive && (
            <div className="absolute right-0 top-0 w-32 h-32 bg-gradient-to-br from-pink-500 to-purple-600 blur-2xl opacity-20 -mr-10 -mt-10"></div>
          )}
          <div className="relative z-10">
            <div className="flex items-center gap-3 mb-2">
              <div className={`p-2 rounded-lg ${isProfitPositive ? 'bg-white/10 text-pink-400' : 'bg-red-100 text-red-600'}`}>
                <Wallet className="w-5 h-5" />
              </div>
              <p className={`text-sm font-semibold uppercase ${isProfitPositive ? 'text-indigo-200' : 'text-red-700'}`}>Profitto Netto</p>
            </div>
            <p className="text-4xl font-black tracking-tight">€ {netProfit.toLocaleString('it-IT', { minimumFractionDigits: 2 })}</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* LEFT COLUMN: Details & Expenses */}
        <div className="space-y-8">

          {/* Detailed Info Card */}
          <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
            <h3 className="text-lg font-bold text-gray-900 mb-6 flex items-center">
              <span className="w-1.5 h-6 bg-pink-500 rounded-full mr-3"></span>
              Dettagli
            </h3>
            <div className="space-y-5">
              <div className="flex justify-between items-center border-b border-gray-50 pb-3">
                <span className="text-gray-500 text-sm flex items-center gap-2 font-medium"><Clock className="w-4 h-4 text-gray-400" /> Orario</span>
                <span className="font-semibold text-gray-800 bg-gray-50 px-3 py-1 rounded-md">{event.time}</span>
              </div>
              <div className="flex justify-between items-center border-b border-gray-50 pb-3">
                <span className="text-gray-500 text-sm flex items-center gap-2 font-medium"><Euro className="w-4 h-4 text-gray-400" /> Costo Biglietto</span>
                <span className="font-semibold text-gray-800 bg-gray-50 px-3 py-1 rounded-md">€ {event.cost}</span>
              </div>
              <div className="flex justify-between items-center border-b border-gray-50 pb-3">
                <span className="text-gray-500 text-sm flex items-center gap-2 font-medium"><Users className="w-4 h-4 text-gray-400" /> Max Partecipanti</span>
                <span className="font-semibold text-gray-800 bg-gray-50 px-3 py-1 rounded-md">{event.maxAttendees ? event.maxAttendees : '∞'}</span>
              </div>

              <div className="pt-4">
                <div className="flex justify-between text-xs font-bold text-gray-500 uppercase mb-2">
                  <span>Occupazione</span>
                  <span>{Math.round(occupancyPercentage)}%</span>
                </div>
                <div className="w-full bg-gray-100 rounded-full h-3 overflow-hidden">
                  <div 
                    className={`h-3 rounded-full bg-gradient-to-r from-pink-500 to-yellow-400 shadow-sm transition-all duration-500`} 
                    style={{ width: `${occupancyPercentage}%` }}
                  ></div>
                </div>
                <p className="text-xs text-center mt-2 text-gray-400">
                  {event.attendees.length} iscritti su {event.maxAttendees ? event.maxAttendees : 'illimitati'}
                </p>
              </div>
            </div>

            <div className="mt-8">
              <p className="text-sm font-bold text-gray-900 mb-2">Descrizione</p>
              <div className="bg-gray-50 p-4 rounded-xl text-sm text-gray-600 italic border border-gray-100">
                 "{event.description || "Nessuna descrizione inserita."}"
              </div>
            </div>
          </div>

          {/* Expenses Management */}
          <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
