    return event;
  });
};

export const isCloudEnabled = (): boolean => !!localStorage.getItem(FIREBASE_CONFIG_KEY);

import { ViewState, AppEvent, ExtraExpense } from './types';
import { getEvents, saveEvent, isCloudEnabled, getExtraExpenses } from './services/storageService';
import { Dashboard } from './components/Dashboard';
import { EventForm } from './components/EventForm';
import { EventDetails } from './components/EventDetails';
import { Settings } from './components/Settings';
import { ParticipantsList } from './components/ParticipantsList';
import { ParticipantDetails } from './components/ParticipantDetails';
import { LayoutDashboard, Settings as SettingsIcon, Cloud, CloudOff, RefreshCw, Users } from 'lucide-react';
import React, { useEffect, useState } from 'react';

export default function App() {
  const [viewState, setViewState] = useState<ViewState>({ type: 'DASHBOARD' });
  const [events, setEvents] = useState<AppEvent[]>([]);
  const [extraExpenses, setExtraExpenses] = useState<ExtraExpense[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isCloud, setIsCloud] = useState(false);

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = async () => {
    setIsLoading(true);
    setIsCloud(isCloudEnabled());
    try {
      const [eventsData, expensesData] = await Promise.all([
        getEvents(),
        getExtraExpenses()
      ]);
      setEvents(eventsData);
      setExtraExpenses(expensesData);
    } catch (e) {
      console.error("Failed to load data", e);
    } finally {
      setIsLoading(false);
    }
  };

  const navigateToDashboard = () => {
    setViewState({ type: 'DASHBOARD' });
    refreshData();
  };

  const handleEventSaved = async (event: AppEvent) => {
    setIsLoading(true);
    await saveEvent(event);
    setViewState({ type: 'EVENT_DETAILS', eventId: event.id });
    await refreshData();
  };

  const handleEventUpdated = async (updatedEvent: AppEvent) => {
    setEvents(prev => prev.map(e => e.id === updatedEvent.id ? updatedEvent : e));
  };

  const renderContent = () => {
    if (isLoading && events.length === 0) {
      return (
        <div className="flex h-[50vh] items-center justify-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-pink-600"></div>
        </div>
      );
    }

    switch (viewState.type) {
      case 'DASHBOARD':
        return (
          <Dashboard 
            events={events} 
            extraExpenses={extraExpenses}
            onCreateClick={() => setViewState({ type: 'CREATE_EVENT' })}
            onEventClick={(id) => setViewState({ type: 'EVENT_DETAILS', eventId: id })}
            onRefresh={refreshData}
          />
        );

      case 'PARTICIPANTS':
        return (
          <ParticipantsList 
            events={events} 
            onBack={navigateToDashboard} 
            onParticipantClick={(key) => setViewState({ type: 'PARTICIPANT_DETAILS', participantKey: key })}
          />
        );

      case 'PARTICIPANT_DETAILS':
        return (
          <ParticipantDetails 
            participantKey={viewState.participantKey}
            events={events}
            onBack={() => setViewState({ type: 'PARTICIPANTS' })}
            onUpdate={refreshData}
          />
        );

      case 'CREATE_EVENT':
        return <EventForm onSave={handleEventSaved} onCancel={navigateToDashboard} />;

      case 'EDIT_EVENT':
        const eventToEdit = events.find(e => e.id === viewState.eventId);
        if (!eventToEdit) return <div>Evento non trovato</div>;
        return (
          <EventForm
            initialData={eventToEdit}
            onSave={handleEventSaved}
            onCancel={() => setViewState({ type: 'EVENT_DETAILS', eventId: eventToEdit.id })}
          />
        );

      case 'EVENT_DETAILS':
        const event = events.find(e => e.id === viewState.eventId);
        if (!event) return <div>Evento non trovato</div>;
        return (
          <EventDetails 
            event={event} 
            allEvents={events}
            onBack={navigateToDashboard}
            onUpdate={handleEventUpdated}
            onDelete={navigateToDashboard}
            onEditEvent={() => setViewState({ type: 'EDIT_EVENT', eventId: event.id })}
          />
        );

      case 'SETTINGS':
        return <Settings onBack={navigateToDashboard} />;

      default:
        return <div>View not found</div>;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row font-sans">
      <aside className="bg-indigo-950 text-white w-full md:w-64 flex-shrink-0 flex flex-col shadow-2xl z-20 relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none opacity-20">
             <div className="absolute top-[-50px] left-[-50px] w-40 h-40 bg-pink-600 rounded-full blur-[60px]"></div>
        </div>
        <div className="p-6 relative z-10">
          <div className="flex items-center justify-center md:justify-start mb-10 mt-2">
             <div className="relative group cursor-default select-none">
               <div className="absolute -inset-1 bg-gradient-to-r from-pink-500 to-purple-500 rounded-xl blur opacity-40"></div>
               <div className="relative flex items-center bg-indigo-950 border border-indigo-800/50 rounded-xl px-5 py-3 shadow-2xl">
                 <div className="flex flex-col leading-none">
                    <div className="flex items-baseline gap-0.5">
                      <span className="text-2xl font-black text-pink-400">ON</span>
                      <span className="text-2xl font-black text-yellow-400">BEVENTI</span>
                    </div>
                    <span className="text-[0.5rem] font-bold text-indigo-300 uppercase tracking-widest text-right">Event Manager</span>
                 </div>
               </div>
             </div>
          </div>
          <nav className="space-y-3">
            <button 
              onClick={navigateToDashboard}
              className={`w-full flex items-center px-4 py-3.5 rounded-xl transition-all duration-300 font-medium ${
                ['DASHBOARD', 'EVENT_DETAILS', 'CREATE_EVENT', 'EDIT_EVENT'].includes(viewState.type)
                  ? 'bg-gradient-to-r from-pink-600 to-purple-700 text-white shadow-lg border border-pink-500/30' 
                  : 'text-indigo-200 hover:bg-white/5 hover:text-white border border-transparent'
              }`}
            >
              <LayoutDashboard className="w-5 h-5 mr-3" />
              Dashboard
            </button>
            <button 
              onClick={() => setViewState({ type: 'PARTICIPANTS' })}
              className={`w-full flex items-center px-4 py-3.5 rounded-xl transition-all duration-300 font-medium ${
                ['PARTICIPANTS', 'PARTICIPANT_DETAILS'].includes(viewState.type)
                  ? 'bg-gradient-to-r from-pink-600 to-purple-700 text-white shadow-lg border border-pink-500/30' 
                  : 'text-indigo-200 hover:bg-white/5 hover:text-white border border-transparent'
              }`}
            >
              <Users className="w-5 h-5 mr-3" />
              Partecipanti
            </button>
            <button 
              onClick={() => setViewState({ type: 'SETTINGS' })}
              className={`w-full flex items-center px-4 py-3.5 rounded-xl transition-all duration-300 font-medium ${
                viewState.type === 'SETTINGS' 
                  ? 'bg-gradient-to-r from-pink-600 to-purple-700 text-white shadow-lg border border-pink-500/30' 
                  : 'text-indigo-200 hover:bg-white/5 hover:text-white border border-transparent'
              }`}
            >
              <SettingsIcon className="w-5 h-5 mr-3" />
              Impostazioni
            </button>
          </nav>
        </div>
        <div className="p-6 mt-auto relative z-10">
          <div className="bg-indigo-900/40 border border-indigo-800/50 rounded-xl p-4 backdrop-blur-sm">
            <div className="flex items-center justify-between mb-2">
               <p className="text-[10px] text-indigo-300 font-bold uppercase tracking-wider">Sync Status</p>
               {isCloud ? <Cloud className="w-3 h-3 text-green-400" /> : <CloudOff className="w-3 h-3 text-gray-400" />}
            </div>
            <div className="text-[10px] text-indigo-200 font-medium flex items-center justify-between">
               {isCloud ? 'Cloud Sync' : 'Local Only'}
               <button onClick={refreshData} className="hover:text-white transition-colors">
                 <RefreshCw className={`w-3 h-3 ${isLoading ? 'animate-spin' : ''}`} />
               </button>
            </div>
          </div>
        </div>
      </aside>
      <main className="flex-1 p-4 md:p-8 overflow-y-auto h-screen bg-slate-50/50">
        <div className="max-w-7xl mx-auto pb-10">
          {renderContent()}
        </div>
      </main>
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { AppEvent, Attendee } from '../types';
import { Users, Search, Mail, Phone, ArrowLeft, SortAsc, SortDesc } from 'lucide-react';

interface ParticipantsListProps {
  events: AppEvent[];
  onBack: () => void;
  onParticipantClick: (key: string) => void;
}

type SortKey = 'name' | 'eventsCount';
type SortOrder = 'asc' | 'desc';

export const ParticipantsList: React.FC<ParticipantsListProps> = ({ events, onBack, onParticipantClick }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [sortKey, setSortKey] = useState<SortKey>('name');
  const [sortOrder, setSortOrder] = useState<SortOrder>('asc');

  const globalAttendees = useMemo(() => {
    const map = new Map<string, { attendee: Attendee, eventsCount: number, eventTitles: string[], key: string }>();

    (events || []).forEach(event => {
      (event.attendees || []).forEach(a => {
        const key = (a.email || a.phone || a.name).toLowerCase().trim();

        if (map.has(key)) {
          const existing = map.get(key)!;
          existing.eventsCount += 1;
          existing.eventTitles.push(event.title);
        } else {
          map.set(key, {
            attendee: a,
            eventsCount: 1,
            eventTitles: [event.title],
            key: key
          });
        }
      });
    });

    let list = Array.from(map.values());

    if (searchTerm) {
      const lowerSearch = searchTerm.toLowerCase();
      list = list.filter(item => 
        item.attendee.name.toLowerCase().includes(lowerSearch) ||
        (item.attendee.email && item.attendee.email.toLowerCase().includes(lowerSearch)) ||
        (item.attendee.phone && item.attendee.phone.includes(searchTerm))
      );
    }

    list.sort((a, b) => {
      if (sortKey === 'name') {
        const comparison = a.attendee.name.localeCompare(b.attendee.name);
        return sortOrder === 'asc' ? comparison : -comparison;
      } else {
        const comparison = a.eventsCount - b.eventsCount;
        return sortOrder === 'asc' ? comparison : -comparison;
      }
    });

    return list;
  }, [events, searchTerm, sortKey, sortOrder]);

  const toggleSort = (key: SortKey) => {
    if (sortKey === key) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortKey(key);
      setSortOrder(key === 'eventsCount' ? 'desc' : 'asc');
    }
  };

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex flex-col lg:flex-row justify-between items-stretch lg:items-center gap-4 bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="p-2.5 bg-gray-50 hover:bg-gray-100 rounded-xl transition-colors border border-gray-100">
            <ArrowLeft className="w-5 h-5 text-gray-500" />
          </button>
          <div>
            <h1 className="text-2xl font-extrabold text-gray-900">Anagrafica Partecipanti</h1>
            <p className="text-sm text-gray-500">Gestione centralizzata di tutti i tuoi iscritti.</p>
          </div>
        </div>

        <div className="flex flex-col sm:flex-row gap-3">
          <div className="relative flex-1 sm:w-80">
            <Search className="absolute left-3.5 top-3 w-4 h-4 text-gray-400" />
            <input 
              type="text"
              placeholder="Cerca nome, email o telefono..."
              className="w-full pl-11 pr-4 py-2.5 border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-pink-500 shadow-sm transition-all"
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>

          <div className="flex bg-gray-50 p-1 rounded-xl border border-gray-200">
            <button 
              onClick={() => toggleSort('name')}
              className={`flex items-center gap-2 px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${sortKey === 'name' ? 'bg-white text-indigo-950 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
            >
              Nome {sortKey === 'name' && (sortOrder === 'asc' ? <SortAsc className="w-3.5 h-3.5" /> : <SortDesc className="w-3.5 h-3.5" />)}
            </button>
            <button 
              onClick={() => toggleSort('eventsCount')}
              className={`flex items-center gap-2 px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${sortKey === 'eventsCount' ? 'bg-white text-indigo-950 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
            >
              Eventi {sortKey === 'eventsCount' && (sortOrder === 'asc' ? <SortAsc className="w-3.5 h-3.5" /> : <SortDesc className="w-3.5 h-3.5" />)}
            </button>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-indigo-950 text-white text-[11px] font-bold uppercase tracking-wider">
                <th className="px-6 py-4 cursor-pointer hover:bg-indigo-900 transition-colors" onClick={() => toggleSort('name')}>
                  <div className="flex items-center gap-2">
                    Partecipante {sortKey === 'name' && (sortOrder === 'asc' ? <SortAsc className="w-3 h-3 opacity-60" /> : <SortDesc className="w-3 h-3 opacity-60" />)}
                  </div>
                </th>
                <th className="px-6 py-4">Contatti</th>
                <th className="px-6 py-4 text-center cursor-pointer hover:bg-indigo-900 transition-colors" onClick={() => toggleSort('eventsCount')}>
                  <div className="flex items-center justify-center gap-2">
                    Eventi Totali {sortKey === 'eventsCount' && (sortOrder === 'asc' ? <SortAsc className="w-3 h-3 opacity-60" /> : <SortDesc className="w-3 h-3 opacity-60" />)}
                  </div>
                </th>
                <th className="px-6 py-4">Ultimi Eventi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {globalAttendees.length === 0 ? (
                <tr>
                  <td colSpan={4} className="px-6 py-24 text-center text-gray-400 italic">
                    <div className="flex flex-col items-center gap-3">
                      <div className="p-4 bg-gray-50 rounded-full"><Users className="w-8 h-8 opacity-20" /></div>
                      <p>Nessun partecipante trovato.</p>
                    </div>
                  </td>
                </tr>
              ) : (
                globalAttendees.map((item, idx) => (
                  <tr 
                    key={idx} 
                    className="hover:bg-pink-50/30 transition-colors group cursor-pointer"
                    onClick={() => onParticipantClick(item.key)}
                  >
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <div className="w-9 h-9 rounded-xl bg-gradient-to-br from-pink-100 to-indigo-100 text-pink-700 flex items-center justify-center font-bold text-sm shadow-sm group-hover:scale-110 transition-transform">
                          {item.attendee.name.charAt(0).toUpperCase()}
                        </div>
                        <span className="font-bold text-gray-900 group-hover:text-pink-600 transition-colors">{item.attendee.name}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="space-y-1.5">
                        {item.attendee.email && (
                          <div className="flex items-center text-xs text-gray-500">
                            <Mail className="w-3.5 h-3.5 mr-2 text-indigo-300" /> {item.attendee.email}
                          </div>
                        )}
                        {item.attendee.phone && (
                          <div className="flex items-center text-xs text-gray-500">
                            <Phone className="w-3.5 h-3.5 mr-2 text-indigo-300" /> {item.attendee.phone}
                          </div>
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-4 text-center">
                      <span className="inline-block bg-indigo-50 text-indigo-700 px-4 py-1.5 rounded-full text-xs font-black border border-indigo-100 min-w-[3rem]">
                        {item.eventsCount}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex flex-wrap gap-1.5 max-w-sm">
                        {item.eventTitles.slice(-2).map((t, i) => (
                          <span key={i} className="text-[10px] bg-white text-gray-600 px-2.5 py-1 rounded-md border border-gray-200 shadow-sm">
                            {t}
                          </span>
                        ))}
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { AppEvent, Attendee, PaymentStatus } from '../types';
import { Button } from './Button';
import { 
  ArrowLeft, Edit2, Save, X, Mail, Phone, Calendar, 
  MessageCircle, ExternalLink, Trophy, History, Wallet, 
  User, CheckCircle, Clock, Tag, Briefcase
} from 'lucide-react';
import { updateParticipantGlobally } from '../services/storageService';

interface ParticipantDetailsProps {
  participantKey: string;
  events: AppEvent[];
  onBack: () => void;
  onUpdate: () => void;
}

export const ParticipantDetails: React.FC<ParticipantDetailsProps> = ({ participantKey, events, onBack, onUpdate }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [loading, setLoading] = useState(false);

  // Analisi dati partecipante
  const data = useMemo(() => {
    let baseAttendee: Attendee | null = null;
    let totalPaid = 0;
    const history: { event: AppEvent, attendeeData: Attendee }[] = [];

    events.forEach(event => {
      const attendee = event.attendees.find(a => 
        (a.email || a.phone || a.name).toLowerCase().trim() === participantKey
      );

      if (attendee) {
        if (!baseAttendee) baseAttendee = attendee;
        history.push({ event, attendeeData: attendee });

        if (attendee.status === PaymentStatus.PAID) {
          totalPaid += (attendee.paidAmount !== undefined ? attendee.paidAmount : event.cost);
        }
      }
    });

    // Ordina storia per data evento (più recenti prima)
    history.sort((a, b) => new Date(b.event.date).getTime() - new Date(a.event.date).getTime());

    return { baseAttendee, totalPaid, history };
  }, [events, participantKey]);

  const [formData, setFormData] = useState({
    name: data.baseAttendee?.name || '',
    email: data.baseAttendee?.email || '',
    phone: data.baseAttendee?.phone || ''
  });

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      await updateParticipantGlobally(participantKey, formData);
      setIsEditing(false);
      onUpdate();
    } finally {
      setLoading(false);
    }
  };

  if (!data.baseAttendee) return <div className="p-8 text-center text-gray-500">Partecipante non trovato.</div>;

  const isVip = data.history.length >= 5;
  const isRegular = data.history.length >= 3;

  return (
    <div className="space-y-8 animate-fade-in pb-10">
      {/* Header & Navigation */}
      <div className="flex items-center justify-between bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="p-2.5 bg-gray-50 hover:bg-gray-100 rounded-xl transition-colors border border-gray-100">
            <ArrowLeft className="w-5 h-5 text-gray-500" />
          </button>
          <div>
            <h1 className="text-2xl font-black text-gray-900 leading-tight">Scheda Partecipante</h1>
            <p className="text-sm text-gray-500 font-medium">Gestione anagrafica e storico partecipazioni.</p>
          </div>
        </div>
        <div className="flex gap-2">
           {!isEditing ? (
             <Button variant="secondary" onClick={() => setIsEditing(true)}>
               <Edit2 className="w-4 h-4 mr-2" /> Modifica Anagrafica
             </Button>
           ) : (
             <div className="flex gap-2">
                <Button variant="ghost" onClick={() => setIsEditing(false)}>Annulla</Button>
                <Button onClick={handleSave} isLoading={loading}>
                   <Save className="w-4 h-4 mr-2" /> Salva Modifiche
                </Button>
             </div>
           )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* Profile Card & Info */}
        <div className="space-y-6">
          <div className="bg-white p-8 rounded-3xl shadow-sm border border-gray-100 text-center relative overflow-hidden group">
            {/* Background pattern */}
            <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-pink-500 to-indigo-600"></div>

            <div className="w-24 h-24 mx-auto rounded-3xl bg-gradient-to-br from-indigo-50 to-pink-50 flex items-center justify-center text-4xl font-black text-indigo-600 border-4 border-white shadow-xl mb-6 relative z-10">
              {data.baseAttendee.name.charAt(0).toUpperCase()}
              {isVip && (
                <div className="absolute -top-2 -right-2 bg-yellow-400 p-1.5 rounded-full border-2 border-white shadow-sm" title="VIP">
                  <Trophy className="w-4 h-4 text-white" />
                </div>
              )}
            </div>

            {isEditing ? (
              <form onSubmit={handleSave} className="space-y-4 text-left">
                <div>
                  <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Nome Completo</label>
                  <input 
                    className="w-full mt-1 px-4 py-2 bg-gray-50 border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-pink-500"
                    value={formData.name}
