                </div>
              </form>
            ) : (
              <>
                <h2 className="text-2xl font-extrabold text-gray-900 mb-2">{data.baseAttendee.name}</h2>
                <div className="flex flex-wrap justify-center gap-2 mb-8">
                  {isVip ? (
