                      <Trophy className="w-3 h-3 mr-1" /> VIP Platinum
                    </span>
                  ) : isRegular ? (
                    <span className="bg-green-100 text-green-700 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider">
                      Fedele
                    </span>
                  ) : (
                    <span className="bg-gray-100 text-gray-500 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider">
                      Nuovo Iscritto
                    </span>
                  )}
                </div>

                <div className="space-y-3 pt-4 border-t border-gray-50">
                  <div className="flex items-center p-3 rounded-2xl bg-gray-50">
                    <Mail className="w-4 h-4 text-gray-400 mr-3" />
                    <div className="text-left flex-1">
                      <p className="text-[10px] font-bold text-gray-400 uppercase">Email</p>
                      <p className="text-sm font-semibold text-gray-700 truncate">{data.baseAttendee.email || '-'}</p>
                    </div>
                  </div>
                  <div className="flex items-center p-3 rounded-2xl bg-gray-50">
                    <Phone className="w-4 h-4 text-gray-400 mr-3" />
                    <div className="text-left flex-1">
                      <p className="text-[10px] font-bold text-gray-400 uppercase">Telefono</p>
                      <p className="text-sm font-semibold text-gray-700">{data.baseAttendee.phone || '-'}</p>
                    </div>
                    {data.baseAttendee.phone && (
                      <a href={`https://wa.me/${data.baseAttendee.phone.replace(/\D/g, '')}`} target="_blank" className="p-2 text-green-500 hover:bg-green-100 rounded-lg">
                        <MessageCircle className="w-4 h-4" />
