import React, { useState, useMemo, useEffect } from 'react';
import { AppEvent, Attendee, PaymentStatus } from '../types';
import { Button } from './Button';
import { 
  ArrowLeft, Edit2, Save, X, Mail, Phone, Calendar, 
  MessageCircle, ExternalLink, Trophy, History, Wallet, 
  CheckCircle, Clock, Tag, Briefcase, Download, User
} from 'lucide-react';
import { updateParticipantGlobally } from '../services/storageService';

interface ParticipantDetailsProps {
  participantKey: string;
  events: AppEvent[];
  onBack: () => void;
  onUpdate: () => void;
}

interface ParticipantSummary {
  baseAttendee: Attendee | null;
  totalPaid: number;
  history: { event: AppEvent; attendeeData: Attendee }[];
  lastSeen: string | null;
}

export const ParticipantDetails: React.FC<ParticipantDetailsProps> = ({ participantKey, events, onBack, onUpdate }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({ name: '', email: '', phone: '' });

  // Caricamento soglie fedeltà dalle impostazioni
  const vipThreshold = Number(localStorage.getItem('onbeventi_vip_threshold') || '5');
  const regularThreshold = Number(localStorage.getItem('onbeventi_regular_threshold') || '3');

  // Analisi dati partecipante con tipizzazione esplicita per evitare errori TS
  const data = useMemo<ParticipantSummary>(() => {
    let baseAttendee: Attendee | null = null;
    let totalPaid = 0;
    const history: { event: AppEvent; attendeeData: Attendee }[] = [];

    (events || []).forEach(event => {
      const attendee = (event.attendees || []).find(a => 
        (a.email || a.phone || a.name).toLowerCase().trim() === participantKey
      );

      if (attendee) {
        if (!baseAttendee) baseAttendee = attendee;
        history.push({ event, attendeeData: attendee });

        if (attendee.status === PaymentStatus.PAID) {
          totalPaid += (attendee.paidAmount !== undefined ? attendee.paidAmount : event.cost);
        }
      }
    });

    history.sort((a, b) => new Date(b.event.date).getTime() - new Date(a.event.date).getTime());
    const lastSeen = history.length > 0 ? history[0].event.date : null;

    return { baseAttendee, totalPaid, history, lastSeen };
  }, [events, participantKey]);

  // Sincronizza il form quando i dati di base cambiano
  useEffect(() => {
    if (data.baseAttendee) {
      setFormData({
        name: data.baseAttendee.name || '',
        email: data.baseAttendee.email || '',
        phone: data.baseAttendee.phone || ''
      });
    }
  }, [data.baseAttendee]);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;
    setLoading(true);
    try {
      await updateParticipantGlobally(participantKey, formData);
      setIsEditing(false);
      onUpdate();
    } catch (err) {
      console.error("Errore durante l'aggiornamento globale:", err);
      alert("Errore durante l'aggiornamento. Riprova.");
    } finally {
      setLoading(false);
    }
  };

  const handleExportVCard = () => {
    if (!data.baseAttendee) return;
    const { name, email, phone } = formData;
    const vcard = `BEGIN:VCARD
VERSION:3.0
FN:${name}
TEL;TYPE=CELL:${phone}
EMAIL:${email}
ORG:ONBEVENTI CRM
NOTE:Partecipazioni totali: ${data.history.length}
END:VCARD`;

    const blob = new Blob([vcard], { type: 'text/vcard' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${name.replace(/\s+/g, '_')}_Contatto.vcf`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  if (!data.baseAttendee) {
    return (
      <div className="p-12 text-center">
        <div className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100 max-w-md mx-auto">
          <User className="w-12 h-12 text-gray-200 mx-auto mb-4" />
          <p className="text-gray-500 font-medium">Membro non trovato nel database.</p>
          <Button onClick={onBack} variant="secondary" className="mt-4">Torna alla lista</Button>
        </div>
      </div>
    );
  }

  const isVip = data.history.length >= vipThreshold;
  const isRegular = data.history.length >= regularThreshold;

  return (
    <div className="space-y-8 animate-fade-in pb-12">
      {/* Navbar Scheda */}
      <div className="flex flex-col md:flex-row md:items-center justify-between bg-white p-6 rounded-2xl shadow-sm border border-gray-100 gap-4">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="p-2.5 bg-gray-50 hover:bg-gray-100 rounded-xl transition-colors border border-gray-100">
            <ArrowLeft className="w-5 h-5 text-gray-500" />
          </button>
          <div>
            <h1 className="text-2xl font-black text-gray-900 leading-tight">Profilo Membro</h1>
            <p className="text-xs text-indigo-500 font-bold uppercase tracking-wider">ONBEVENTI Community System</p>
          </div>
        </div>
        <div className="flex gap-2">
           {!isEditing ? (
             <>
               <Button variant="secondary" onClick={handleExportVCard} title="Esporta in rubrica">
                 <Download className="w-4 h-4 mr-2" /> VCard
               </Button>
               <Button onClick={() => setIsEditing(true)}>
                 <Edit2 className="w-4 h-4 mr-2" /> Modifica Dati
               </Button>
             </>
           ) : (
             <div className="flex gap-2">
                <Button variant="ghost" onClick={() => setIsEditing(false)}>Annulla</Button>
                <Button onClick={handleSave} isLoading={loading}>
                   <Save className="w-4 h-4 mr-2" /> Aggiorna Ovunque
                </Button>
             </div>
           )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Colonna Sinistra: Profilo & Info */}
        <div className="space-y-6">
          <div className="bg-white p-8 rounded-3xl shadow-sm border border-gray-100 text-center relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-pink-500 to-indigo-600"></div>

            <div className="w-24 h-24 mx-auto rounded-3xl bg-indigo-50 flex items-center justify-center text-4xl font-black text-indigo-600 border-4 border-white shadow-xl mb-6 relative">
              {formData.name.charAt(0).toUpperCase()}
              {isVip && (
                <div className="absolute -top-3 -right-3 bg-yellow-400 p-2 rounded-full border-4 border-white shadow-lg">
                  <Trophy className="w-5 h-5 text-white" />
                </div>
              )}
            </div>

            {isEditing ? (
              <form onSubmit={handleSave} className="space-y-4 text-left">
                <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Nome Completo</label>
                  <input 
                    className="w-full mt-1 px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl text-sm focus:ring-2 focus:ring-pink-500 outline-none" 
                    value={formData.name} 
                    onChange={e => setFormData(p => ({...p, name: e.target.value}))} 
                    required 
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Email</label>
                  <input 
                    type="email" 
                    className="w-full mt-1 px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl text-sm focus:ring-2 focus:ring-pink-500 outline-none" 
                    value={formData.email} 
                    onChange={e => setFormData(p => ({...p, email: e.target.value}))} 
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Telefono</label>
                  <input 
                    type="tel" 
                    className="w-full mt-1 px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl text-sm focus:ring-2 focus:ring-pink-500 outline-none" 
                    value={formData.phone} 
                    onChange={e => setFormData(p => ({...p, phone: e.target.value}))} 
                  />
                </div>
              </form>
            ) : (
              <>
                <h2 className="text-2xl font-black text-gray-900 mb-1">{formData.name}</h2>
                <div className="flex flex-wrap justify-center gap-2 mb-8">
                  {isVip ? (
                    <span className="bg-yellow-100 text-yellow-700 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider flex items-center shadow-sm">
                      <Trophy className="w-3 h-3 mr-1" /> VIP Platinum
                    </span>
                  ) : isRegular ? (
                    <span className="bg-green-100 text-green-700 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider shadow-sm">
                      Membro Fedele
                    </span>
                  ) : (
                    <span className="bg-gray-100 text-gray-500 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider shadow-sm">
                      Nuovo Iscritto
                    </span>
                  )}
                </div>

                <div className="space-y-3 pt-6 border-t border-gray-50">
                  <div className="flex items-center p-3 rounded-2xl bg-gray-50 hover:bg-gray-100 transition-colors group">
                    <Mail className="w-4 h-4 text-gray-400 mr-3" />
                    <div className="text-left flex-1">
                      <p className="text-[10px] font-black text-gray-400 uppercase">Email</p>
                      <p className="text-sm font-bold text-gray-700 truncate">{formData.email || '-'}</p>
                    </div>
                    {formData.email && (
                      <a href={`mailto:${formData.email}`} className="opacity-0 group-hover:opacity-100 p-2 text-indigo-500 transition-opacity">
                        <ExternalLink className="w-4 h-4" />
                      </a>
                    )}
                  </div>
                  <div className="flex items-center p-3 rounded-2xl bg-gray-50 hover:bg-gray-100 transition-colors group">
                    <Phone className="w-4 h-4 text-gray-400 mr-3" />
                    <div className="text-left flex-1">
                      <p className="text-[10px] font-black text-gray-400 uppercase">Telefono</p>
                      <p className="text-sm font-bold text-gray-700">{formData.phone || '-'}</p>
                    </div>
                    {formData.phone && (
                      <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        <a href={`tel:${formData.phone}`} className="p-2 text-indigo-500">
                          <Phone className="w-4 h-4" />
                        </a>
                        <a 
                          href={`https://wa.me/${formData.phone.replace(/\D/g, '')}`} 
                          target="_blank" 
                          rel="noopener noreferrer" 
                          className="p-2 text-green-500"
                        >
                          <MessageCircle className="w-4 h-4" />
                        </a>
                      </div>
                    )}
                  </div>
                </div>
              </>
            )}
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="bg-white p-5 rounded-3xl border border-gray-100 shadow-sm relative overflow-hidden group">
              <div className="absolute top-0 right-0 w-8 h-8 bg-pink-50 rounded-bl-full group-hover:w-12 group-hover:h-12 transition-all"></div>
              <p className="text-[10px] font-black text-gray-400 uppercase mb-1">Totale Versato</p>
              <p className="text-2xl font-black text-pink-600">€{data.totalPaid.toFixed(2)}</p>
            </div>
            <div className="bg-white p-5 rounded-3xl border border-gray-100 shadow-sm relative overflow-hidden group">
              <div className="absolute top-0 right-0 w-8 h-8 bg-indigo-50 rounded-bl-full group-hover:w-12 group-hover:h-12 transition-all"></div>
              <p className="text-[10px] font-black text-gray-400 uppercase mb-1">Eventi</p>
              <p className="text-2xl font-black text-indigo-600">{data.history.length}</p>
            </div>
          </div>

          {data.lastSeen && (
            <div className="bg-indigo-950 p-6 rounded-3xl text-white shadow-xl relative overflow-hidden">
               <Calendar className="absolute -bottom-2 -right-2 w-16 h-16 text-white/5" />
               <p className="text-[10px] font-black text-indigo-300 uppercase tracking-widest mb-1">Ultima Presenza</p>
               <p className="text-lg font-bold">{new Date(data.lastSeen).toLocaleDateString('it-IT', { day: 'numeric', month: 'long', year: 'numeric' })}</p>
            </div>
          )}
        </div>

        {/* Colonna Destra: Storico Eventi */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden flex flex-col h-full">
            <div className="px-6 py-5 border-b border-gray-100 bg-gray-50/50 flex justify-between items-center">
              <h3 className="font-black text-gray-900 flex items-center gap-2">
                <History className="w-5 h-5 text-pink-500" />
                Storico Partecipazioni
              </h3>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead className="bg-indigo-950 text-white text-[10px] font-bold uppercase tracking-wider">
                  <tr>
                    <th className="px-6 py-4">Evento</th>
                    <th className="px-6 py-4">Data</th>
                    <th className="px-6 py-4 text-center">Stato Pagamento</th>
                    <th className="px-6 py-4 text-right">Quota</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                  {data.history.length === 0 ? (
                    <tr>
                      <td colSpan={4} className="px-6 py-12 text-center text-gray-400 italic">
                        Nessuna attività registrata per questo membro.
                      </td>
                    </tr>
                  ) : (
                    data.history.map(({ event, attendeeData }) => {
                      const isPaid = attendeeData.status === PaymentStatus.PAID;
                      const amount = attendeeData.paidAmount !== undefined ? attendeeData.paidAmount : event.cost;
                      return (
                        <tr key={event.id} className="hover:bg-gray-50 transition-colors group">
                          <td className="px-6 py-4">
                            <div className="flex flex-col">
                              <span className="font-bold text-gray-900 text-sm group-hover:text-indigo-600 transition-colors">{event.title}</span>
                              <div className="text-[10px] text-gray-400 flex items-center gap-1 mt-0.5">
                                <Briefcase className="w-3 h-3" /> {event.location}
                              </div>
                            </div>
                          </td>
                          <td className="px-6 py-4 text-xs font-medium text-gray-600">
                            {new Date(event.date).toLocaleDateString('it-IT')}
                          </td>
                          <td className="px-6 py-4 text-center">
                            <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-[9px] font-black uppercase tracking-wider shadow-sm ${
                              isPaid ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-700'
                            }`}>
                              {isPaid ? <CheckCircle className="w-3 h-3 mr-1" /> : <Clock className="w-3 h-3 mr-1" />}
                              {isPaid ? 'Pagato' : 'Sospeso'}
                            </span>
                          </td>
                          <td className="px-6 py-4 text-right font-black text-sm">
                            € {amount.toFixed(2)}
                          </td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>

            <div className="p-6 bg-gray-50 border-t border-gray-100 mt-auto flex justify-between items-center">
              <div className="flex items-center gap-2">
                 <Tag className="w-4 h-4 text-pink-500" />
                 <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Resoconto Finanziario Personale</span>
              </div>
              <div className="text-right">
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-wider">Contributo Reale</p>
                <p className="text-xl font-black text-gray-900">€ {data.totalPaid.toFixed(2)}</p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Button } from './Button';
import { Save, ArrowLeft, ShieldCheck, Database, Trophy, Settings as SettingsIcon, AlertCircle, CheckCircle } from 'lucide-react';

interface SettingsProps {
  onBack: () => void;
}

export const Settings: React.FC<SettingsProps> = ({ onBack }) => {
  const [firebaseConfig, setFirebaseConfig] = useState('');
  const [vipThreshold, setVipThreshold] = useState('5');
  const [regularThreshold, setRegularThreshold] = useState('3');
  const [saved, setSaved] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const existingFirebase = localStorage.getItem('onbeventi_firebase_config');
    if (existingFirebase) setFirebaseConfig(existingFirebase);

    const existingVip = localStorage.getItem('onbeventi_vip_threshold');
    if (existingVip) setVipThreshold(existingVip);

    const existingRegular = localStorage.getItem('onbeventi_regular_threshold');
    if (existingRegular) setRegularThreshold(existingRegular);
  }, []);

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    if (Number(vipThreshold) <= Number(regularThreshold)) {
      setError("La soglia VIP deve essere superiore alla soglia Membro Fedele.");
      return;
    }

    localStorage.setItem('onbeventi_vip_threshold', vipThreshold);
    localStorage.setItem('onbeventi_regular_threshold', regularThreshold);

    const configInput = firebaseConfig.trim();
    if (configInput) {
      try {
        const parsed = JSON.parse(configInput);
        if (parsed.apiKey) {
           localStorage.setItem('onbeventi_firebase_config', JSON.stringify(parsed, null, 2));
        } else {
          // Robust parsing fallback (similar to your existing logic)
          const extractedConfig: Record<string, string> = {};
          ['apiKey', 'authDomain', 'projectId', 'storageBucket', 'messagingSenderId', 'appId'].forEach(key => {
            const regex = new RegExp(`(?:["']?)${key}(?:["']?)\\s*:\\s*(["'])(.*?)\\1`);
            const match = configInput.match(regex);
            if (match && match[2]) extractedConfig[key] = match[2];
          });
          if (extractedConfig.apiKey) localStorage.setItem('onbeventi_firebase_config', JSON.stringify(extractedConfig));
        }
      } catch (err) {
        // Just save as text if parsing fails (fallback)
        localStorage.setItem('onbeventi_firebase_config', configInput);
      }
    } else {
      localStorage.removeItem('onbeventi_firebase_config');
    }

    setSaved(true);
    setTimeout(() => {
      setSaved(false);
      window.location.reload();
    }, 1000);
  };

  return (
    <div className="max-w-2xl mx-auto animate-fade-in pb-10">
      <button onClick={onBack} className="mb-6 flex items-center text-sm text-gray-500 hover:text-pink-600 transition-colors font-medium">
        <ArrowLeft className="w-4 h-4 mr-1" />
        Dashboard
      </button>

      <div className="bg-white rounded-2xl shadow-xl border border-gray-100 overflow-hidden">
        <div className="px-8 py-6 border-b border-gray-100 bg-gray-50/50">
          <h2 className="text-2xl font-black text-gray-900 flex items-center gap-2">
            <SettingsIcon className="w-6 h-6 text-pink-500" />
            Configurazione
          </h2>
          <p className="text-gray-500 text-sm mt-1">Personalizza l'app e gestisci le integrazioni cloud.</p>
        </div>

        <form onSubmit={handleSave} className="p-8 space-y-8">
          {error && (
            <div className="bg-red-50 border border-red-100 text-red-700 px-4 py-3 rounded-xl flex items-center gap-3 animate-shake">
              <AlertCircle className="w-5 h-5 shrink-0" />
              <p className="text-sm font-bold">{error}</p>
            </div>
          )}

          <div className="space-y-4">
             <div className="flex items-center justify-between">
                <h3 className="text-sm font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                    <Trophy className="w-4 h-4 text-yellow-500" /> Loyalty Badges System
                </h3>
             </div>
             <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="bg-gray-50 p-4 rounded-xl border border-gray-100">
                  <label className="block text-xs font-black text-gray-500 uppercase mb-2">Soglia VIP (Presenze)</label>
                  <input 
                    type="number" 
                    value={vipThreshold} 
                    onChange={e => setVipThreshold(e.target.value)} 
                    className="w-full px-4 py-2 bg-white border border-gray-200 rounded-lg text-sm font-bold focus:ring-2 focus:ring-pink-500 outline-none transition-all" 
                  />
                  <p className="text-[10px] text-gray-400 mt-2">Badge "VIP Platinum" assegnato ai membri con questo numero di presenze.</p>
                </div>
                <div className="bg-gray-50 p-4 rounded-xl border border-gray-100">
                  <label className="block text-xs font-black text-gray-500 uppercase mb-2">Soglia Fedeltà (Presenze)</label>
                  <input 
                    type="number" 
                    value={regularThreshold} 
                    onChange={e => setRegularThreshold(e.target.value)} 
                    className="w-full px-4 py-2 bg-white border border-gray-200 rounded-lg text-sm font-bold focus:ring-2 focus:ring-pink-500 outline-none transition-all" 
                  />
                  <p className="text-[10px] text-gray-400 mt-2">Badge "Membro Fedele" assegnato ai membri più regolari.</p>
                </div>
             </div>
          </div>

          <div className="space-y-4">
             <h3 className="text-sm font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                <Database className="w-4 h-4 text-indigo-600" /> Firebase Cloud Sync
             </h3>
             <textarea 
               value={firebaseConfig} 
               onChange={(e) => setFirebaseConfig(e.target.value)} 
               rows={6} 
               placeholder='{ "apiKey": "...", "projectId": "...", ... }'
               className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl text-xs font-mono focus:ring-2 focus:ring-pink-500 outline-none transition-all" 
             />
             <p className="text-xs text-gray-400">Incolla qui l'oggetto di configurazione del tuo progetto Firebase per sincronizzare i dati della tua community.</p>
          </div>

          <div className="flex items-center justify-between pt-4">
            {saved && (
              <span className="flex items-center gap-2 text-green-600 text-sm font-black animate-bounce">
                <CheckCircle className="w-4 h-4" /> Salvato!
              </span>
            )}
            <Button type="submit" className="ml-auto shadow-xl shadow-pink-200">
              <Save className="w-4 h-4 mr-2" /> Salva Configurazione
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
};

export enum PaymentStatus {
  PENDING = 'PENDING',
  PAID = 'PAID',
}

export interface Attendee {
  id: string;
  name: string;
  email?: string;
  phone?: string;
  status: PaymentStatus;
  registrationDate: string;
  paidAmount?: number; // Quota effettivamente pagata (se diversa dal costo evento)
  isPresent?: boolean; // Se il membro ha effettivamente partecipato (default: true)
}

export interface Expense {
  id: string;
  description: string;
  amount: number;
}

export interface ExtraExpense {
  id: string;
  description: string;
  amount: number;
  date: string;
}

export interface AppEvent {
  id: string;
  title: string;
  description: string;
  date: string;
  time: string;
  location: string;
  cost: number; // Ticket price per person
  maxAttendees?: number; // Optional capacity limit
  expenses: Expense[]; // List of operational costs
  attendees: Attendee[];
  createdAt: string;
}

export type ViewState = 
  | { type: 'DASHBOARD' }
  | { type: 'CREATE_EVENT' }
  | { type: 'EDIT_EVENT'; eventId: string }
  | { type: 'EVENT_DETAILS'; eventId: string }
  | { type: 'SETTINGS' }
  | { type: 'PARTICIPANTS' }
  | { type: 'PARTICIPANT_DETAILS'; participantKey: string };

import React, { useState, useMemo } from 'react';
import { AppEvent, Attendee, Expense, PaymentStatus } from '../types';
import { Button } from './Button';
import { 
  ArrowLeft, UserPlus, CheckCircle, XCircle, Trash2, 
  Calendar, MapPin, Euro, Clock, Edit2, Plus, 
  TrendingUp, TrendingDown, Wallet, Users, Save, X, AlertTriangle, Phone, Mail, UserCheck, Tag, UserMinus, UserX
} from 'lucide-react';
import { 
  addAttendee, togglePaymentStatus, deleteAttendee, 
  deleteEvent, addExpense, deleteExpense, updateAttendee, updateExpense, generateId
} from '../services/storageService';

interface EventDetailsProps {
  event: AppEvent;
  allEvents: AppEvent[];
  onBack: () => void;
  onUpdate: (updatedEvent: AppEvent) => void;
  onDelete: () => void;
  onEditEvent: () => void;
}

export const EventDetails: React.FC<EventDetailsProps> = ({ event, allEvents, onBack, onUpdate, onDelete, onEditEvent }) => {
  const [showAddAttendee, setShowAddAttendee] = useState(false);
  const [showAddExpense, setShowAddExpense] = useState(false);
  const [loading, setLoading] = useState(false);

  // State for new Attendee
  const [newAttendee, setNewAttendee] = useState({ name: '', email: '', phone: '', paidAmount: '' });
  const [suggestions, setSuggestions] = useState<Attendee[]>([]);

  // State for editing Attendee
  const [editingAttendeeId, setEditingAttendeeId] = useState<string | null>(null);
  const [editAttendeeData, setEditAttendeeData] = useState({ name: '', email: '', phone: '', paidAmount: '' });

  // State for new Expense
  const [newExpense, setNewExpense] = useState({ description: '', amount: '' });

  // State for editing Expense
  const [editingExpenseId, setEditingExpenseId] = useState<string | null>(null);
  const [editExpenseData, setEditExpenseData] = useState({ description: '', amount: '' });

  // --- CONFIRMATION MODAL STATE ---
  const [confirmModal, setConfirmModal] = useState<{
    isOpen: boolean;
    type: 'DELETE_EVENT' | 'DELETE_ATTENDEE' | 'DELETE_EXPENSE' | null;
    itemId?: string;
    message: string;
  }>({
    isOpen: false,
    type: null,
    message: ''
  });

  // --- SUGGESTIONS LOGIC ---
  const globalParticipants = useMemo(() => {
    const map = new Map<string, Attendee>();
    (allEvents || []).forEach(ev => {
      (ev.attendees || []).forEach(at => {
        const key = (at.email || at.phone || at.name).toLowerCase().trim();
        map.set(key, at);
      });
    });
    return Array.from(map.values());
  }, [allEvents]);

  const handleNameChange = (val: string) => {
    setNewAttendee(prev => ({ ...prev, name: val }));
    if (val.length >= 2) {
      const filtered = globalParticipants.filter(p => 
        p.name.toLowerCase().includes(val.toLowerCase())
      ).slice(0, 5);
      setSuggestions(filtered);
    } else {
      setSuggestions([]);
    }
  };

  const selectSuggestion = (p: Attendee) => {
    setNewAttendee({
      name: p.name,
      email: p.email || '',
      phone: p.phone || '',
      paidAmount: '' 
    });
    setSuggestions([]);
  };

  // --- ATTENDEE LOGIC ---

  const handleAddAttendee = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newAttendee.name.trim()) return;

    setLoading(true);

    if (event.maxAttendees && (event.attendees || []).length >= event.maxAttendees) {
      alert("Numero massimo di partecipanti raggiunto.");
      setLoading(false);
      return;
    }

    const attendee: Attendee = {
      id: generateId(),
      name: newAttendee.name,
      email: newAttendee.email,
      phone: newAttendee.phone,
      paidAmount: newAttendee.paidAmount ? Number(newAttendee.paidAmount) : undefined,
      status: PaymentStatus.PENDING,
      registrationDate: new Date().toISOString(),
      isPresent: true
    };

    try {
      const updated = await addAttendee(event.id, attendee);
      if (updated) {
        onUpdate(updated);
        setNewAttendee({ name: '', email: '', phone: '', paidAmount: '' });
        setShowAddAttendee(false);
        setSuggestions([]);
      }
    } catch (err) {
      console.error("Error adding attendee:", err);
      alert("Si è verificato un errore durante l'aggiunta.");
    } finally {
      setLoading(false);
    }
  };

  const startEditingAttendee = (attendee: Attendee) => {
    setEditingAttendeeId(attendee.id);
    setEditAttendeeData({ 
      name: attendee.name, 
      email: attendee.email || '', 
      phone: attendee.phone || '',
      paidAmount: attendee.paidAmount !== undefined ? attendee.paidAmount.toString() : ''
    });
  };

  const cancelEditingAttendee = () => {
    setEditingAttendeeId(null);
    setEditAttendeeData({ name: '', email: '', phone: '', paidAmount: '' });
  };

  const saveEditedAttendee = async (originalAttendee: Attendee) => {
    const updatedAttendee: Attendee = {
      ...originalAttendee,
      name: editAttendeeData.name,
      email: editAttendeeData.email,
      phone: editAttendeeData.phone,
      paidAmount: editAttendeeData.paidAmount ? Number(editAttendeeData.paidAmount) : undefined
    };
    setLoading(true);
    try {
      const updatedEvent = await updateAttendee(event.id, updatedAttendee);
      if (updatedEvent) {
        onUpdate(updatedEvent);
        setEditingAttendeeId(null);
      }
    } finally {
      setLoading(false);
    }
  };

  const handleTogglePayment = async (attendeeId: string) => {
    setLoading(true);
    try {
      const updated = await togglePaymentStatus(event.id, attendeeId);
      if (updated) onUpdate(updated);
    } finally {
      setLoading(false);
    }
  };

  const handleTogglePresence = async (attendee: Attendee) => {
    setLoading(true);
    const updatedAttendee = { ...attendee, isPresent: attendee.isPresent === false ? true : false };
    try {
      const updatedEvent = await updateAttendee(event.id, updatedAttendee);
      if (updatedEvent) onUpdate(updatedEvent);
    } finally {
      setLoading(false);
    }
  };

  // --- DELETE LOGIC ---
  const requestDeleteAttendee = (attendeeId: string) => {
    setConfirmModal({ isOpen: true, type: 'DELETE_ATTENDEE', itemId: attendeeId, message: 'Sei sicuro di voler rimuovere questo membro dalla lista?' });
  };
  const requestDeleteExpense = (expenseId: string) => {
    setConfirmModal({ isOpen: true, type: 'DELETE_EXPENSE', itemId: expenseId, message: 'Sei sicuro di voler eliminare questa voce di spesa?' });
  };
  const requestDeleteEvent = () => {
    setConfirmModal({ isOpen: true, type: 'DELETE_EVENT', message: 'ATTENZIONE: Stai per eliminare definitivamente questo evento e tutti i dati associati. Sei sicuro?' });
  };

  const executeDelete = async () => {
    setLoading(true);
    try {
      if (confirmModal.type === 'DELETE_EVENT') {
        await deleteEvent(event.id);
        onDelete();
      } else if (confirmModal.type === 'DELETE_ATTENDEE' && confirmModal.itemId) {
        const updated = await deleteAttendee(event.id, confirmModal.itemId);
        if (updated) onUpdate(updated);
      } else if (confirmModal.type === 'DELETE_EXPENSE' && confirmModal.itemId) {
        const updated = await deleteExpense(event.id, confirmModal.itemId);
        if (updated) onUpdate(updated);
      }
    } finally {
      setLoading(false);
      setConfirmModal({ isOpen: false, type: null, message: '' });
    }
  };

  // --- EXPENSE LOGIC ---
  const handleAddExpense = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    const expense: Expense = { id: generateId(), description: newExpense.description, amount: Number(newExpense.amount) };
    try {
      const updated = await addExpense(event.id, expense);
      if (updated) {
        onUpdate(updated);
        setNewExpense({ description: '', amount: '' });
        setShowAddExpense(false);
      }
    } finally { setLoading(false); }
  };

  const startEditingExpense = (expense: Expense) => {
    setEditingExpenseId(expense.id);
    setEditExpenseData({ description: expense.description, amount: expense.amount.toString() });
  };

  const saveEditedExpense = async (originalExpense: Expense) => {
    if (!editExpenseData.description || !editExpenseData.amount) return;
    const updatedExpense: Expense = { ...originalExpense, description: editExpenseData.description, amount: Number(editExpenseData.amount) };
    setLoading(true);
    try {
      const updatedEvent = await updateExpense(event.id, updatedExpense);
      if (updatedEvent) {
        onUpdate(updatedEvent);
        setEditingExpenseId(null);
      }
    } finally { setLoading(false); }
  };

  // --- CALCULATIONS ---
  const attendees = event.attendees || [];
  const expenses = event.expenses || [];

  const totalCollected = attendees.reduce((acc, a) => {
    if (a.status === PaymentStatus.PAID) {
      return acc + (a.paidAmount !== undefined ? a.paidAmount : event.cost);
    }
    return acc;
  }, 0);

  const totalExpenses = expenses.reduce((acc, curr) => acc + curr.amount, 0);
  const netProfit = totalCollected - totalExpenses;
  const isProfitPositive = netProfit >= 0;

  // L'occupazione conta tutti gli iscritti (anche se poi assenti, il posto è occupato)
  const occupancyPercentage = event.maxAttendees ? Math.min((attendees.length / event.maxAttendees) * 100, 100) : 0;

  return (
    <div className="space-y-8 animate-fade-in pb-10 relative">
      {loading && <div className="fixed inset-0 z-[60] bg-white/50 backdrop-blur-sm flex items-center justify-center"><div className="animate-spin rounded-full h-10 w-10 border-b-2 border-pink-600"></div></div>}

      {/* Confirmation Modal */}
      {confirmModal.isOpen && (
        <div className="fixed inset-0 bg-indigo-950/80 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl max-w-sm w-full p-6 animate-scale-in border border-gray-100">
            <div className="flex flex-col items-center text-center mb-6">
              <div className="w-14 h-14 bg-red-50 rounded-full flex items-center justify-center mb-4 text-red-500"><AlertTriangle className="w-7 h-7" /></div>
              <h3 className="text-xl font-bold text-gray-900">Conferma Eliminazione</h3>
              <p className="text-gray-500 mt-2 text-sm leading-relaxed">{confirmModal.message}</p>
            </div>
            <div className="flex gap-3 justify-center">
              <Button variant="secondary" onClick={() => setConfirmModal({ isOpen: false, type: null, message: '' })} className="w-full">Annulla</Button>
              <Button variant="danger" onClick={executeDelete} className="w-full shadow-red-200" isLoading={loading}>Elimina</Button>
            </div>
          </div>
        </div>
      )}

      {/* Header */}
      <div className="flex flex-col lg:flex-row lg:items-center gap-6 justify-between bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
        <div className="flex items-start gap-5">
          <button onClick={onBack} className="p-2.5 bg-gray-50 hover:bg-gray-100 text-gray-600 rounded-xl transition-colors mt-1" type="button"><ArrowLeft className="w-5 h-5" /></button>
          <div>
            <h1 className="text-3xl font-extrabold text-gray-900 tracking-tight">{event.title}</h1>
            <div className="flex flex-wrap items-center gap-4 mt-2 text-sm text-gray-500 font-medium">
              <span className="flex items-center bg-indigo-50 text-indigo-700 px-3 py-1 rounded-full"><Calendar className="w-3.5 h-3.5 mr-1.5" /> {new Date(event.date).toLocaleDateString('it-IT')}</span>
              <span className="flex items-center bg-gray-100 text-gray-600 px-3 py-1 rounded-full"><MapPin className="w-3.5 h-3.5 mr-1.5" /> {event.location}</span>
            </div>
          </div>
        </div>
        <div className="flex gap-3">
          <Button variant="secondary" onClick={onEditEvent} type="button"><Edit2 className="w-4 h-4 mr-2" /> Modifica</Button>
          <Button variant="danger" onClick={requestDeleteEvent} type="button">Elimina Evento</Button>
        </div>
      </div>

      {/* Stats Overview */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 relative overflow-hidden">
          <div className="absolute top-0 right-0 w-24 h-24 bg-green-50 rounded-bl-full -mr-5 -mt-5"></div>
          <div className="relative">
             <div className="flex items-center gap-3 mb-2">
                <div className="p-2 bg-green-100 text-green-600 rounded-lg"><TrendingUp className="w-5 h-5" /></div>
                <p className="text-sm font-semibold text-gray-500 uppercase">Incasso Reale</p>
              </div>
              <p className="text-3xl font-extrabold text-gray-900">€ {totalCollected.toLocaleString('it-IT', { minimumFractionDigits: 2 })}</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 relative overflow-hidden">
          <div className="absolute top-0 right-0 w-24 h-24 bg-red-50 rounded-bl-full -mr-5 -mt-5"></div>
          <div className="relative">
            <div className="flex items-center gap-3 mb-2">
              <div className="p-2 bg-red-100 text-red-600 rounded-lg"><TrendingDown className="w-5 h-5" /></div>
              <p className="text-sm font-semibold text-gray-500 uppercase">Spese</p>
            </div>
            <p className="text-3xl font-extrabold text-gray-900">€ {totalExpenses.toLocaleString('it-IT', { minimumFractionDigits: 2 })}</p>
          </div>
        </div>
        <div className={`p-6 rounded-2xl shadow-lg border relative overflow-hidden flex flex-col justify-center ${isProfitPositive ? 'bg-indigo-950 border-indigo-900 text-white' : 'bg-red-50 border-red-100 text-red-900'}`}>
          <div className="relative z-10">
            <div className="flex items-center gap-3 mb-2">
              <div className={`p-2 rounded-lg ${isProfitPositive ? 'bg-white/10 text-pink-400' : 'bg-red-100 text-red-600'}`}><Wallet className="w-5 h-5" /></div>
              <p className={`text-sm font-semibold uppercase ${isProfitPositive ? 'text-indigo-200' : 'text-red-700'}`}>Profitto Netto</p>
            </div>
            <p className="text-4xl font-black tracking-tight">€ {netProfit.toLocaleString('it-IT', { minimumFractionDigits: 2 })}</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Left: Details & Expenses */}
        <div className="space-y-8">
          <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
            <h3 className="text-lg font-bold text-gray-900 mb-6 flex items-center"><span className="w-1.5 h-6 bg-pink-500 rounded-full mr-3"></span>Dettagli</h3>
            <div className="space-y-5">
              <div className="flex justify-between items-center border-b border-gray-50 pb-3"><span className="text-gray-500 text-sm flex items-center gap-2 font-medium"><Clock className="w-4 h-4 text-gray-400" /> Orario</span><span className="font-semibold text-gray-800 bg-gray-50 px-3 py-1 rounded-md">{event.time}</span></div>
              <div className="flex justify-between items-center border-b border-gray-50 pb-3"><span className="text-gray-500 text-sm flex items-center gap-2 font-medium"><Euro className="w-4 h-4 text-gray-400" /> Costo Biglietto</span><span className="font-semibold text-gray-800 bg-gray-50 px-3 py-1 rounded-md">€ {event.cost}</span></div>
              <div className="flex justify-between items-center border-b border-gray-50 pb-3"><span className="text-gray-500 text-sm flex items-center gap-2 font-medium"><Users className="w-4 h-4 text-gray-400" /> Max Partecipanti</span><span className="font-semibold text-gray-800 bg-gray-50 px-3 py-1 rounded-md">{event.maxAttendees ? event.maxAttendees : '∞'}</span></div>
              <div className="pt-4">
                <div className="flex justify-between text-xs font-bold text-gray-500 uppercase mb-2"><span>Occupazione</span><span>{event.maxAttendees ? Math.round(occupancyPercentage) : 100}%</span></div>
                <div className="w-full bg-gray-100 rounded-full h-3 overflow-hidden"><div className="h-3 rounded-full bg-gradient-to-r from-pink-500 to-yellow-400 shadow-sm transition-all duration-500" style={{ width: `${event.maxAttendees ? occupancyPercentage : 100}%` }}></div></div>
                <p className="text-xs text-center mt-2 text-gray-400">{attendees.length} iscritti su {event.maxAttendees ? event.maxAttendees : 'illimitati'}</p>
              </div>
            </div>
          </div>

          <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
            <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-gray-50/50"><h3 className="font-bold text-gray-900">Spese & Costi</h3><button onClick={() => setShowAddExpense(!showAddExpense)} className="text-xs text-white bg-indigo-900 hover:bg-indigo-800 px-3 py-1.5 rounded-full font-medium flex items-center transition-colors shadow-sm" type="button"><Plus className="w-3 h-3 mr-1" /> Nuova Spesa</button></div>
            {showAddExpense && (
              <div className="p-5 bg-indigo-50 border-b border-indigo-100 animate-slide-down">
                 <form onSubmit={handleAddExpense} className="flex flex-col gap-3">
                    <input type="text" placeholder="Descrizione" className="w-full text-sm px-3 py-2 border-indigo-200 rounded-lg focus:ring-2 focus:ring-pink-500" required value={newExpense.description} onChange={e => setNewExpense(prev => ({...prev, description: e.target.value}))} />
                    <div className="flex gap-2">
                      <input type="number" placeholder="Importo (€)" className="w-full text-sm px-3 py-2 border-indigo-200 rounded-lg focus:ring-2 focus:ring-pink-500" required min="0" step="0.01" value={newExpense.amount} onChange={e => setNewExpense(prev => ({...prev, amount: e.target.value}))} />
                      <Button type="submit" className="whitespace-nowrap text-xs py-1" isLoading={loading}>Salva</Button>
                    </div>
                 </form>
              </div>
            )}
            <div className="divide-y divide-gray-100">
              {expenses.length === 0 ? (<p className="p-6 text-center text-sm text-gray-400">Nessuna spesa registrata.</p>) : (
                expenses.map(exp => {
                  const isEditing = editingExpenseId === exp.id;
                  return (
                    <div key={exp.id} className={`p-4 flex flex-col sm:flex-row justify-between sm:items-center gap-2 group transition-colors ${isEditing ? 'bg-indigo-50/50' : 'hover:bg-gray-50'}`}>
                      {isEditing ? (
                        <div className="flex-1 flex gap-2"><input className="flex-1 border border-pink-300 rounded-md text-sm px-3 py-1.5" value={editExpenseData.description} onChange={e => setEditExpenseData(p => ({...p, description: e.target.value}))} /><input className="w-24 border border-pink-300 rounded-md text-sm px-3 py-1.5" type="number" value={editExpenseData.amount} onChange={e => setEditExpenseData(p => ({...p, amount: e.target.value}))} /><button onClick={() => saveEditedExpense(exp)} className="bg-green-500 p-1.5 rounded-lg text-white"><Save className="w-4 h-4" /></button></div>
                      ) : (
                        <>
                          <div className="flex-1 min-w-0 mr-2"><p className="text-sm font-semibold text-gray-800 break-words">{exp.description}</p></div>
                          <div className="flex items-center gap-3"><p className="text-sm font-bold text-red-500 bg-red-50 px-2 py-1 rounded">- €{exp.amount}</p><div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity"><button onClick={() => startEditingExpense(exp)} className="p-1.5 text-gray-300 hover:text-indigo-600 rounded-full"><Edit2 className="w-4 h-4" /></button><button onClick={() => requestDeleteExpense(exp.id)} className="p-1.5 text-gray-300 hover:text-red-500 rounded-full"><Trash2 className="w-4 h-4" /></button></div></div>
                        </>
                      )}
                    </div>
                  );
                })
              )}
            </div>
          </div>
        </div>

        {/* Right: Attendees List */}
        <div className="lg:col-span-2 flex flex-col h-full">
          <div className="bg-white rounded-2xl shadow-sm border border-gray-100 flex flex-col h-full overflow-hidden">
            <div className="p-6 border-b border-gray-100 flex justify-between items-center bg-white">
              <div className="flex items-center gap-3"><div className="p-2 bg-pink-100 text-pink-600 rounded-lg"><Users className="w-5 h-5" /></div><div><h2 className="font-bold text-gray-900 text-lg">Lista Membri Iscritti</h2><p className="text-xs text-gray-500">Gestisci partecipazioni, assenze e pagamenti</p></div></div>
              <Button onClick={() => setShowAddAttendee(!showAddAttendee)} variant="primary" className="text-xs" disabled={!!event.maxAttendees && attendees.length >= event.maxAttendees} type="button"><UserPlus className="w-4 h-4 mr-2" /> Aggiungi</Button>
            </div>

            {showAddAttendee && (
              <div className="p-6 bg-gradient-to-r from-indigo-50 to-pink-50 border-b border-pink-100 animate-slide-down">
                <h4 className="text-sm font-bold text-indigo-900 mb-4 uppercase tracking-wide">Nuovo Partecipante</h4>
                <form onSubmit={handleAddAttendee} className="space-y-4 relative">
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                    <div className="relative">
                      <input type="text" required className="w-full px-4 py-2 border border-gray-200 rounded-lg text-sm focus:ring-2 focus:ring-pink-500" value={newAttendee.name} onChange={e => handleNameChange(e.target.value)} placeholder="Nome Cognome *" autoComplete="off" />
                      {suggestions.length > 0 && (
                        <div className="absolute z-[70] left-0 right-0 mt-1 bg-white border border-gray-200 rounded-xl shadow-2xl overflow-hidden animate-scale-in">
                           <ul className="divide-y divide-gray-50">
                              {suggestions.map((p, idx) => (<li key={idx}><button type="button" onClick={() => selectSuggestion(p)} className="w-full text-left px-4 py-3 hover:bg-pink-50 flex items-center justify-between group"><div><p className="text-sm font-bold text-gray-900">{p.name}</p></div><Plus className="w-3 h-3 text-gray-400 group-hover:text-pink-600" /></button></li>))}
                           </ul>
                        </div>
                      )}
                    </div>
                    <input type="email" className="w-full px-4 py-2 border border-gray-200 rounded-lg text-sm" value={newAttendee.email} onChange={e => setNewAttendee(prev => ({ ...prev, email: e.target.value }))} placeholder="Email" />
                    <input type="tel" className="w-full px-4 py-2 border border-gray-200 rounded-lg text-sm" value={newAttendee.phone} onChange={e => setNewAttendee(prev => ({ ...prev, phone: e.target.value }))} placeholder="Telefono" />
                    <input type="number" step="0.01" className="w-full px-4 py-2 border border-gray-200 rounded-lg text-sm font-bold text-pink-600 bg-pink-50" value={newAttendee.paidAmount} onChange={e => setNewAttendee(prev => ({ ...prev, paidAmount: e.target.value }))} placeholder={`Quota (Standard: €${event.cost})`} />
                  </div>
                  <div className="flex justify-end gap-2 pt-2"><Button type="button" variant="ghost" onClick={() => setShowAddAttendee(false)}>Chiudi</Button><Button type="submit" isLoading={loading}>Inserisci in lista</Button></div>
                </form>
              </div>
            )}

            <div className="overflow-x-auto flex-1">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="text-xs font-semibold text-gray-300 bg-indigo-950 border-b border-indigo-900">
                    <th className="px-6 py-4">MEMBRO</th>
                    <th className="px-6 py-4">CONTATTI</th>
                    <th className="px-6 py-4 text-center">QUOTA PAGATA</th>
                    <th className="px-6 py-4 text-center">STATO</th>
                    <th className="px-6 py-4 text-right">AZIONI</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {attendees.length === 0 ? (
                    <tr><td colSpan={5} className="px-6 py-16 text-center text-gray-400">La lista è vuota</td></tr>
                  ) : (
                    attendees.map(attendee => {
                      const isEditing = editingAttendeeId === attendee.id;
                      const isAbsent = attendee.isPresent === false;
                      const hasCustomAmount = attendee.paidAmount !== undefined && attendee.paidAmount !== event.cost;
                      const displayAmount = attendee.paidAmount !== undefined ? attendee.paidAmount : event.cost;

                      return (
                        <tr key={attendee.id} className={`group transition-colors ${isEditing ? 'bg-pink-50' : 'hover:bg-gray-50'} ${isAbsent ? 'opacity-60 grayscale-[0.5]' : ''}`}>
                          <td className="px-6 py-4">
                            {isEditing ? (<input className="w-full border border-pink-300 rounded-md text-sm px-3 py-1.5" value={editAttendeeData.name} onChange={e => setEditAttendeeData(p => ({...p, name: e.target.value}))} />) : (
                              <div className="flex items-center gap-2">
                                <span className={`font-semibold text-gray-900 ${isAbsent ? 'line-through' : ''}`}>{attendee.name}</span>
                                {hasCustomAmount && <span className="text-[10px] bg-amber-100 text-amber-700 px-1.5 py-0.5 rounded font-bold uppercase flex items-center gap-0.5"><Tag className="w-2.5 h-2.5" /> Quota Speciale</span>}
                                {isAbsent && <span className="text-[9px] bg-red-100 text-red-700 px-1.5 py-0.5 rounded-full font-black uppercase tracking-widest border border-red-200">Assente</span>}
                              </div>
                            )}
                          </td>
                          <td className="px-6 py-4 text-xs text-gray-500">
                            {isEditing ? (
                              <div className="flex flex-col gap-1"><input className="border rounded px-2 py-1" placeholder="Email" value={editAttendeeData.email} onChange={e => setEditAttendeeData(p => ({...p, email: e.target.value}))} /><input className="border rounded px-2 py-1" placeholder="Telefono" value={editAttendeeData.phone} onChange={e => setEditAttendeeData(p => ({...p, phone: e.target.value}))} /></div>
                            ) : (
                              <div>{attendee.email && <div className="flex items-center mb-0.5"><Mail className="w-3 h-3 mr-1" /> {attendee.email}</div>}{attendee.phone && <div className="flex items-center"><Phone className="w-3 h-3 mr-1" /> {attendee.phone}</div>}</div>
                            )}
                          </td>
                          <td className="px-6 py-4 text-center">
                            {isEditing ? (
                              <input type="number" step="0.01" className="w-24 border border-pink-300 rounded px-2 py-1 text-center font-bold text-pink-600" value={editAttendeeData.paidAmount} onChange={e => setEditAttendeeData(p => ({...p, paidAmount: e.target.value}))} placeholder={event.cost.toString()} />
                            ) : (
                              <span className={`font-bold ${hasCustomAmount ? 'text-pink-600' : 'text-gray-900'}`}>€ {displayAmount.toFixed(2)}</span>
                            )}
                          </td>
                          <td className="px-6 py-4 text-center">
                             {!isEditing && (
                              <button onClick={() => handleTogglePayment(attendee.id)} className={`inline-flex items-center px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wide transition-all ${attendee.status === PaymentStatus.PAID ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-800'}`} type="button">
                                {attendee.status === PaymentStatus.PAID ? (<><CheckCircle className="w-3.5 h-3.5 mr-1" /> Pagato</>) : (<><XCircle className="w-3.5 h-3.5 mr-1" /> Da Pagare</>)}
                              </button>
                             )}
                          </td>
                          <td className="px-6 py-4 text-right">
                            {isEditing ? (
                              <div className="flex justify-end gap-2"><button onClick={() => saveEditedAttendee(attendee)} className="bg-green-500 text-white p-1.5 rounded-lg"><Save className="w-4 h-4" /></button><button onClick={cancelEditingAttendee} className="bg-gray-400 text-white p-1.5 rounded-lg"><X className="w-4 h-4" /></button></div>
                            ) : (
                              <div className="flex justify-end items-center gap-1">
                                <button 
                                  onClick={() => handleTogglePresence(attendee)} 
                                  className={`p-2 rounded-lg transition-all ${isAbsent ? 'text-red-500 bg-red-50 hover:bg-red-100' : 'text-gray-400 hover:text-green-600 hover:bg-green-50'}`}
                                  title={isAbsent ? "Segna come Presente" : "Segna come Assente"}
                                >
                                  {isAbsent ? <UserX className="w-4 h-4" /> : <UserCheck className="w-4 h-4" />}
                                </button>
                                <div className="w-px h-4 bg-gray-100 mx-1"></div>
                                <button onClick={() => startEditingAttendee(attendee)} className="text-gray-400 hover:text-indigo-600 p-2 rounded-lg" title="Modifica"><Edit2 className="w-4 h-4" /></button>
                                <button onClick={() => requestDeleteAttendee(attendee.id)} className="text-gray-400 hover:text-red-600 p-2 rounded-lg" title="Rimuovi"><Trash2 className="w-4 h-4" /></button>
                              </div>
                            )}
                          </td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { AppEvent, Attendee } from '../types';
import { Users, Search, Mail, Phone, ArrowLeft, SortAsc, SortDesc, Trophy, UserCheck, Star } from 'lucide-react';

interface ParticipantsListProps {
  events: AppEvent[];
  onBack: () => void;
  onParticipantClick: (key: string) => void;
}

type SortKey = 'name' | 'eventsCount';
type SortOrder = 'asc' | 'desc';

export const ParticipantsList: React.FC<ParticipantsListProps> = ({ events, onBack, onParticipantClick }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [sortKey, setSortKey] = useState<SortKey>('name');
  const [sortOrder, setSortOrder] = useState<SortOrder>('asc');

  // Caricamento soglie fedeltà per il calcolo dei badge in lista
  const vipThreshold = Number(localStorage.getItem('onbeventi_vip_threshold') || '5');
  const regularThreshold = Number(localStorage.getItem('onbeventi_regular_threshold') || '3');

  const globalAttendees = useMemo(() => {
    const map = new Map<string, { 
      attendee: Attendee, 
      eventsCount: number, // Solo presenze effettive
      totalBookings: number, // Totale prenotazioni (incluse assenze)
      eventTitles: string[], 
      key: string,
      isVip: boolean,
      isRegular: boolean
    }>();

    (events || []).forEach(event => {
      (event.attendees || []).forEach(a => {
        const key = (a.email || a.phone || a.name).toLowerCase().trim();
        const isPresent = a.isPresent !== false;

        if (map.has(key)) {
          const existing = map.get(key)!;
          existing.totalBookings += 1;
          if (isPresent) {
            existing.eventsCount += 1;
          }
          existing.eventTitles.push(event.title);
        } else {
          map.set(key, {
            attendee: a,
            eventsCount: isPresent ? 1 : 0,
            totalBookings: 1,
            eventTitles: [event.title],
            key: key,
            isVip: false, // calcolato dopo
            isRegular: false // calcolato dopo
          });
        }
      });
    });

    let list = Array.from(map.values()).map(item => ({
      ...item,
      isVip: item.eventsCount >= vipThreshold,
      isRegular: item.eventsCount >= regularThreshold && item.eventsCount < vipThreshold
    }));

    if (searchTerm) {
      const lowerSearch = searchTerm.toLowerCase();
      list = list.filter(item => 
        item.attendee.name.toLowerCase().includes(lowerSearch) ||
        (item.attendee.email && item.attendee.email.toLowerCase().includes(lowerSearch)) ||
        (item.attendee.phone && item.attendee.phone.includes(searchTerm))
      );
    }

    list.sort((a, b) => {
      if (sortKey === 'name') {
        const comparison = a.attendee.name.localeCompare(b.attendee.name);
        return sortOrder === 'asc' ? comparison : -comparison;
      } else {
        const comparison = a.eventsCount - b.eventsCount;
        return sortOrder === 'asc' ? comparison : -comparison;
      }
    });

    return list;
  }, [events, searchTerm, sortKey, sortOrder, vipThreshold, regularThreshold]);

  const toggleSort = (key: SortKey) => {
    if (sortKey === key) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortKey(key);
      setSortOrder(key === 'eventsCount' ? 'desc' : 'asc');
    }
  };

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex flex-col lg:flex-row justify-between items-stretch lg:items-center gap-4 bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="p-2.5 bg-gray-50 hover:bg-gray-100 rounded-xl transition-colors border border-gray-100">
            <ArrowLeft className="w-5 h-5 text-gray-500" />
          </button>
          <div>
            <h1 className="text-2xl font-extrabold text-gray-900 tracking-tight">Anagrafica Membri</h1>
            <p className="text-sm text-gray-500">Gestisci i contatti della tua community e identifica i membri VIP.</p>
          </div>
        </div>

        <div className="flex flex-col sm:flex-row gap-3">
          <div className="relative flex-1 sm:w-80">
            <Search className="absolute left-3.5 top-3 w-4 h-4 text-gray-400" />
            <input 
              type="text"
              placeholder="Cerca per nome, email o telefono..."
              className="w-full pl-11 pr-4 py-2.5 border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-pink-500 shadow-sm transition-all outline-none"
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>

          <div className="flex bg-gray-50 p-1 rounded-xl border border-gray-200">
            <button 
              onClick={() => toggleSort('name')}
              className={`flex items-center gap-2 px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${sortKey === 'name' ? 'bg-white text-indigo-950 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
            >
              Nome {sortKey === 'name' && (sortOrder === 'asc' ? <SortAsc className="w-3.5 h-3.5" /> : <SortDesc className="w-3.5 h-3.5" />)}
            </button>
            <button 
              onClick={() => toggleSort('eventsCount')}
              className={`flex items-center gap-2 px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${sortKey === 'eventsCount' ? 'bg-white text-indigo-950 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
            >
              Presenze {sortKey === 'eventsCount' && (sortOrder === 'asc' ? <SortAsc className="w-3.5 h-3.5" /> : <SortDesc className="w-3.5 h-3.5" />)}
            </button>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-indigo-950 text-white text-[11px] font-bold uppercase tracking-wider">
                <th className="px-6 py-4 cursor-pointer hover:bg-indigo-900 transition-colors" onClick={() => toggleSort('name')}>
                  <div className="flex items-center gap-2">
                    Membro {sortKey === 'name' && (sortOrder === 'asc' ? <SortAsc className="w-3 h-3 opacity-60" /> : <SortDesc className="w-3 h-3 opacity-60" />)}
                  </div>
                </th>
                <th className="px-6 py-4">Contatti</th>
                <th className="px-6 py-4 text-center cursor-pointer hover:bg-indigo-900 transition-colors" onClick={() => toggleSort('eventsCount')}>
                  <div className="flex items-center justify-center gap-2">
                    Presenze Effettive {sortKey === 'eventsCount' && (sortOrder === 'asc' ? <SortAsc className="w-3 h-3 opacity-60" /> : <SortDesc className="w-3 h-3 opacity-60" />)}
                  </div>
                </th>
                <th className="px-6 py-4">Ultimi Eventi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {globalAttendees.length === 0 ? (
                <tr>
                  <td colSpan={4} className="px-6 py-24 text-center text-gray-400 italic">
                    <div className="flex flex-col items-center gap-3">
                      <div className="p-4 bg-gray-50 rounded-full"><Users className="w-8 h-8 opacity-20" /></div>
                      <p>Nessun membro trovato.</p>
                    </div>
                  </td>
                </tr>
              ) : (
                globalAttendees.map((item, idx) => (
                  <tr 
                    key={idx} 
                    className="hover:bg-pink-50/30 transition-colors group cursor-pointer"
                    onClick={() => onParticipantClick(item.key)}
                  >
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-indigo-50 to-pink-50 text-indigo-700 flex items-center justify-center font-black text-sm shadow-sm group-hover:scale-110 transition-transform relative border border-gray-100">
                          {item.attendee.name.charAt(0).toUpperCase()}
                          {item.isVip && (
                            <div className="absolute -top-1.5 -right-1.5 bg-yellow-400 p-0.5 rounded-full border-2 border-white shadow-sm">
                              <Trophy className="w-2.5 h-2.5 text-white" />
                            </div>
                          )}
                        </div>
                        <div className="flex flex-col">
                          <div className="flex items-center gap-2">
                            <span className="font-bold text-gray-900 group-hover:text-pink-600 transition-colors">{item.attendee.name}</span>

                            {/* Badge chiari in riga */}
                            {item.isVip && (
                              <span className="inline-flex items-center bg-yellow-100 text-yellow-700 px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-wider border border-yellow-200">
                                <Trophy className="w-2.5 h-2.5 mr-1" /> VIP
                              </span>
                            )}
                            {item.isRegular && (
                              <span className="inline-flex items-center bg-green-100 text-green-700 px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-wider border border-green-200">
                                <Star className="w-2.5 h-2.5 mr-1" /> MEMBRO FEDELE
                              </span>
                            )}
                          </div>
                          {item.eventsCount >= vipThreshold && (
                            <span className="text-[9px] text-yellow-600/70 font-bold uppercase tracking-tighter">Miglior Membro</span>
                          )}
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="space-y-1">
                        {item.attendee.email && (
                          <div className="flex items-center text-[11px] text-gray-500">
                            <Mail className="w-3 h-3 mr-1.5 text-indigo-300" /> {item.attendee.email}
                          </div>
                        )}
                        {item.attendee.phone && (
                          <div className="flex items-center text-[11px] text-gray-500">
                            <Phone className="w-3 h-3 mr-1.5 text-indigo-300" /> {item.attendee.phone}
                          </div>
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-4 text-center">
                      <div className="flex flex-col items-center">
                        <span className={`inline-block px-4 py-1.5 rounded-full text-xs font-black border min-w-[3rem] shadow-sm transition-all ${
                          item.isVip 
                            ? 'bg-yellow-400 text-white border-yellow-500 scale-110' 
                            : item.isRegular 
                              ? 'bg-green-500 text-white border-green-600'
                              : 'bg-indigo-50 text-indigo-700 border-indigo-100'
                        }`}>
                          {item.eventsCount}
                        </span>
                        {item.totalBookings > item.eventsCount && (
                          <span className="text-[9px] text-gray-400 mt-1">({item.totalBookings} prenotazioni totali)</span>
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex flex-wrap gap-1.5 max-w-sm">
                        {item.eventTitles.slice(-2).reverse().map((t, i) => (
                          <span key={i} className={`text-[9px] px-2 py-0.5 rounded border shadow-sm truncate max-w-[120px] ${
                            i === 0 ? 'bg-indigo-50 text-indigo-700 border-indigo-100 font-bold' : 'bg-white text-gray-500 border-gray-100'
                          }`}>
                            {t}
                          </span>
                        ))}
                        {item.eventTitles.length > 2 && (
                          <span className="text-[9px] text-gray-400 font-bold flex items-center">
                            +{item.eventTitles.length - 2} altri
                          </span>
                        )}
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { AppEvent, Attendee, PaymentStatus } from '../types';
import { Button } from './Button';
import { 
  ArrowLeft, Edit2, Save, X, Mail, Phone, Calendar, 
  MessageCircle, ExternalLink, Trophy, History, Wallet, 
  CheckCircle, Clock, Tag, Briefcase, Download, User, UserX
} from 'lucide-react';
import { updateParticipantGlobally } from '../services/storageService';

interface ParticipantDetailsProps {
  participantKey: string;
  events: AppEvent[];
  onBack: () => void;
  onUpdate: () => void;
}

interface ParticipantSummary {
  baseAttendee: Attendee | null;
  totalPaid: number;
  presenceCount: number; // Solo quando isPresent === true
  history: { event: AppEvent; attendeeData: Attendee }[];
  lastSeen: string | null;
}

export const ParticipantDetails: React.FC<ParticipantDetailsProps> = ({ participantKey, events, onBack, onUpdate }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({ name: '', email: '', phone: '' });

  // Caricamento soglie fedeltà dalle impostazioni
  const vipThreshold = Number(localStorage.getItem('onbeventi_vip_threshold') || '5');
  const regularThreshold = Number(localStorage.getItem('onbeventi_regular_threshold') || '3');

  // Analisi dati partecipante con tipizzazione esplicita per evitare errori TS
  const data = useMemo<ParticipantSummary>(() => {
    let baseAttendee: Attendee | null = null;
    let totalPaid = 0;
    let presenceCount = 0;
    const history: { event: AppEvent; attendeeData: Attendee }[] = [];

    (events || []).forEach(event => {
      const attendee = (event.attendees || []).find(a => 
        (a.email || a.phone || a.name).toLowerCase().trim() === participantKey
      );

      if (attendee) {
        if (!baseAttendee) baseAttendee = attendee;
        history.push({ event, attendeeData: attendee });

        if (attendee.status === PaymentStatus.PAID) {
          totalPaid += (attendee.paidAmount !== undefined ? attendee.paidAmount : event.cost);
        }

        if (attendee.isPresent !== false) {
          presenceCount += 1;
        }
      }
    });

    history.sort((a, b) => new Date(b.event.date).getTime() - new Date(a.event.date).getTime());

    // Ultima presenza effettiva
    const lastSeenPresence = history.find(h => h.attendeeData.isPresent !== false);
    const lastSeen = lastSeenPresence ? lastSeenPresence.event.date : null;

    return { baseAttendee, totalPaid, presenceCount, history, lastSeen };
  }, [events, participantKey]);

  // Sincronizza il form quando i dati di base cambiano
  useEffect(() => {
    if (data.baseAttendee) {
      setFormData({
        name: data.baseAttendee.name || '',
        email: data.baseAttendee.email || '',
        phone: data.baseAttendee.phone || ''
      });
    }
  }, [data.baseAttendee]);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;
    setLoading(true);
    try {
      await updateParticipantGlobally(participantKey, formData);
      setIsEditing(false);
      onUpdate();
    } catch (err) {
      console.error("Errore durante l'aggiornamento globale:", err);
      alert("Errore durante l'aggiornamento. Riprova.");
    } finally {
      setLoading(false);
    }
  };

  const handleExportVCard = () => {
    if (!data.baseAttendee) return;
    const { name, email, phone } = formData;
    const vcard = `BEGIN:VCARD
VERSION:3.0
FN:${name}
TEL;TYPE=CELL:${phone}
EMAIL:${email}
ORG:ONBEVENTI CRM
NOTE:Presenze effettive: ${data.presenceCount}
END:VCARD`;

    const blob = new Blob([vcard], { type: 'text/vcard' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${name.replace(/\s+/g, '_')}_Contatto.vcf`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  if (!data.baseAttendee) {
    return (
      <div className="p-12 text-center">
        <div className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100 max-w-md mx-auto">
          <User className="w-12 h-12 text-gray-200 mx-auto mb-4" />
          <p className="text-gray-500 font-medium">Membro non trovato nel database.</p>
          <Button onClick={onBack} variant="secondary" className="mt-4">Torna alla lista</Button>
        </div>
      </div>
    );
  }

  const isVip = data.presenceCount >= vipThreshold;
  const isRegular = data.presenceCount >= regularThreshold;

  return (
    <div className="space-y-8 animate-fade-in pb-12">
      {/* Navbar Scheda */}
      <div className="flex flex-col md:flex-row md:items-center justify-between bg-white p-6 rounded-2xl shadow-sm border border-gray-100 gap-4">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="p-2.5 bg-gray-50 hover:bg-gray-100 rounded-xl transition-colors border border-gray-100">
            <ArrowLeft className="w-5 h-5 text-gray-500" />
          </button>
          <div>
            <h1 className="text-2xl font-black text-gray-900 leading-tight">Profilo Membro</h1>
            <p className="text-xs text-indigo-500 font-bold uppercase tracking-wider">ONBEVENTI Community System</p>
          </div>
        </div>
        <div className="flex gap-2">
           {!isEditing ? (
             <>
               <Button variant="secondary" onClick={handleExportVCard} title="Esporta in rubrica">
                 <Download className="w-4 h-4 mr-2" /> VCard
               </Button>
               <Button onClick={() => setIsEditing(true)}>
                 <Edit2 className="w-4 h-4 mr-2" /> Modifica Dati
               </Button>
             </>
           ) : (
             <div className="flex gap-2">
                <Button variant="ghost" onClick={() => setIsEditing(false)}>Annulla</Button>
                <Button onClick={handleSave} isLoading={loading}>
                   <Save className="w-4 h-4 mr-2" /> Aggiorna Ovunque
                </Button>
             </div>
           )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Colonna Sinistra: Profilo & Info */}
        <div className="space-y-6">
          <div className="bg-white p-8 rounded-3xl shadow-sm border border-gray-100 text-center relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-pink-500 to-indigo-600"></div>

            <div className="w-24 h-24 mx-auto rounded-3xl bg-indigo-50 flex items-center justify-center text-4xl font-black text-indigo-600 border-4 border-white shadow-xl mb-6 relative">
              {formData.name.charAt(0).toUpperCase()}
              {isVip && (
                <div className="absolute -top-3 -right-3 bg-yellow-400 p-2 rounded-full border-4 border-white shadow-lg">
                  <Trophy className="w-5 h-5 text-white" />
                </div>
              )}
            </div>

            {isEditing ? (
              <form onSubmit={handleSave} className="space-y-4 text-left">
                <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Nome Completo</label>
                  <input 
                    className="w-full mt-1 px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl text-sm focus:ring-2 focus:ring-pink-500 outline-none" 
                    value={formData.name} 
                    onChange={e => setFormData(p => ({...p, name: e.target.value}))} 
                    required 
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Email</label>
                  <input 
                    type="email" 
                    className="w-full mt-1 px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl text-sm focus:ring-2 focus:ring-pink-500 outline-none" 
                    value={formData.email} 
                    onChange={e => setFormData(p => ({...p, email: e.target.value}))} 
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Telefono</label>
                  <input 
                    type="tel" 
                    className="w-full mt-1 px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl text-sm focus:ring-2 focus:ring-pink-500 outline-none" 
                    value={formData.phone} 
                    onChange={e => setFormData(p => ({...p, phone: e.target.value}))} 
                  />
                </div>
              </form>
            ) : (
              <>
                <h2 className="text-2xl font-black text-gray-900 mb-1">{formData.name}</h2>
                <div className="flex flex-wrap justify-center gap-2 mb-8">
                  {isVip ? (
                    <span className="bg-yellow-100 text-yellow-700 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider flex items-center shadow-sm">
                      <Trophy className="w-3 h-3 mr-1" /> VIP Platinum
                    </span>
                  ) : isRegular ? (
                    <span className="bg-green-100 text-green-700 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider shadow-sm">
                      Membro Fedele
                    </span>
                  ) : (
                    <span className="bg-gray-100 text-gray-500 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider shadow-sm">
                      Nuovo Iscritto
                    </span>
                  )}
                </div>

                <div className="space-y-3 pt-6 border-t border-gray-50">
                  <div className="flex items-center p-3 rounded-2xl bg-gray-50 hover:bg-gray-100 transition-colors group">
                    <Mail className="w-4 h-4 text-gray-400 mr-3" />
                    <div className="text-left flex-1">
                      <p className="text-[10px] font-black text-gray-400 uppercase">Email</p>
                      <p className="text-sm font-bold text-gray-700 truncate">{formData.email || '-'}</p>
                    </div>
                    {formData.email && (
                      <a href={`mailto:${formData.email}`} className="opacity-0 group-hover:opacity-100 p-2 text-indigo-500 transition-opacity">
                        <ExternalLink className="w-4 h-4" />
                      </a>
                    )}
                  </div>
                  <div className="flex items-center p-3 rounded-2xl bg-gray-50 hover:bg-gray-100 transition-colors group">
                    <Phone className="w-4 h-4 text-gray-400 mr-3" />
                    <div className="text-left flex-1">
                      <p className="text-[10px] font-black text-gray-400 uppercase">Telefono</p>
                      <p className="text-sm font-bold text-gray-700">{formData.phone || '-'}</p>
                    </div>
                    {formData.phone && (
                      <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        <a href={`tel:${formData.phone}`} className="p-2 text-indigo-500">
                          <Phone className="w-4 h-4" />
                        </a>
                        <a 
                          href={`https://wa.me/${formData.phone.replace(/\D/g, '')}`} 
                          target="_blank" 
                          rel="noopener noreferrer" 
                          className="p-2 text-green-500"
                        >
                          <MessageCircle className="w-4 h-4" />
                        </a>
                      </div>
                    )}
                  </div>
                </div>
              </>
            )}
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="bg-white p-5 rounded-3xl border border-gray-100 shadow-sm relative overflow-hidden group">
              <div className="absolute top-0 right-0 w-8 h-8 bg-pink-50 rounded-bl-full group-hover:w-12 group-hover:h-12 transition-all"></div>
              <p className="text-[10px] font-black text-gray-400 uppercase mb-1">Totale Versato</p>
              <p className="text-2xl font-black text-pink-600">€{data.totalPaid.toFixed(2)}</p>
            </div>
            <div className="bg-white p-5 rounded-3xl border border-gray-100 shadow-sm relative overflow-hidden group">
              <div className="absolute top-0 right-0 w-8 h-8 bg-indigo-50 rounded-bl-full group-hover:w-12 group-hover:h-12 transition-all"></div>
              <p className="text-[10px] font-black text-gray-400 uppercase mb-1">Presenze</p>
              <p className="text-2xl font-black text-indigo-600">{data.presenceCount}</p>
              {data.history.length > data.presenceCount && (
                <p className="text-[9px] text-gray-400">su {data.history.length} prenotazioni</p>
              )}
            </div>
          </div>

          <div className="bg-indigo-950 p-6 rounded-3xl text-white shadow-xl relative overflow-hidden">
               <Calendar className="absolute -bottom-2 -right-2 w-16 h-16 text-white/5" />
               <p className="text-[10px] font-black text-indigo-300 uppercase tracking-widest mb-1">Ultima Presenza Reale</p>
               <p className="text-lg font-bold">
                 {data.lastSeen 
                   ? new Date(data.lastSeen).toLocaleDateString('it-IT', { day: 'numeric', month: 'long', year: 'numeric' })
                   : 'Nessuna presenza registrata'
                 }
               </p>
            </div>
        </div>

        {/* Colonna Destra: Storico Eventi */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden flex flex-col h-full">
            <div className="px-6 py-5 border-b border-gray-100 bg-gray-50/50 flex justify-between items-center">
              <h3 className="font-black text-gray-900 flex items-center gap-2">
                <History className="w-5 h-5 text-pink-500" />
                Storico Community
              </h3>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead className="bg-indigo-950 text-white text-[10px] font-bold uppercase tracking-wider">
                  <tr>
                    <th className="px-6 py-4">Evento</th>
                    <th className="px-6 py-4">Presenza</th>
                    <th className="px-6 py-4 text-center">Pagamento</th>
                    <th className="px-6 py-4 text-right">Quota</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                  {data.history.length === 0 ? (
                    <tr>
                      <td colSpan={4} className="px-6 py-12 text-center text-gray-400 italic">
                        Nessuna attività registrata per questo membro.
                      </td>
                    </tr>
                  ) : (
                    data.history.map(({ event, attendeeData }) => {
                      const isPaid = attendeeData.status === PaymentStatus.PAID;
                      const isPresent = attendeeData.isPresent !== false;
                      const amount = attendeeData.paidAmount !== undefined ? attendeeData.paidAmount : event.cost;
                      return (
                        <tr key={event.id} className={`hover:bg-gray-50 transition-colors group ${!isPresent ? 'bg-gray-50/30' : ''}`}>
                          <td className="px-6 py-4">
                            <div className="flex flex-col">
                              <span className={`font-bold text-gray-900 text-sm group-hover:text-indigo-600 transition-colors ${!isPresent ? 'line-through text-gray-400' : ''}`}>
                                {event.title}
                              </span>
                              <div className="text-[10px] text-gray-400 flex items-center gap-1 mt-0.5">
                                <Briefcase className="w-3 h-3" /> {event.location} • {new Date(event.date).toLocaleDateString('it-IT')}
                              </div>
                            </div>
                          </td>
                          <td className="px-6 py-4">
                            {isPresent ? (
                              <span className="flex items-center text-green-600 text-[10px] font-black uppercase tracking-wider">
                                <CheckCircle className="w-3 h-3 mr-1" /> Presente
                              </span>
                            ) : (
                              <span className="flex items-center text-red-400 text-[10px] font-black uppercase tracking-wider">
                                <UserX className="w-3 h-3 mr-1" /> Assente
                              </span>
                            )}
                          </td>
                          <td className="px-6 py-4 text-center">
                            <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-[9px] font-black uppercase tracking-wider shadow-sm ${
                              isPaid ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-700'
                            }`}>
                              {isPaid ? <CheckCircle className="w-3 h-3 mr-1" /> : <Clock className="w-3 h-3 mr-1" />}
                              {isPaid ? 'Pagato' : 'Sospeso'}
                            </span>
                          </td>
                          <td className="px-6 py-4 text-right font-black text-sm">
                            € {amount.toFixed(2)}
                          </td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>

            <div className="p-6 bg-gray-50 border-t border-gray-100 mt-auto flex justify-between items-center">
              <div className="flex items-center gap-2">
                 <Tag className="w-4 h-4 text-pink-500" />
                 <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Resoconto Community Personale</span>
              </div>
              <div className="text-right">
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-wider">Contributo Finanziario Reale</p>
                <p className="text-xl font-black text-gray-900">€ {data.totalPaid.toFixed(2)}</p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { AppEvent, Attendee } from '../types';
import { Users, Search, Mail, Phone, ArrowLeft, SortAsc, SortDesc, Trophy, UserCheck, Star, Repeat, PieChart } from 'lucide-react';

interface ParticipantsListProps {
  events: AppEvent[];
  onBack: () => void;
  onParticipantClick: (key: string) => void;
}

type SortKey = 'name' | 'eventsCount';
type SortOrder = 'asc' | 'desc';

export const ParticipantsList: React.FC<ParticipantsListProps> = ({ events, onBack, onParticipantClick }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [sortKey, setSortKey] = useState<SortKey>('name');
  const [sortOrder, setSortOrder] = useState<SortOrder>('asc');

  // Caricamento soglie fedeltà per il calcolo dei badge in lista
  const vipThreshold = Number(localStorage.getItem('onbeventi_vip_threshold') || '5');
  const regularThreshold = Number(localStorage.getItem('onbeventi_regular_threshold') || '3');

  const { list, stats } = useMemo(() => {
    const map = new Map<string, { 
      attendee: Attendee, 
      eventsCount: number, // Solo presenze effettive
      totalBookings: number, // Totale prenotazioni (incluse assenze)
      eventTitles: string[], 
      key: string,
      isVip: boolean,
      isRegular: boolean
    }>();

    (events || []).forEach(event => {
      (event.attendees || []).forEach(a => {
        const key = (a.email || a.phone || a.name).toLowerCase().trim();
        const isPresent = a.isPresent !== false;

        if (map.has(key)) {
          const existing = map.get(key)!;
          existing.totalBookings += 1;
          if (isPresent) {
            existing.eventsCount += 1;
          }
          existing.eventTitles.push(event.title);
        } else {
          map.set(key, {
            attendee: a,
            eventsCount: isPresent ? 1 : 0,
            totalBookings: 1,
            eventTitles: [event.title],
            key: key,
            isVip: false, // calcolato dopo
            isRegular: false // calcolato dopo
          });
        }
      });
    });

    const fullList = Array.from(map.values()).map(item => ({
      ...item,
      isVip: item.eventsCount >= vipThreshold,
      isRegular: item.eventsCount >= regularThreshold && item.eventsCount < vipThreshold
    }));

    // Calcolo Statistiche Community
    const totalMembers = fullList.length;
    const multiEventCount = fullList.filter(m => m.eventsCount > 1).length;
    const fedeleCount = fullList.filter(m => m.isRegular).length;
    const vipCount = fullList.filter(m => m.isVip).length;

    const stats = {
      totalMembers,
      multiEventPercentage: totalMembers > 0 ? (multiEventCount / totalMembers) * 100 : 0,
      fedelePercentage: totalMembers > 0 ? (fedeleCount / totalMembers) * 100 : 0,
      vipPercentage: totalMembers > 0 ? (vipCount / totalMembers) * 100 : 0,
    };

    let filteredList = [...fullList];
    if (searchTerm) {
      const lowerSearch = searchTerm.toLowerCase();
      filteredList = filteredList.filter(item => 
        item.attendee.name.toLowerCase().includes(lowerSearch) ||
        (item.attendee.email && item.attendee.email.toLowerCase().includes(lowerSearch)) ||
        (item.attendee.phone && item.attendee.phone.includes(searchTerm))
      );
    }

    filteredList.sort((a, b) => {
      if (sortKey === 'name') {
        const comparison = a.attendee.name.localeCompare(b.attendee.name);
        return sortOrder === 'asc' ? comparison : -comparison;
      } else {
        const comparison = a.eventsCount - b.eventsCount;
        return sortOrder === 'asc' ? comparison : -comparison;
      }
    });

    return { list: filteredList, stats };
  }, [events, searchTerm, sortKey, sortOrder, vipThreshold, regularThreshold]);

  const toggleSort = (key: SortKey) => {
    if (sortKey === key) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortKey(key);
      setSortOrder(key === 'eventsCount' ? 'desc' : 'asc');
    }
  };

  return (
    <div className="space-y-8 animate-fade-in">
      {/* Header & Navigation */}
      <div className="flex items-center gap-4">
        <button onClick={onBack} className="p-2.5 bg-white hover:bg-gray-50 text-gray-500 rounded-xl transition-colors border border-gray-100 shadow-sm">
          <ArrowLeft className="w-5 h-5" />
        </button>
        <div>
          <h1 className="text-2xl font-black text-gray-900 tracking-tight">Anagrafica & Community</h1>
          <p className="text-sm text-gray-500">Analisi e gestione dei membri di ONBEVENTI.</p>
        </div>
      </div>

      {/* Community Stats Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm relative overflow-hidden group">
          <div className="absolute top-0 right-0 w-16 h-16 bg-indigo-50 rounded-bl-full group-hover:scale-110 transition-transform"></div>
          <div className="relative">
            <Users className="w-5 h-5 text-indigo-600 mb-3" />
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Membri Totali</p>
            <p className="text-3xl font-black text-gray-900 mt-1">{stats.totalMembers}</p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm relative overflow-hidden group">
          <div className="absolute top-0 right-0 w-16 h-16 bg-pink-50 rounded-bl-full group-hover:scale-110 transition-transform"></div>
          <div className="relative">
            <Repeat className="w-5 h-5 text-pink-500 mb-3" />
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Ritorno Community</p>
            <p className="text-3xl font-black text-gray-900 mt-1">{stats.multiEventPercentage.toFixed(1)}<span className="text-sm font-bold ml-1">%</span></p>
            <p className="text-[9px] text-gray-400 mt-1 font-medium">Membri con {'>'}1 presenza</p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm relative overflow-hidden group">
          <div className="absolute top-0 right-0 w-16 h-16 bg-green-50 rounded-bl-full group-hover:scale-110 transition-transform"></div>
          <div className="relative">
            <Star className="w-5 h-5 text-green-500 mb-3" />
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Membri Fedeli</p>
            <p className="text-3xl font-black text-gray-900 mt-1">{stats.fedelePercentage.toFixed(1)}<span className="text-sm font-bold ml-1">%</span></p>
            <p className="text-[9px] text-gray-400 mt-1 font-medium">Soglia: {regularThreshold}+ eventi</p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm relative overflow-hidden group">
          <div className="absolute top-0 right-0 w-16 h-16 bg-yellow-50 rounded-bl-full group-hover:scale-110 transition-transform"></div>
          <div className="relative">
            <Trophy className="w-5 h-5 text-yellow-500 mb-3" />
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Membri VIP</p>
