import { AppEvent, Attendee, Expense, ExtraExpense, PaymentStatus } from '../types';
import { initializeApp, getApps, getApp } from "firebase/app";
import { getFirestore, collection, getDocs, doc, setDoc, deleteDoc, getDoc, updateDoc } from "firebase/firestore";

const STORAGE_KEY = 'onbeventi_data_v1';
const EXTRA_EXPENSES_KEY = 'onbeventi_extra_expenses_v1';
const FIREBASE_CONFIG_KEY = 'onbeventi_firebase_config';

const cleanForFirebase = (obj: any): any => {
  if (Array.isArray(obj)) {
    return obj.map(cleanForFirebase);
  } else if (obj !== null && typeof obj === 'object') {
    return Object.fromEntries(
      Object.entries(obj)
        .filter(([_, v]) => v !== undefined)
        .map(([k, v]) => [k, cleanForFirebase(v)])
    );
  }
  return obj;
};

const getDb = () => {
  const configStr = localStorage.getItem(FIREBASE_CONFIG_KEY);
  if (!configStr) return null;
  try {
    const firebaseConfig = JSON.parse(configStr);
    const app = !getApps().length ? initializeApp(firebaseConfig) : getApp();
    return getFirestore(app);
  } catch (e) {
    console.error("Firebase config error", e);
    return null;
  }
};

export const generateId = (): string => {
  return Date.now().toString(36) + Math.random().toString(36).substring(2, 9);
};

export const getEvents = async (): Promise<AppEvent[]> => {
  const db = getDb();
  if (db) {
    try {
      const querySnapshot = await getDocs(collection(db, "events"));
      const events: AppEvent[] = [];
      querySnapshot.forEach((doc) => { 
        const data = doc.data() as AppEvent;
        data.attendees = data.attendees || [];
        data.expenses = data.expenses || [];
        events.push(data); 
      });
      return events;
    } catch (e: any) { 
      console.error("Firebase fetch error", e);
      if (e.code === 'permission-denied') {
        throw new Error('FIREBASE_PERMISSION_DENIED');
      }
      return []; 
    }
  } else {
    const data = localStorage.getItem(STORAGE_KEY);
    const events: AppEvent[] = data ? JSON.parse(data) : [];
    return events.map(e => ({
      ...e,
      attendees: e.attendees || [],
      expenses: e.expenses || []
    }));
  }
};

export const saveEvent = async (event: AppEvent): Promise<void> => {
  const db = getDb();
  const eventToSave = cleanForFirebase({
    ...event,
    attendees: event.attendees || [],
    expenses: event.expenses || []
  });

  if (db) {
    try {
      await setDoc(doc(db, "events", event.id), eventToSave);
    } catch (e: any) {
      if (e.code === 'permission-denied') throw new Error('FIREBASE_PERMISSION_DENIED');
      throw e;
    }
  } else {
    const events = (await getEvents());
    const idx = events.findIndex(e => e.id === event.id);
    if (idx >= 0) events[idx] = eventToSave; else events.push(eventToSave);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(events));
  }
};

// Fix: Implementation of missing event management functions for attendees and expenses

export const addAttendee = async (eventId: string, attendee: Attendee): Promise<AppEvent | null> => {
  const events = await getEvents();
  const event = events.find(e => e.id === eventId);
  if (!event) return null;

  event.attendees = [...(event.attendees || []), attendee];
  await saveEvent(event);
  return event;
};

export const updateAttendee = async (eventId: string, attendee: Attendee): Promise<AppEvent | null> => {
  const events = await getEvents();
  const event = events.find(e => e.id === eventId);
  if (!event) return null;

  event.attendees = (event.attendees || []).map(a => a.id === attendee.id ? attendee : a);
  await saveEvent(event);
  return event;
};

export const deleteAttendee = async (eventId: string, attendeeId: string): Promise<AppEvent | null> => {
  const events = await getEvents();
  const event = events.find(e => e.id === eventId);
  if (!event) return null;

  event.attendees = (event.attendees || []).filter(a => a.id !== attendeeId);
  await saveEvent(event);
  return event;
};

export const togglePaymentStatus = async (eventId: string, attendeeId: string): Promise<AppEvent | null> => {
  const events = await getEvents();
  const event = events.find(e => e.id === eventId);
  if (!event) return null;

  event.attendees = (event.attendees || []).map(a => {
    if (a.id === attendeeId) {
      return { 
        ...a, 
        status: a.status === PaymentStatus.PAID ? PaymentStatus.PENDING : PaymentStatus.PAID 
      };
    }
    return a;
  });
  await saveEvent(event);
  return event;
};

export const addExpense = async (eventId: string, expense: Expense): Promise<AppEvent | null> => {
  const events = await getEvents();
  const event = events.find(e => e.id === eventId);
  if (!event) return null;

  event.expenses = [...(event.expenses || []), expense];
  await saveEvent(event);
  return event;
};

export const updateExpense = async (eventId: string, expense: Expense): Promise<AppEvent | null> => {
  const events = await getEvents();
  const event = events.find(e => e.id === eventId);
  if (!event) return null;

  event.expenses = (event.expenses || []).map(e => e.id === expense.id ? expense : e);
  await saveEvent(event);
  return event;
};

export const deleteExpense = async (eventId: string, expenseId: string): Promise<AppEvent | null> => {
  const events = await getEvents();
  const event = events.find(e => e.id === eventId);
  if (!event) return null;

  event.expenses = (event.expenses || []).filter(e => e.id !== expenseId);
  await saveEvent(event);
  return event;
};

export const updateParticipantGlobally = async (oldKey: string, newData: { name: string, email: string, phone: string }): Promise<void> => {
  const events = await getEvents();

  for (const event of events) {
    let changed = false;
    const updatedAttendees = event.attendees.map(a => {
      const currentKey = (a.email || a.phone || a.name).toLowerCase().trim();
      if (currentKey === oldKey) {
        changed = true;
        return { ...a, ...newData };
      }
      return a;
    });

    if (changed) {
      const updatedEvent = { ...event, attendees: updatedAttendees };
      await saveEvent(updatedEvent);
    }
  }
};

export const deleteEvent = async (eventId: string): Promise<void> => {
  const db = getDb();
  if (db) {
    try {
      await deleteDoc(doc(db, "events", eventId));
    } catch (e: any) {
      if (e.code === 'permission-denied') throw new Error('FIREBASE_PERMISSION_DENIED');
      throw e;
    }
  } else {
    const events = (await getEvents()).filter(e => e.id !== eventId);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(events));
  }
};

export const getExtraExpenses = async (): Promise<ExtraExpense[]> => {
  const db = getDb();
  if (db) {
    try {
      const querySnapshot = await getDocs(collection(db, "extra_expenses"));
      const list: ExtraExpense[] = [];
      querySnapshot.forEach((doc) => { list.push(doc.data() as ExtraExpense); });
      return list;
    } catch (e: any) { 
      if (e.code === 'permission-denied') throw new Error('FIREBASE_PERMISSION_DENIED');
      return []; 
    }
  } else {
    const data = localStorage.getItem(EXTRA_EXPENSES_KEY);
    return data ? JSON.parse(data) : [];
  }
};

export const saveExtraExpense = async (expense: ExtraExpense): Promise<void> => {
  const db = getDb();
  if (db) {
    try {
      await setDoc(doc(db, "extra_expenses", expense.id), cleanForFirebase(expense));
    } catch (e: any) {
      if (e.code === 'permission-denied') throw new Error('FIREBASE_PERMISSION_DENIED');
      throw e;
    }
  } else {
    const list = await getExtraExpenses();
    list.push(expense);
    localStorage.setItem(EXTRA_EXPENSES_KEY, JSON.stringify(list));
  }
};

export const deleteExtraExpense = async (id: string): Promise<void> => {
  const db = getDb();
  if (db) {
    try {
      await deleteDoc(doc(db, "extra_expenses", id));
    } catch (e: any) {
      if (e.code === 'permission-denied') throw new Error('FIREBASE_PERMISSION_DENIED');
      throw e;
    }
  } else {
    const list = (await getExtraExpenses()).filter(e => e.id !== id);
    localStorage.setItem(EXTRA_EXPENSES_KEY, JSON.stringify(list));
  }
};

export const isCloudEnabled = (): boolean => !!localStorage.getItem(FIREBASE_CONFIG_KEY);

import React, { useState, useMemo } from 'react';
import { AppEvent, Attendee } from '../types';
import { Users, Search, Mail, Phone, ArrowLeft, SortAsc, SortDesc, Trophy, UserCheck, Star, Repeat, Target } from 'lucide-react';

interface ParticipantsListProps {
  events: AppEvent[];
  onBack: () => void;
  onParticipantClick: (key: string) => void;
}

type SortKey = 'name' | 'eventsCount';
type SortOrder = 'asc' | 'desc';

export const ParticipantsList: React.FC<ParticipantsListProps> = ({ events, onBack, onParticipantClick }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [sortKey, setSortKey] = useState<SortKey>('name');
  const [sortOrder, setSortOrder] = useState<SortOrder>('asc');

  // Caricamento soglie fedeltà per il calcolo dei badge in lista
  const vipThreshold = Number(localStorage.getItem('onbeventi_vip_threshold') || '5');
  const regularThreshold = Number(localStorage.getItem('onbeventi_regular_threshold') || '3');

  const { list, stats } = useMemo(() => {
    // 1. Trova la data dell'evento più recente
    const sortedEvents = [...events].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    const latestEventDate = sortedEvents.length > 0 ? new Date(sortedEvents[0].date).getTime() : 0;

    const map = new Map<string, { 
      attendee: Attendee, 
      eventsCount: number, 
      totalBookings: number, 
      eventTitles: string[], 
      firstEventDate: number, // Data (timestamp) del primo evento a cui ha partecipato
      key: string,
      isVip: boolean,
      isRegular: boolean
    }>();

    (events || []).forEach(event => {
      const eventTimestamp = new Date(event.date).getTime();
      (event.attendees || []).forEach(a => {
        const key = (a.email || a.phone || a.name).toLowerCase().trim();
        const isPresent = a.isPresent !== false;

        if (map.has(key)) {
          const existing = map.get(key)!;
          existing.totalBookings += 1;
          if (isPresent) {
            existing.eventsCount += 1;
          }
          if (eventTimestamp < existing.firstEventDate) {
            existing.firstEventDate = eventTimestamp;
          }
          existing.eventTitles.push(event.title);
        } else {
          map.set(key, {
            attendee: a,
            eventsCount: isPresent ? 1 : 0,
            totalBookings: 1,
            eventTitles: [event.title],
            firstEventDate: eventTimestamp,
            key: key,
            isVip: false,
            isRegular: false
          });
        }
      });
    });

    const fullList = Array.from(map.values()).map(item => ({
      ...item,
      isVip: item.eventsCount >= vipThreshold,
      isRegular: item.eventsCount >= regularThreshold && item.eventsCount < vipThreshold
    }));

    // --- Calcolo Statistiche Community ---
    const totalMembers = fullList.length;
    const multiEventCount = fullList.filter(m => m.eventsCount > 1).length;
    const fedeleCount = fullList.filter(m => m.isRegular).length;
    const vipCount = fullList.filter(m => m.isVip).length;

    // --- Logica Richiesta: Ritenzione Reale (Esclusi i nuovi dell'ultimo evento) ---
    // Membri "storici": quelli il cui primo evento non è l'ultimo organizzato
    const historicalMembers = fullList.filter(m => m.firstEventDate < latestEventDate);
    const returningHistoricalCount = historicalMembers.filter(m => m.eventsCount > 1).length;
    const realRetentionRate = historicalMembers.length > 0 
      ? (returningHistoricalCount / historicalMembers.length) * 100 
      : 0;

    const stats = {
      totalMembers,
      multiEventPercentage: totalMembers > 0 ? (multiEventCount / totalMembers) * 100 : 0,
      fedelePercentage: totalMembers > 0 ? (fedeleCount / totalMembers) * 100 : 0,
      vipPercentage: totalMembers > 0 ? (vipCount / totalMembers) * 100 : 0,
      realRetentionRate
    };

    let filteredList = [...fullList];
    if (searchTerm) {
      const lowerSearch = searchTerm.toLowerCase();
      filteredList = filteredList.filter(item => 
        item.attendee.name.toLowerCase().includes(lowerSearch) ||
        (item.attendee.email && item.attendee.email.toLowerCase().includes(lowerSearch)) ||
        (item.attendee.phone && item.attendee.phone.includes(searchTerm))
      );
    }

    filteredList.sort((a, b) => {
      if (sortKey === 'name') {
        const comparison = a.attendee.name.localeCompare(b.attendee.name);
        return sortOrder === 'asc' ? comparison : -comparison;
      } else {
        const comparison = a.eventsCount - b.eventsCount;
        return sortOrder === 'asc' ? comparison : -comparison;
      }
    });

    return { list: filteredList, stats };
  }, [events, searchTerm, sortKey, sortOrder, vipThreshold, regularThreshold]);

  const toggleSort = (key: SortKey) => {
    if (sortKey === key) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortKey(key);
      setSortOrder(key === 'eventsCount' ? 'desc' : 'asc');
    }
  };

  return (
    <div className="space-y-8 animate-fade-in">
      {/* Header & Navigation */}
      <div className="flex items-center gap-4">
        <button onClick={onBack} className="p-2.5 bg-white hover:bg-gray-50 text-gray-500 rounded-xl transition-colors border border-gray-100 shadow-sm">
          <ArrowLeft className="w-5 h-5" />
        </button>
        <div>
          <h1 className="text-2xl font-black text-gray-900 tracking-tight">Anagrafica & Community</h1>
          <p className="text-sm text-gray-500">Analisi profonda della partecipazione e fedeltà.</p>
        </div>
      </div>

      {/* Community Stats Grid - 5 Cards Layout */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-4">
        <div className="bg-white p-5 rounded-3xl border border-gray-100 shadow-sm relative overflow-hidden group">
          <div className="absolute top-0 right-0 w-12 h-12 bg-indigo-50 rounded-bl-full"></div>
          <div className="relative">
            <Users className="w-4 h-4 text-indigo-600 mb-2" />
            <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Membri Totali</p>
            <p className="text-2xl font-black text-gray-900 mt-0.5">{stats.totalMembers}</p>
          </div>
        </div>

        <div className="bg-white p-5 rounded-3xl border border-gray-100 shadow-sm relative overflow-hidden group">
          <div className="absolute top-0 right-0 w-12 h-12 bg-pink-50 rounded-bl-full"></div>
          <div className="relative">
            <Repeat className="w-4 h-4 text-pink-500 mb-2" />
            <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Ritorno (Lordo)</p>
            <p className="text-2xl font-black text-gray-900 mt-0.5">{stats.multiEventPercentage.toFixed(1)}%</p>
            <p className="text-[8px] text-gray-400 mt-1 font-medium italic">Su tutta la lista</p>
          </div>
        </div>

        {/* Nuova Statistica: Ritenzione Reale */}
        <div className="bg-indigo-900 p-5 rounded-3xl border border-indigo-950 shadow-xl relative overflow-hidden group text-white">
          <div className="absolute top-0 right-0 w-12 h-12 bg-white/5 rounded-bl-full"></div>
          <div className="relative">
            <Target className="w-4 h-4 text-pink-400 mb-2" />
            <p className="text-[9px] font-black text-indigo-300 uppercase tracking-widest">Ritenzione Reale</p>
            <p className="text-2xl font-black text-white mt-0.5">{stats.realRetentionRate.toFixed(1)}%</p>
            <p className="text-[8px] text-indigo-400 mt-1 font-medium leading-tight">Esclusi i nuovi dell'ultimo evento</p>
          </div>
        </div>

        <div className="bg-white p-5 rounded-3xl border border-gray-100 shadow-sm relative overflow-hidden group">
          <div className="absolute top-0 right-0 w-12 h-12 bg-green-50 rounded-bl-full"></div>
          <div className="relative">
            <Star className="w-4 h-4 text-green-500 mb-2" />
