  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;
    setLoading(true);
    try {
      await updateParticipantGlobally(participantKey, {
        name: formData.name,
        email: formData.email,
        phone: formData.phone,
        gender: (formData.gender as 'M' | 'F' | 'Other') || undefined
      } as any);
