};

import React, { useMemo, useState } from 'react';
import { AppEvent, ExtraExpense, PaymentStatus } from '../types';
import { Calendar, DollarSign, Users, Plus, ArrowRight, MapPin, Clock, Ticket, TrendingDown, Wallet, History, Receipt, Trash2, Save, Filter, ChevronDown, BarChart3 } from 'lucide-react';
import { Button } from './Button';
import { generateId, saveExtraExpense, deleteExtraExpense } from '../services/storageService';

interface DashboardProps {
  events: AppEvent[];
  extraExpenses: ExtraExpense[];
  onCreateClick: () => void;
  onEventClick: (id: string) => void;
  onRefresh: () => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ events, extraExpenses, onCreateClick, onEventClick, onRefresh }) => {
  const [showAddExtra, setShowAddExtra] = useState(false);
  const [newExtra, setNewExtra] = useState({ description: '', amount: '' });
  const [loading, setLoading] = useState(false);
  const [selectedYear, setSelectedYear] = useState<string>('all');

  // Calcolo anni disponibili per il filtro
  const availableYears = useMemo(() => {
    const years = new Set<string>();
    events.forEach(e => years.add(new Date(e.date).getFullYear().toString()));
    extraExpenses.forEach(e => years.add(new Date(e.date).getFullYear().toString()));
    return Array.from(years).sort((a, b) => b.localeCompare(a));
  }, [events, extraExpenses]);

  const stats = useMemo(() => {
    const today = new Date();
    today.setHours(0,0,0,0);

    // Filtro eventi per anno se selezionato
    const filteredEvents = selectedYear === 'all' 
      ? events 
      : events.filter(e => new Date(e.date).getFullYear().toString() === selectedYear);

    // Filtro spese extra per anno se selezionato
    const filteredExtraExpenses = selectedYear === 'all'
      ? extraExpenses
      : extraExpenses.filter(e => new Date(e.date).getFullYear().toString() === selectedYear);

    const upcoming = filteredEvents
      .filter(e => new Date(e.date) >= today)
      .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    const past = filteredEvents
      .filter(e => new Date(e.date) < today)
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    // STATS filtrate
    const totalRevenue = filteredEvents.reduce((acc, curr) => {
      const eventRevenue = curr.attendees.reduce((sum, a) => {
        if (a.status === PaymentStatus.PAID) {
          return sum + (a.paidAmount !== undefined ? a.paidAmount : curr.cost);
        }
        return sum;
      }, 0);
      return acc + eventRevenue;
    }, 0);

    const totalEventExpenses = filteredEvents.reduce((acc, curr) => {
      return acc + (curr.expenses || []).reduce((sum, exp) => sum + exp.amount, 0);
    }, 0);

    const totalExtraExpenses = filteredExtraExpenses.reduce((acc, curr) => acc + curr.amount, 0);
    const totalExpenses = totalEventExpenses + totalExtraExpenses;
    const totalProfit = totalRevenue - totalExpenses;

    const totalEventsCount = filteredEvents.length;
    // Conta solo le partecipazioni REALI (isPresent !== false)
    const totalParticipations = filteredEvents.reduce((acc, curr) => 
      acc + (curr.attendees ? curr.attendees.filter(a => a.isPresent !== false).length : 0), 0);

    return { 
      upcoming, 
      past, 
      totalRevenue, 
      totalExpenses, 
      totalProfit, 
      filteredExtraExpenses,
      totalEventsCount,
      totalParticipations
    };
  }, [events, extraExpenses, selectedYear]);

  const handleAddExtra = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newExtra.description || !newExtra.amount) return;
    setLoading(true);
    try {
      await saveExtraExpense({
        id: generateId(),
        description: newExtra.description,
        amount: Number(newExtra.amount),
        date: new Date().toISOString()
      });
      setNewExtra({ description: '', amount: '' });
      setShowAddExtra(false);
      onRefresh();
    } finally {
      setLoading(false);
    }
  };

  const handleRemoveExtra = async (id: string) => {
    if (!confirm("Eliminare questa spesa extra?")) return;
    await deleteExtraExpense(id);
    onRefresh();
  };

  const renderEventItem = (event: AppEvent) => (
    <div 
      key={event.id} 
      className="p-6 hover:bg-gray-50 transition-all cursor-pointer group border-l-4 border-transparent hover:border-pink-500" 
      onClick={() => onEventClick(event.id)}
    >
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
        <div className="flex items-start gap-4 flex-1">
          <div className="hidden md:flex flex-col items-center justify-center w-16 h-16 bg-indigo-50 rounded-2xl border border-indigo-100 text-indigo-900 shrink-0">
            <span className="text-xs font-bold uppercase">{new Date(event.date).toLocaleDateString('it-IT', { month: 'short' })}</span>
            <span className="text-2xl font-bold">{new Date(event.date).getDate()}</span>
          </div>
          <div>
            <h3 className="text-lg font-bold text-gray-900 group-hover:text-pink-600 transition-colors">{event.title}</h3>
            <div className="flex flex-wrap items-center gap-x-6 gap-y-2 mt-2 text-sm text-gray-500">
              <span className="flex items-center"><Calendar className="w-4 h-4 mr-1.5 text-gray-400"/> {new Date(event.date).toLocaleDateString('it-IT')}</span>
              <span className="flex items-center"><Clock className="w-4 h-4 mr-1.5 text-gray-400"/> {event.time}</span>
              <span className="flex items-center"><MapPin className="w-4 h-4 mr-1.5 text-gray-400"/> {event.location}</span>
            </div>
          </div>
        </div>
        <div className="flex items-center gap-8 w-full md:w-auto justify-between md:justify-end">
          <div className="text-right">
            <p className="text-xs font-semibold text-gray-400 uppercase tracking-wide">Presenti Effettivi</p>
            <div className="flex items-center justify-end gap-1">
              <Users className="w-4 h-4 text-gray-400" />
              <p className="text-lg font-bold text-gray-900">{event.attendees.filter(a => a.isPresent !== false).length}</p>
            </div>
          </div>
          <div className="text-right min-w-[80px]">
            <p className="text-xs font-semibold text-gray-400 uppercase tracking-wide">Costo Base</p>
            <p className="text-lg font-bold text-pink-600">€ {event.cost}</p>
          </div>
          <div className="w-8 h-8 rounded-full bg-gray-100 flex items-center justify-center group-hover:bg-pink-100 group-hover:text-pink-600 transition-colors">
            <ArrowRight className="w-4 h-4" />
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className="space-y-8 animate-fade-in">
      {/* Header Section */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 bg-white p-6 rounded-2xl shadow-sm border border-gray-100 relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-gradient-to-br from-pink-100 to-yellow-100 rounded-full blur-3xl opacity-30 -mr-16 -mt-16 pointer-events-none"></div>
        <div className="relative z-10">
          <h1 className="text-3xl font-extrabold text-gray-900 tracking-tight">Gestione <span className="text-transparent bg-clip-text bg-gradient-to-r from-pink-500 to-purple-600">ONBEVENTI</span></h1>
          <p className="text-gray-500 mt-1">
            {selectedYear === 'all' 
              ? 'Resoconto totale delle attività.' 
              : `Statistiche e attività per l'anno solare ${selectedYear}.`}
          </p>
        </div>

        <div className="relative z-10 flex flex-wrap items-center gap-3 w-full lg:w-auto">
          {/* Yearly Filter */}
          <div className="relative flex-1 lg:flex-none">
            <Filter className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
            <select 
              value={selectedYear}
              onChange={(e) => setSelectedYear(e.target.value)}
              className="pl-10 pr-10 py-2.5 bg-gray-50 border border-gray-200 rounded-xl text-sm font-bold text-gray-700 outline-none focus:ring-2 focus:ring-pink-500 appearance-none min-w-[140px] w-full transition-all cursor-pointer"
            >
              <option value="all">Tutto il tempo</option>
              {availableYears.map(year => (
                <option key={year} value={year}>{year}</option>
              ))}
            </select>
            <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
          </div>

          <Button onClick={onCreateClick} className="shadow-lg shadow-pink-200 flex-1 lg:flex-none">
            <Plus className="w-5 h-5 mr-2" />
            Nuovo Evento
          </Button>
        </div>
      </div>

      {/* Global Stats Grid - Ordered: Activity, Revenue, Expenses, Profit */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {/* 1. Volume Attività */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 relative overflow-hidden">
           <div className="absolute top-0 right-0 w-20 h-20 bg-indigo-50 rounded-bl-full -mr-4 -mt-4"></div>
           <div className="relative">
            <div className="p-3 bg-indigo-100 w-fit rounded-xl text-indigo-600 mb-4 shadow-sm">
              <BarChart3 className="w-6 h-6" />
            </div>
            <p className="text-xs text-gray-400 font-bold uppercase tracking-wider">Volume Attività</p>
            <div className="mt-1">
              <div className="flex items-baseline gap-1.5">
                <span className="text-2xl font-black text-gray-900">{stats.totalEventsCount}</span>
                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-tight">Eventi</span>
              </div>
              <div className="flex items-baseline gap-1.5">
                <span className="text-2xl font-black text-gray-900">{stats.totalParticipations}</span>
                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-tight">Presenze</span>
              </div>
            </div>
          </div>
        </div>

        {/* 2. Incasso Globale */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 relative overflow-hidden">
           <div className="absolute top-0 right-0 w-20 h-20 bg-green-50 rounded-bl-full -mr-4 -mt-4"></div>
           <div className="relative">
            <div className="p-3 bg-green-100 w-fit rounded-xl text-green-600 mb-4 shadow-sm">
              <DollarSign className="w-6 h-6" />
            </div>
            <p className="text-xs text-gray-400 font-bold uppercase tracking-wider">Incasso {selectedYear === 'all' ? 'Globale' : selectedYear}</p>
            <p className="text-3xl font-black text-gray-900 mt-1">€ {stats.totalRevenue.toLocaleString('it-IT', { minimumFractionDigits: 2 })}</p>
          </div>
        </div>

        {/* 3. Uscite Totali */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 relative overflow-hidden">
           <div className="absolute top-0 right-0 w-20 h-20 bg-red-50 rounded-bl-full -mr-4 -mt-4"></div>
           <div className="relative">
            <div className="p-3 bg-red-100 w-fit rounded-xl text-red-600 mb-4 shadow-sm">
              <TrendingDown className="w-6 h-6" />
            </div>
            <p className="text-xs text-gray-400 font-bold uppercase tracking-wider">Uscite {selectedYear === 'all' ? 'Totali' : selectedYear}</p>
            <p className="text-3xl font-black text-gray-900 mt-1">€ {stats.totalExpenses.toLocaleString('it-IT', { minimumFractionDigits: 2 })}</p>
          </div>
        </div>

        {/* 4. Profitto Globale */}
        <div className="bg-indigo-950 p-6 rounded-2xl shadow-xl border border-indigo-900 relative overflow-hidden">
           <div className="absolute top-0 right-0 w-32 h-32 bg-pink-500/20 rounded-bl-full -mr-8 -mt-8 blur-xl"></div>
           <div className="relative">
            <div className="p-3 bg-white/10 w-fit rounded-xl text-pink-400 mb-4 shadow-inner">
              <Wallet className="w-6 h-6" />
            </div>
            <p className="text-xs text-indigo-300 font-bold uppercase tracking-wider">Profitto {selectedYear === 'all' ? 'Globale' : selectedYear}</p>
            <p className="text-3xl font-black text-white mt-1">€ {stats.totalProfit.toLocaleString('it-IT', { minimumFractionDigits: 2 })}</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Left/Main: Events */}
        <div className="lg:col-span-2 space-y-8">
          {/* Upcoming Events */}
          <section className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
            <div className="px-6 py-5 border-b border-gray-100 bg-gray-50/50 flex justify-between items-center">
              <h2 className="text-lg font-bold text-gray-800 flex items-center gap-2">
                <Ticket className="w-5 h-5 text-pink-500" />
                Prossimi Eventi {selectedYear !== 'all' && `(${selectedYear})`}
              </h2>
            </div>
            {stats.upcoming.length === 0 ? (
              <div className="p-12 text-center text-gray-400">Nessun evento in programma {selectedYear !== 'all' ? `per il ${selectedYear}` : ''}.</div>
            ) : (
              <div className="divide-y divide-gray-100">
                {stats.upcoming.map(renderEventItem)}
              </div>
            )}
          </section>

          {/* Past Events */}
          <section className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden opacity-90">
            <div className="px-6 py-5 border-b border-gray-100 bg-indigo-50/30 flex justify-between items-center">
              <h2 className="text-lg font-bold text-gray-600 flex items-center gap-2">
                <History className="w-5 h-5 text-indigo-400" />
                Eventi Passati {selectedYear !== 'all' && `(${selectedYear})`}
              </h2>
            </div>
            {stats.past.length === 0 ? (
              <div className="p-8 text-center text-gray-400 text-sm italic">Nessun evento passato registrato {selectedYear !== 'all' ? `nel ${selectedYear}` : ''}.</div>
            ) : (
              <div className="divide-y divide-gray-100">
                {stats.past.map(renderEventItem)}
              </div>
            )}
          </section>
        </div>

        {/* Right Column: Extra Expenses */}
        <div className="space-y-8">
          <section className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
            <div className="px-6 py-5 border-b border-gray-100 bg-red-50/30 flex justify-between items-center">
              <h2 className="text-md font-bold text-gray-800 flex items-center gap-2">
                <Receipt className="w-5 h-5 text-red-500" />
                Spese Extra {selectedYear !== 'all' && `(${selectedYear})`}
              </h2>
              <button 
                onClick={() => setShowAddExtra(!showAddExtra)}
                className="text-[10px] bg-red-600 text-white px-2 py-1 rounded-full font-bold uppercase hover:bg-red-700 transition-colors"
              >
                {showAddExtra ? 'Chiudi' : 'Aggiungi'}
              </button>
            </div>

            {showAddExtra && (
              <div className="p-4 bg-red-50/50 border-b border-red-100 animate-slide-down">
                <form onSubmit={handleAddExtra} className="space-y-3">
                   <input 
                    className="w-full text-xs px-3 py-2 rounded-lg border-gray-200 focus:ring-2 focus:ring-red-500"
                    placeholder="Descrizione (es. Affitto Ufficio)"
                    value={newExtra.description}
                    onChange={e => setNewExtra(p => ({...p, description: e.target.value}))}
                    required
                   />
                   <div className="flex gap-2">
                    <input 
                      type="number"
                      step="0.01"
                      className="w-full text-xs px-3 py-2 rounded-lg border-gray-200 focus:ring-2 focus:ring-red-500"
                      placeholder="Importo (€)"
                      value={newExtra.amount}
                      onChange={e => setNewExtra(p => ({...p, amount: e.target.value}))}
                      required
                    />
                    <button type="submit" disabled={loading} className="bg-indigo-950 text-white px-3 py-1 rounded-lg text-xs font-bold shadow-sm">
                      <Save className="w-3 h-3" />
                    </button>
                   </div>
                </form>
              </div>
            )}

            <div className="max-h-[500px] overflow-y-auto">
              {stats.filteredExtraExpenses.length === 0 ? (
                <p className="p-6 text-center text-xs text-gray-400 italic">Nessuna spesa extra registrata {selectedYear !== 'all' ? `nel ${selectedYear}` : ''}.</p>
              ) : (
                <div className="divide-y divide-gray-50">
                  {stats.filteredExtraExpenses.sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()).map(exp => (
                    <div key={exp.id} className="p-4 group hover:bg-gray-50 flex justify-between items-center">
                      <div>
                        <p className="text-xs font-bold text-gray-800">{exp.description}</p>
                        <p className="text-[10px] text-gray-400">{new Date(exp.date).toLocaleDateString()}</p>
                      </div>
                      <div className="flex items-center gap-3">
                        <span className="text-xs font-black text-red-600">- €{exp.amount.toFixed(2)}</span>
                        <button 
                          onClick={() => handleRemoveExtra(exp.id)}
                          className="opacity-0 group-hover:opacity-100 text-gray-300 hover:text-red-600 transition-all"
                        >
                          <Trash2 className="w-3 h-3" />
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
            {stats.filteredExtraExpenses.length > 0 && (
              <div className="p-3 bg-gray-50 text-right text-[10px] font-bold text-gray-500 uppercase">
                Totale {selectedYear === 'all' ? '' : selectedYear}: <span className="text-red-600">€ {stats.filteredExtraExpenses.reduce((a,b)=>a+b.amount,0).toFixed(2)}</span>
              </div>
            )}
          </section>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { AppEvent, Attendee, Expense, PaymentStatus } from '../types';
import { Button } from './Button';
import { 
  ArrowLeft, UserPlus, CheckCircle, XCircle, Trash2, 
  Calendar, MapPin, Euro, Clock, Edit2, Plus, 
  TrendingUp, TrendingDown, Wallet, Users, Save, X, AlertTriangle, Phone, Mail, UserCheck, Tag, UserMinus, UserX
} from 'lucide-react';
import { 
  addAttendee, togglePaymentStatus, deleteAttendee, 
  deleteEvent, addExpense, deleteExpense, updateAttendee, updateExpense, generateId
} from '../services/storageService';

interface EventDetailsProps {
  event: AppEvent;
  allEvents: AppEvent[];
  onBack: () => void;
  onUpdate: (updatedEvent: AppEvent) => void;
  onDelete: () => void;
  onEditEvent: () => void;
  onParticipantClick: (participantKey: string) => void;
}

export const EventDetails: React.FC<EventDetailsProps> = ({ 
  event, 
  allEvents, 
  onBack, 
  onUpdate, 
  onDelete, 
  onEditEvent,
  onParticipantClick
}) => {
  const [showAddAttendee, setShowAddAttendee] = useState(false);
  const [showAddExpense, setShowAddExpense] = useState(false);
  const [loading, setLoading] = useState(false);

  const [newAttendee, setNewAttendee] = useState({ name: '', email: '', phone: '', paidAmount: '', gender: '' });
  const [suggestions, setSuggestions] = useState<Attendee[]>([]);

  const [editingAttendeeId, setEditingAttendeeId] = useState<string | null>(null);
  const [editAttendeeData, setEditAttendeeData] = useState({ name: '', email: '', phone: '', paidAmount: '', gender: '' });

  const [newExpense, setNewExpense] = useState({ description: '', amount: '' });
  const [editingExpenseId, setEditingExpenseId] = useState<string | null>(null);
  const [editExpenseData, setEditExpenseData] = useState({ description: '', amount: '' });

  const [confirmModal, setConfirmModal] = useState<{
    isOpen: boolean;
    type: 'DELETE_EVENT' | 'DELETE_ATTENDEE' | 'DELETE_EXPENSE' | null;
    itemId?: string;
    message: string;
  }>({
    isOpen: false,
    type: null,
    message: ''
  });

  const globalParticipants = useMemo(() => {
    const map = new Map<string, Attendee>();
    (allEvents || []).forEach(ev => {
      (ev.attendees || []).forEach(at => {
        const key = (at.email || at.phone || at.name).toLowerCase().trim();
        map.set(key, at);
      });
    });
    return Array.from(map.values());
  }, [allEvents]);

  const handleNameChange = (val: string) => {
    setNewAttendee(prev => ({ ...prev, name: val }));
    if (val.length >= 2) {
      const filtered = globalParticipants.filter(p => 
        p.name.toLowerCase().includes(val.toLowerCase())
      ).slice(0, 5);
      setSuggestions(filtered);
    } else {
      setSuggestions([]);
    }
  };

  const selectSuggestion = (p: Attendee) => {
    setNewAttendee({
      name: p.name,
      email: p.email || '',
      phone: p.phone || '',
      gender: p.gender || '',
      paidAmount: '' 
    });
    setSuggestions([]);
  };

  const handleAddAttendee = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newAttendee.name.trim()) return;

    setLoading(true);

    if (event.maxAttendees && (event.attendees || []).length >= event.maxAttendees) {
      alert("Numero massimo di partecipanti raggiunto.");
      setLoading(false);
      return;
    }

    const attendee: Attendee = {
      id: generateId(),
      name: newAttendee.name,
      email: newAttendee.email,
      phone: newAttendee.phone,
      gender: (newAttendee.gender as 'M' | 'F' | 'Other') || undefined,
      paidAmount: newAttendee.paidAmount ? Number(newAttendee.paidAmount) : undefined,
      status: PaymentStatus.PENDING,
      registrationDate: new Date().toISOString(),
      isPresent: true
    };

    try {
      const updated = await addAttendee(event.id, attendee);
      if (updated) {
        onUpdate(updated);
        setNewAttendee({ name: '', email: '', phone: '', paidAmount: '', gender: '' });
        setShowAddAttendee(false);
        setSuggestions([]);
      }
    } catch (err) {
      console.error("Error adding attendee:", err);
      alert("Errore durante l'aggiunta.");
    } finally {
      setLoading(false);
    }
  };

  const startEditingAttendee = (attendee: Attendee) => {
    setEditingAttendeeId(attendee.id);
    setEditAttendeeData({ 
      name: attendee.name, 
      email: attendee.email || '', 
      phone: attendee.phone || '',
      gender: attendee.gender || '',
      paidAmount: attendee.paidAmount !== undefined ? attendee.paidAmount.toString() : ''
    });
  };

  const cancelEditingAttendee = () => {
    setEditingAttendeeId(null);
    setEditAttendeeData({ name: '', email: '', phone: '', paidAmount: '', gender: '' });
  };

  const saveEditedAttendee = async (originalAttendee: Attendee) => {
    const updatedAttendee: Attendee = {
      ...originalAttendee,
      name: editAttendeeData.name,
      email: editAttendeeData.email,
      phone: editAttendeeData.phone,
      gender: (editAttendeeData.gender as 'M' | 'F' | 'Other') || undefined,
      paidAmount: editAttendeeData.paidAmount ? Number(editAttendeeData.paidAmount) : undefined
    };
    setLoading(true);
    try {
      const updatedEvent = await updateAttendee(event.id, updatedAttendee);
      if (updatedEvent) {
        onUpdate(updatedEvent);
        setEditingAttendeeId(null);
      }
    } finally {
      setLoading(false);
    }
  };

  const handleTogglePayment = async (attendeeId: string) => {
    setLoading(true);
    try {
      const updated = await togglePaymentStatus(event.id, attendeeId);
      if (updated) onUpdate(updated);
    } finally {
      setLoading(false);
    }
  };

  const handleTogglePresence = async (attendee: Attendee) => {
    setLoading(true);
    const updatedAttendee = { ...attendee, isPresent: attendee.isPresent === false ? true : false };
    try {
      const updatedEvent = await updateAttendee(event.id, updatedAttendee);
      if (updatedEvent) onUpdate(updatedEvent);
    } finally {
      setLoading(false);
    }
  };

  const requestDeleteAttendee = (attendeeId: string) => {
    setConfirmModal({ isOpen: true, type: 'DELETE_ATTENDEE', itemId: attendeeId, message: 'Sei sicuro di voler rimuovere questo membro dalla lista?' });
  };
  const requestDeleteExpense = (expenseId: string) => {
    setConfirmModal({ isOpen: true, type: 'DELETE_EXPENSE', itemId: expenseId, message: 'Sei sicuro di voler eliminare questa voce di spesa?' });
  };
  const requestDeleteEvent = () => {
    setConfirmModal({ isOpen: true, type: 'DELETE_EVENT', message: 'ATTENZIONE: Stai per eliminare definitivamente questo evento. Sei sicuro?' });
  };

  const executeDelete = async () => {
    setLoading(true);
    try {
      if (confirmModal.type === 'DELETE_EVENT') {
        await deleteEvent(event.id);
        onDelete();
      } else if (confirmModal.type === 'DELETE_ATTENDEE' && confirmModal.itemId) {
        const updated = await deleteAttendee(event.id, confirmModal.itemId);
        if (updated) onUpdate(updated);
      } else if (confirmModal.type === 'DELETE_EXPENSE' && confirmModal.itemId) {
        const updated = await deleteExpense(event.id, confirmModal.itemId);
        if (updated) onUpdate(updated);
      }
    } finally {
      setLoading(false);
      setConfirmModal({ isOpen: false, type: null, message: '' });
    }
  };

  const handleAddExpense = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    const expense: Expense = { id: generateId(), description: newExpense.description, amount: Number(newExpense.amount) };
    try {
      const updated = await addExpense(event.id, expense);
      if (updated) {
        onUpdate(updated);
        setNewExpense({ description: '', amount: '' });
        setShowAddExpense(false);
      }
    } finally { setLoading(false); }
  };

  const startEditingExpense = (expense: Expense) => {
    setEditingExpenseId(expense.id);
    setEditExpenseData({ description: expense.description, amount: expense.amount.toString() });
  };

  const saveEditedExpense = async (originalExpense: Expense) => {
    if (!editExpenseData.description || !editExpenseData.amount) return;
    const updatedExpense: Expense = { ...originalExpense, description: editExpenseData.description, amount: Number(editExpenseData.amount) };
    setLoading(true);
    try {
      const updatedEvent = await updateExpense(event.id, updatedExpense);
      if (updatedEvent) {
        onUpdate(updatedEvent);
        setEditingExpenseId(null);
      }
    } finally { setLoading(false); }
  };

  const attendees = event.attendees || [];
  const expenses = event.expenses || [];

  const totalCollected = attendees.reduce((acc, a) => {
    if (a.status === PaymentStatus.PAID) {
      return acc + (a.paidAmount !== undefined ? a.paidAmount : event.cost);
    }
    return acc;
  }, 0);

  const totalExpenses = expenses.reduce((acc, curr) => acc + curr.amount, 0);
  const netProfit = totalCollected - totalExpenses;
  const isProfitPositive = netProfit >= 0;

  const occupancyPercentage = event.maxAttendees ? Math.min((attendees.length / event.maxAttendees) * 100, 100) : 0;

  // --- Calcolo Demografia REALE per l'evento (solo presenti) ---
  const presentAttendees = attendees.filter(a => a.isPresent !== false);
  const malesCount = presentAttendees.filter(a => a.gender === 'M').length;
  const femalesCount = presentAttendees.filter(a => a.gender === 'F').length;
  const totalPresent = presentAttendees.length;
  const malePercent = totalPresent > 0 ? Math.round((malesCount / totalPresent) * 100) : 0;
  const femalePercent = totalPresent > 0 ? Math.round((femalesCount / totalPresent) * 100) : 0;

  return (
    <div className="space-y-8 animate-fade-in pb-10 relative">
      {loading && <div className="fixed inset-0 z-[60] bg-white/50 backdrop-blur-sm flex items-center justify-center"><div className="animate-spin rounded-full h-10 w-10 border-b-2 border-pink-600"></div></div>}

      {confirmModal.isOpen && (
        <div className="fixed inset-0 bg-indigo-950/80 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl max-w-sm w-full p-6 animate-scale-in border border-gray-100">
            <div className="flex flex-col items-center text-center mb-6">
              <div className="w-14 h-14 bg-red-50 rounded-full flex items-center justify-center mb-4 text-red-500"><AlertTriangle className="w-7 h-7" /></div>
              <h3 className="text-xl font-bold text-gray-900">Conferma Eliminazione</h3>
              <p className="text-gray-500 mt-2 text-sm leading-relaxed">{confirmModal.message}</p>
            </div>
            <div className="flex gap-3 justify-center">
              <Button variant="secondary" onClick={() => setConfirmModal({ isOpen: false, type: null, message: '' })} className="w-full">Annulla</Button>
              <Button variant="danger" onClick={executeDelete} className="w-full shadow-red-200" isLoading={loading}>Elimina</Button>
            </div>
          </div>
        </div>
      )}

      <div className="flex flex-col lg:flex-row lg:items-center gap-6 justify-between bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
        <div className="flex items-start gap-5">
          <button onClick={onBack} className="p-2.5 bg-gray-50 hover:bg-gray-100 text-gray-600 rounded-xl transition-colors mt-1" type="button"><ArrowLeft className="w-5 h-5" /></button>
          <div>
            <h1 className="text-3xl font-extrabold text-gray-900 tracking-tight">{event.title}</h1>
            <div className="flex flex-wrap items-center gap-4 mt-2 text-sm text-gray-500 font-medium">
              <span className="flex items-center bg-indigo-50 text-indigo-700 px-3 py-1 rounded-full"><Calendar className="w-3.5 h-3.5 mr-1.5" /> {new Date(event.date).toLocaleDateString('it-IT')}</span>
              <span className="flex items-center bg-gray-100 text-gray-600 px-3 py-1 rounded-full"><MapPin className="w-3.5 h-3.5 mr-1.5" /> {event.location}</span>
            </div>
          </div>
        </div>
        <div className="flex gap-3">
          <Button variant="secondary" onClick={onEditEvent} type="button"><Edit2 className="w-4 h-4 mr-2" /> Modifica</Button>
          <Button variant="danger" onClick={requestDeleteEvent} type="button">Elimina Evento</Button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 relative overflow-hidden">
          <div className="absolute top-0 right-0 w-24 h-24 bg-green-50 rounded-bl-full -mr-5 -mt-5"></div>
          <div className="relative">
             <div className="flex items-center gap-3 mb-2">
                <div className="p-2 bg-green-100 text-green-600 rounded-lg"><TrendingUp className="w-5 h-5" /></div>
                <p className="text-sm font-semibold text-gray-500 uppercase">Incasso Reale</p>
              </div>
              <p className="text-3xl font-extrabold text-gray-900">€ {totalCollected.toLocaleString('it-IT', { minimumFractionDigits: 2 })}</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 relative overflow-hidden">
          <div className="absolute top-0 right-0 w-24 h-24 bg-red-50 rounded-bl-full -mr-5 -mt-5"></div>
          <div className="relative">
            <div className="flex items-center gap-3 mb-2">
              <div className="p-2 bg-red-100 text-red-600 rounded-lg"><TrendingDown className="w-5 h-5" /></div>
              <p className="text-sm font-semibold text-gray-500 uppercase">Spese</p>
            </div>
            <p className="text-3xl font-extrabold text-gray-900">€ {totalExpenses.toLocaleString('it-IT', { minimumFractionDigits: 2 })}</p>
          </div>
        </div>
        <div className={`p-6 rounded-2xl shadow-lg border relative overflow-hidden flex flex-col justify-center ${isProfitPositive ? 'bg-indigo-950 border-indigo-900 text-white' : 'bg-red-50 border-red-100 text-red-900'}`}>
          <div className="relative z-10">
            <div className="flex items-center gap-3 mb-2">
              <div className={`p-2 rounded-lg ${isProfitPositive ? 'bg-white/10 text-pink-400' : 'bg-red-100 text-red-600'}`}><Wallet className="w-5 h-5" /></div>
              <p className={`text-sm font-semibold uppercase ${isProfitPositive ? 'text-indigo-200' : 'text-red-700'}`}>Profitto Netto</p>
            </div>
            <p className="text-4xl font-black tracking-tight">€ {netProfit.toLocaleString('it-IT', { minimumFractionDigits: 2 })}</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="space-y-8">
          <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
            <h3 className="text-lg font-bold text-gray-900 mb-6 flex items-center"><span className="w-1.5 h-6 bg-pink-500 rounded-full mr-3"></span>Dettagli</h3>
            <div className="space-y-5">
              <div className="flex justify-between items-center border-b border-gray-50 pb-3"><span className="text-gray-500 text-sm flex items-center gap-2 font-medium"><Clock className="w-4 h-4 text-gray-400" /> Orario</span><span className="font-semibold text-gray-800 bg-gray-50 px-3 py-1 rounded-md">{event.time}</span></div>
              <div className="flex justify-between items-center border-b border-gray-50 pb-3"><span className="text-gray-500 text-sm flex items-center gap-2 font-medium"><Euro className="w-4 h-4 text-gray-400" /> Costo Biglietto</span><span className="font-semibold text-gray-800 bg-gray-50 px-3 py-1 rounded-md">€ {event.cost}</span></div>
              <div className="flex justify-between items-center border-b border-gray-50 pb-3"><span className="text-gray-500 text-sm flex items-center gap-2 font-medium"><Users className="w-4 h-4 text-gray-400" /> Max Partecipanti</span><span className="font-semibold text-gray-800 bg-gray-50 px-3 py-1 rounded-md">{event.maxAttendees ? event.maxAttendees : '∞'}</span></div>
              <div className="pt-4 pb-2">
                <div className="flex justify-between text-xs font-bold text-gray-500 uppercase mb-2"><span>Occupazione</span><span>{event.maxAttendees ? Math.round(occupancyPercentage) : 100}%</span></div>
                <div className="w-full bg-gray-100 rounded-full h-3 overflow-hidden"><div className="h-3 rounded-full bg-gradient-to-r from-pink-500 to-yellow-400 shadow-sm transition-all duration-500" style={{ width: `${event.maxAttendees ? occupancyPercentage : 100}%` }}></div></div>
                <p className="text-xs text-center mt-2 text-gray-400">{attendees.length} iscritti ({totalPresent} presenti)</p>

                {/* --- DEMOGRAFIA EVENTO REALE --- */}
                <div className="mt-6 pt-4 border-t border-gray-50 flex items-center justify-between">
                  <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Mix Genere Presenti</span>
                  <div className="flex gap-2">
                    <span className="text-[10px] font-bold text-blue-600 bg-blue-50 px-2 py-0.5 rounded-full border border-blue-100 flex items-center gap-1">
                      M: {malePercent}%
                    </span>
                    <span className="text-[10px] font-bold text-pink-600 bg-pink-50 px-2 py-0.5 rounded-full border border-pink-100 flex items-center gap-1">
                      F: {femalePercent}%
                    </span>
                  </div>
                </div>
              </div>
            </div>
          </div>

          <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
            <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-gray-50/50"><h3 className="font-bold text-gray-900">Spese & Costi</h3><button onClick={() => setShowAddExpense(!showAddExpense)} className="text-xs text-white bg-indigo-900 hover:bg-indigo-800 px-3 py-1.5 rounded-full font-medium flex items-center transition-colors shadow-sm" type="button"><Plus className="w-3 h-3 mr-1" /> Nuova Spesa</button></div>
            {showAddExpense && (
              <div className="p-5 bg-indigo-50 border-b border-indigo-100 animate-slide-down">
                 <form onSubmit={handleAddExpense} className="flex flex-col gap-3">
                    <input type="text" placeholder="Descrizione" className="w-full text-sm px-3 py-2 border-indigo-200 rounded-lg focus:ring-2 focus:ring-pink-500" required value={newExpense.description} onChange={e => setNewExpense(prev => ({...prev, description: e.target.value}))} />
                    <div className="flex gap-2">
                      <input type="number" placeholder="Importo (€)" className="w-full text-sm px-3 py-2 border-indigo-200 rounded-lg focus:ring-2 focus:ring-pink-500" required min="0" step="0.01" value={newExpense.amount} onChange={e => setNewExpense(prev => ({...prev, amount: e.target.value}))} />
                      <Button type="submit" className="whitespace-nowrap text-xs py-1" isLoading={loading}>Salva</Button>
                    </div>
                 </form>
              </div>
            )}
            <div className="divide-y divide-gray-100">
              {expenses.length === 0 ? (<p className="p-6 text-center text-sm text-gray-400">Nessuna spesa registrata.</p>) : (
                expenses.map(exp => {
                  const isEditing = editingExpenseId === exp.id;
                  return (
                    <div key={exp.id} className={`p-4 flex flex-col sm:flex-row justify-between sm:items-center gap-2 group transition-colors ${isEditing ? 'bg-indigo-50/50' : 'hover:bg-gray-50'}`}>
                      {isEditing ? (
                        <div className="flex-1 flex gap-2"><input className="flex-1 border border-pink-300 rounded-md text-sm px-3 py-1.5" value={editExpenseData.description} onChange={e => setEditExpenseData(p => ({...p, description: e.target.value}))} /><input className="w-24 border border-pink-300 rounded-md text-sm px-3 py-1.5" type="number" value={editExpenseData.amount} onChange={e => setEditExpenseData(p => ({...p, amount: e.target.value}))} /><button onClick={() => saveEditedExpense(exp)} className="bg-green-500 p-1.5 rounded-lg text-white"><Save className="w-4 h-4" /></button></div>
                      ) : (
                        <>
                          <div className="flex-1 min-w-0 mr-2"><p className="text-sm font-semibold text-gray-800 break-words">{exp.description}</p></div>
                          <div className="flex items-center gap-3"><p className="text-sm font-bold text-red-500 bg-red-50 px-2 py-1 rounded">- €{exp.amount}</p><div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity"><button onClick={() => startEditingExpense(exp)} className="p-1.5 text-gray-300 hover:text-indigo-600 rounded-full"><Edit2 className="w-4 h-4" /></button><button onClick={() => requestDeleteExpense(exp.id)} className="p-1.5 text-gray-300 hover:text-red-500 rounded-full"><Trash2 className="w-4 h-4" /></button></div></div>
                        </>
                      )}
                    </div>
                  );
