              )}
            </div>
          </div>
        </div>

        <div className="lg:col-span-2 flex flex-col h-full">
          <div className="bg-white rounded-2xl shadow-sm border border-gray-100 flex flex-col h-full overflow-hidden">
            <div className="p-6 border-b border-gray-100 flex justify-between items-center bg-white">
              <div className="flex items-center gap-3"><div className="p-2 bg-pink-100 text-pink-600 rounded-lg"><Users className="w-5 h-5" /></div><div><h2 className="font-bold text-gray-900 text-lg">Lista Membri Iscritti</h2><p className="text-xs text-gray-500">Gestisci partecipazioni e pagamenti</p></div></div>
              <Button onClick={() => setShowAddAttendee(!showAddAttendee)} variant="primary" className="text-xs" disabled={!!event.maxAttendees && attendees.length >= event.maxAttendees} type="button"><UserPlus className="w-4 h-4 mr-2" /> Aggiungi</Button>
            </div>

            {showAddAttendee && (
              <div className="p-6 bg-gradient-to-r from-indigo-50 to-pink-50 border-b border-pink-100 animate-slide-down">
                <h4 className="text-sm font-bold text-indigo-900 mb-4 uppercase tracking-wide">Nuovo Partecipante</h4>
                <form onSubmit={handleAddAttendee} className="space-y-4 relative">
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                    <div className="relative">
                      <input type="text" required className="w-full px-4 py-2 border border-gray-200 rounded-lg text-sm focus:ring-2 focus:ring-pink-500" value={newAttendee.name} onChange={e => handleNameChange(e.target.value)} placeholder="Nome Cognome *" autoComplete="off" />
                      {suggestions.length > 0 && (
                        <div className="absolute z-[70] left-0 right-0 mt-1 bg-white border border-gray-200 rounded-xl shadow-2xl overflow-hidden animate-scale-in">
                           <ul className="divide-y divide-gray-50">
                              {suggestions.map((p, idx) => (<li key={idx}><button type="button" onClick={() => selectSuggestion(p)} className="w-full text-left px-4 py-3 hover:bg-pink-50 flex items-center justify-between group"><div><p className="text-sm font-bold text-gray-900">{p.name}</p></div><Plus className="w-3 h-3 text-gray-400 group-hover:text-pink-600" /></button></li>))}
                           </ul>
                        </div>
                      )}
                    </div>
                    <input type="email" className="w-full px-4 py-2 border border-gray-200 rounded-lg text-sm" value={newAttendee.email} onChange={e => setNewAttendee(prev => ({ ...prev, email: e.target.value }))} placeholder="Email" />
                    <input type="tel" className="w-full px-4 py-2 border border-gray-200 rounded-lg text-sm" value={newAttendee.phone} onChange={e => setNewAttendee(prev => ({ ...prev, phone: e.target.value }))} placeholder="Telefono" />
                    <select 
                      className="w-full px-4 py-2 border border-gray-200 rounded-lg text-sm focus:ring-2 focus:ring-pink-500 bg-white"
                      value={newAttendee.gender}
                      onChange={e => setNewAttendee(prev => ({ ...prev, gender: e.target.value }))}
                    >
                      <option value="">Sesso (Opzionale)</option>
                      <option value="M">Maschio</option>
                      <option value="F">Femmina</option>
                      <option value="Other">Altro / N.D.</option>
                    </select>
                  </div>
                  <div className="flex justify-between items-center pt-2">
                    <input type="number" step="0.01" className="max-w-[200px] px-4 py-2 border border-gray-200 rounded-lg text-sm font-bold text-pink-600 bg-white" value={newAttendee.paidAmount} onChange={e => setNewAttendee(prev => ({ ...prev, paidAmount: e.target.value }))} placeholder={`Quota (Std: €${event.cost})`} />
                    <div className="flex gap-2"><Button type="button" variant="ghost" onClick={() => setShowAddAttendee(false)}>Chiudi</Button><Button type="submit" isLoading={loading}>Inserisci</Button></div>
                  </div>
                </form>
              </div>
            )}

            <div className="overflow-x-auto flex-1">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="text-xs font-semibold text-gray-300 bg-indigo-950 border-b border-indigo-900">
                    <th className="px-6 py-4">MEMBRO</th>
                    <th className="px-6 py-4">CONTATTI</th>
                    <th className="px-6 py-4 text-center">QUOTA PAGATA</th>
                    <th className="px-6 py-4 text-center">STATO</th>
                    <th className="px-6 py-4 text-right">AZIONI</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {attendees.length === 0 ? (
                    <tr><td colSpan={5} className="px-6 py-16 text-center text-gray-400">La lista è vuota</td></tr>
                  ) : (
                    attendees.map(attendee => {
                      const isEditing = editingAttendeeId === attendee.id;
                      const isAbsent = attendee.isPresent === false;
                      const hasCustomAmount = attendee.paidAmount !== undefined && attendee.paidAmount !== event.cost;
                      const displayAmount = attendee.paidAmount !== undefined ? attendee.paidAmount : event.cost;
                      const participantKey = (attendee.email || attendee.phone || attendee.name).toLowerCase().trim();

                      return (
                        <tr 
                          key={attendee.id} 
                          className={`group transition-colors ${isEditing ? 'bg-pink-50' : 'hover:bg-indigo-50/50 cursor-pointer'} ${isAbsent ? 'opacity-60 grayscale-[0.5]' : ''}`}
                          onClick={() => !isEditing && onParticipantClick(participantKey)}
                          title={!isEditing ? "Vai alla scheda membro" : ""}
                        >
                          <td className="px-6 py-4">
                            {isEditing ? (
                              <div className="space-y-2" onClick={e => e.stopPropagation()}>
                                <input className="w-full border border-pink-300 rounded-md text-sm px-3 py-1.5" value={editAttendeeData.name} onChange={e => setEditAttendeeData(p => ({...p, name: e.target.value}))} />
                                <select className="w-full border border-pink-300 rounded-md text-sm px-3 py-1.5 bg-white" value={editAttendeeData.gender} onChange={e => setEditAttendeeData(p => ({...p, gender: e.target.value}))}>
                                  <option value="">Sesso</option>
                                  <option value="M">Maschio</option>
                                  <option value="F">Femmina</option>
                                  <option value="Other">Altro</option>
                                </select>
                              </div>
                            ) : (
                              <div className="flex items-center gap-2">
                                <span className={`font-semibold text-gray-900 ${isAbsent ? 'line-through' : ''}`}>{attendee.name}</span>
                                {attendee.gender && (
                                  <span className={`text-[8px] px-1 rounded font-black ${attendee.gender === 'M' ? 'bg-blue-100 text-blue-600' : attendee.gender === 'F' ? 'bg-pink-100 text-pink-600' : 'bg-gray-100 text-gray-500'}`}>
                                    {attendee.gender}
                                  </span>
                                )}
                                {hasCustomAmount && <span className="text-[10px] bg-amber-100 text-amber-700 px-1.5 py-0.5 rounded font-bold uppercase flex items-center gap-0.5"><Tag className="w-2.5 h-2.5" /> Special</span>}
                              </div>
                            )}
                          </td>
                          <td className="px-6 py-4 text-xs text-gray-500">
                            {isEditing ? (
                              <div className="flex flex-col gap-1" onClick={e => e.stopPropagation()}><input className="border rounded px-2 py-1" placeholder="Email" value={editAttendeeData.email} onChange={e => setEditAttendeeData(p => ({...p, email: e.target.value}))} /><input className="border rounded px-2 py-1" placeholder="Telefono" value={editAttendeeData.phone} onChange={e => setEditAttendeeData(p => ({...p, phone: e.target.value}))} /></div>
                            ) : (
                              <div>{attendee.email && <div className="flex items-center mb-0.5"><Mail className="w-3 h-3 mr-1" /> {attendee.email}</div>}{attendee.phone && <div className="flex items-center"><Phone className="w-3 h-3 mr-1" /> {attendee.phone}</div>}</div>
                            )}
                          </td>
                          <td className="px-6 py-4 text-center">
                            {isEditing ? (
                              <input onClick={e => e.stopPropagation()} type="number" step="0.01" className="w-24 border border-pink-300 rounded px-2 py-1 text-center font-bold text-pink-600" value={editAttendeeData.paidAmount} onChange={e => setEditAttendeeData(p => ({...p, paidAmount: e.target.value}))} placeholder={event.cost.toString()} />
                            ) : (
                              <span className={`font-bold ${hasCustomAmount ? 'text-pink-600' : 'text-gray-900'}`}>€ {displayAmount.toFixed(2)}</span>
                            )}
                          </td>
                          <td className="px-6 py-4 text-center">
                             {!isEditing && (
                              <button onClick={(e) => { e.stopPropagation(); handleTogglePayment(attendee.id); }} className={`inline-flex items-center px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wide transition-all ${attendee.status === PaymentStatus.PAID ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-800'}`} type="button">
                                {attendee.status === PaymentStatus.PAID ? (<><CheckCircle className="w-3.5 h-3.5 mr-1" /> Pagato</>) : (<><XCircle className="w-3.5 h-3.5 mr-1" /> Da Pagare</>)}
                              </button>
                             )}
                          </td>
                          <td className="px-6 py-4 text-right">
                            {isEditing ? (
                              <div className="flex justify-end gap-2" onClick={e => e.stopPropagation()}><button onClick={() => saveEditedAttendee(attendee)} className="bg-green-500 text-white p-1.5 rounded-lg"><Save className="w-4 h-4" /></button><button onClick={cancelEditingAttendee} className="bg-gray-400 text-white p-1.5 rounded-lg"><X className="w-4 h-4" /></button></div>
                            ) : (
                              <div className="flex justify-end items-center gap-1" onClick={e => e.stopPropagation()}>
                                <button 
                                  onClick={() => handleTogglePresence(attendee)} 
                                  className={`p-2 rounded-lg transition-all ${isAbsent ? 'text-red-500 bg-red-50 hover:bg-red-100' : 'text-gray-400 hover:text-green-600 hover:bg-green-50'}`}
                                >
                                  {isAbsent ? <UserX className="w-4 h-4" /> : <UserCheck className="w-4 h-4" />}
                                </button>
                                <div className="w-px h-4 bg-gray-100 mx-1"></div>
                                <button onClick={() => startEditingAttendee(attendee)} className="text-gray-400 hover:text-indigo-600 p-2 rounded-lg"><Edit2 className="w-4 h-4" /></button>
                                <button onClick={() => requestDeleteAttendee(attendee.id)} className="text-gray-400 hover:text-red-600 p-2 rounded-lg"><Trash2 className="w-4 h-4" /></button>
                              </div>
                            )}
                          </td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { AppEvent, Attendee } from '../types';
import { Users, Search, Mail, Phone, ArrowLeft, SortAsc, SortDesc, Trophy, Star, Repeat, Target } from 'lucide-react';

interface ParticipantsListProps {
  events: AppEvent[];
  onBack: () => void;
  onParticipantClick: (key: string) => void;
}

type SortKey = 'name' | 'eventsCount';
type SortOrder = 'asc' | 'desc';

export const ParticipantsList: React.FC<ParticipantsListProps> = ({ events, onBack, onParticipantClick }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [sortKey, setSortKey] = useState<SortKey>('name');
  const [sortOrder, setSortOrder] = useState<SortOrder>('asc');

  const vipThreshold = Number(localStorage.getItem('onbeventi_vip_threshold') || '5');
  const regularThreshold = Number(localStorage.getItem('onbeventi_regular_threshold') || '3');

  const { list, stats } = useMemo(() => {
    const sortedEvents = [...events].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    const latestEventDate = sortedEvents.length > 0 ? new Date(sortedEvents[0].date).getTime() : 0;

    const map = new Map<string, { 
      attendee: Attendee, 
      eventsCount: number, 
      totalBookings: number, 
      eventTitles: string[], 
      firstEventDate: number, 
      key: string,
      isVip: boolean,
      isRegular: boolean
    }>();

    (events || []).forEach(event => {
      const eventTimestamp = new Date(event.date).getTime();
      (event.attendees || []).forEach(a => {
        const key = (a.email || a.phone || a.name).toLowerCase().trim();
        const isPresent = a.isPresent !== false;

        if (map.has(key)) {
          const existing = map.get(key)!;
          existing.totalBookings += 1;
          if (isPresent) {
            existing.eventsCount += 1;
          }
          if (eventTimestamp < existing.firstEventDate) {
            existing.firstEventDate = eventTimestamp;
          }
          existing.eventTitles.push(event.title);
          // Aggiorniamo il genere se non presente nel vecchio record ma presente nel nuovo
          if (!existing.attendee.gender && a.gender) {
            existing.attendee.gender = a.gender;
          }
        } else {
          map.set(key, {
            attendee: { ...a },
            eventsCount: isPresent ? 1 : 0,
            totalBookings: 1,
            eventTitles: [event.title],
            firstEventDate: eventTimestamp,
            key: key,
            isVip: false,
            isRegular: false
          });
        }
      });
    });

    const fullList = Array.from(map.values()).map(item => ({
      ...item,
      isVip: item.eventsCount >= vipThreshold,
      isRegular: item.eventsCount >= regularThreshold && item.eventsCount < vipThreshold
    }));

    // Consideriamo solo i membri con almeno UNA presenza effettiva per le statistiche demografiche e di ritorno
    const activeList = fullList.filter(m => m.eventsCount > 0);
    const totalMembersCount = fullList.length; // Totale anagrafica
    const activeMembersCount = activeList.length; // Totale presenti almeno una volta

    const multiEventCount = activeList.filter(m => m.eventsCount > 1).length;
    const fedeleCount = activeList.filter(m => m.isRegular).length;
    const vipCount = activeList.filter(m => m.isVip).length;

    // --- Calcolo Generi su membri ATTIVI ---
    const maleCount = activeList.filter(m => m.attendee.gender === 'M').length;
    const femaleCount = activeList.filter(m => m.attendee.gender === 'F').length;
    const malePercent = activeMembersCount > 0 ? (maleCount / activeMembersCount) * 100 : 0;
    const femalePercent = activeMembersCount > 0 ? (femaleCount / activeMembersCount) * 100 : 0;

    const historicalMembers = activeList.filter(m => m.firstEventDate < latestEventDate);
    const returningHistoricalCount = historicalMembers.filter(m => m.eventsCount > 1).length;
    const realReturnRate = historicalMembers.length > 0 
      ? (returningHistoricalCount / historicalMembers.length) * 100 
      : 0;

    const stats = {
      totalMembers: totalMembersCount,
      activeMembersCount,
      malePercent,
      femalePercent,
      multiEventPercentage: activeMembersCount > 0 ? (multiEventCount / activeMembersCount) * 100 : 0,
      fedelePercentage: activeMembersCount > 0 ? (fedeleCount / activeMembersCount) * 100 : 0,
      vipPercentage: activeMembersCount > 0 ? (vipCount / activeMembersCount) * 100 : 0,
      realReturnRate
    };

    let filteredList = [...fullList];
    if (searchTerm) {
      const lowerSearch = searchTerm.toLowerCase();
      filteredList = filteredList.filter(item => 
        item.attendee.name.toLowerCase().includes(lowerSearch) ||
        (item.attendee.email && item.attendee.email.toLowerCase().includes(lowerSearch)) ||
        (item.attendee.phone && item.attendee.phone.includes(searchTerm))
      );
    }

    filteredList.sort((a, b) => {
      if (sortKey === 'name') {
        const comparison = a.attendee.name.localeCompare(b.attendee.name);
        return sortOrder === 'asc' ? comparison : -comparison;
      } else {
        const comparison = a.eventsCount - b.eventsCount;
        return sortOrder === 'asc' ? comparison : -comparison;
      }
    });

    return { list: filteredList, stats };
  }, [events, searchTerm, sortKey, sortOrder, vipThreshold, regularThreshold]);

  const toggleSort = (key: SortKey) => {
    if (sortKey === key) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortKey(key);
      setSortOrder(key === 'eventsCount' ? 'desc' : 'asc');
    }
  };

  return (
    <div className="space-y-8 animate-fade-in">
      <div className="flex items-center gap-4">
        <button onClick={onBack} className="p-2.5 bg-white hover:bg-gray-50 text-gray-500 rounded-xl transition-colors border border-gray-100 shadow-sm">
          <ArrowLeft className="w-5 h-5" />
        </button>
        <div>
          <h1 className="text-2xl font-black text-gray-900 tracking-tight">Anagrafica & Community</h1>
          <p className="text-sm text-gray-500">Analisi della partecipazione e fedeltà dei membri.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-4">
        <div className="bg-white p-5 rounded-3xl border border-gray-100 shadow-sm relative overflow-hidden">
          <div className="absolute top-0 right-0 w-12 h-12 bg-indigo-50 rounded-bl-full"></div>
          <div className="relative">
            <Users className="w-4 h-4 text-indigo-600 mb-2" />
            <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Membri Attivi</p>
            <p className="text-2xl font-black text-gray-900 mt-0.5">{stats.activeMembersCount}</p>
            <div className="flex gap-2 mt-2">
              <span className="text-[8px] font-bold text-blue-500 bg-blue-50 px-1.5 py-0.5 rounded">M: {stats.malePercent.toFixed(0)}%</span>
              <span className="text-[8px] font-bold text-pink-500 bg-pink-50 px-1.5 py-0.5 rounded">F: {stats.femalePercent.toFixed(0)}%</span>
            </div>
          </div>
        </div>

        <div className="bg-white p-5 rounded-3xl border border-gray-100 shadow-sm relative overflow-hidden group">
          <div className="absolute top-0 right-0 w-12 h-12 bg-pink-50 rounded-bl-full"></div>
          <div className="relative">
            <Repeat className="w-4 h-4 text-pink-500 mb-2" />
            <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Frequenza Attivi</p>
            <p className="text-2xl font-black text-gray-900 mt-0.5">{stats.multiEventPercentage.toFixed(1)}%</p>
            <p className="text-[8px] text-gray-400 mt-1 font-medium italic">Su membri con min. 1 presenza</p>
          </div>
        </div>

        <div className="bg-gradient-to-br from-indigo-950 to-indigo-900 p-5 rounded-3xl border border-indigo-800 shadow-xl relative overflow-hidden text-white group">
          <div className="absolute -top-2 -right-2 w-16 h-16 bg-pink-500/10 rounded-full blur-xl group-hover:scale-150 transition-transform"></div>
          <div className="relative">
            <Target className="w-4 h-4 text-pink-400 mb-2" />
            <p className="text-[9px] font-black text-indigo-300 uppercase tracking-widest">Ritorno Reale</p>
            <p className="text-2xl font-black text-white mt-0.5">{stats.realReturnRate.toFixed(1)}%</p>
            <p className="text-[8px] text-indigo-400 mt-1 font-bold leading-tight uppercase tracking-tighter">
              Calcolato su storici presenti
            </p>
          </div>
        </div>

        <div className="bg-white p-5 rounded-3xl border border-gray-100 shadow-sm relative overflow-hidden group">
          <div className="absolute top-0 right-0 w-12 h-12 bg-green-50 rounded-bl-full"></div>
          <div className="relative">
            <Star className="w-4 h-4 text-green-500 mb-2" />
            <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Fedeli Presenti</p>
            <p className="text-2xl font-black text-gray-900 mt-0.5">{stats.fedelePercentage.toFixed(1)}%</p>
            <p className="text-[8px] text-gray-400 mt-1 font-medium italic">Badge Fedeltà</p>
          </div>
        </div>

        <div className="bg-white p-5 rounded-3xl border border-gray-100 shadow-sm relative overflow-hidden group">
          <div className="absolute top-0 right-0 w-12 h-12 bg-yellow-50 rounded-bl-full"></div>
          <div className="relative">
            <Trophy className="w-4 h-4 text-yellow-500 mb-2" />
            <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">VIP Presenti</p>
            <p className="text-2xl font-black text-gray-900 mt-0.5">{stats.vipPercentage.toFixed(1)}%</p>
            <p className="text-[8px] text-gray-400 mt-1 font-medium italic">Badge VIP</p>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="p-6 border-b border-gray-100 flex flex-col md:flex-row justify-between items-stretch md:items-center gap-4">
          <div className="relative flex-1 max-w-md">
            <Search className="absolute left-3.5 top-3 w-4 h-4 text-gray-400" />
            <input 
              type="text"
              placeholder="Cerca per nome, email o telefono..."
              className="w-full pl-11 pr-4 py-2.5 border border-gray-100 rounded-2xl text-sm focus:ring-2 focus:ring-pink-500 shadow-sm transition-all outline-none"
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>

          <div className="flex bg-gray-50 p-1 rounded-2xl border border-gray-200">
            <button 
              onClick={() => toggleSort('name')}
              className={`flex items-center gap-2 px-4 py-1.5 rounded-xl text-xs font-bold transition-all ${sortKey === 'name' ? 'bg-white text-indigo-950 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
            >
              Nome {sortKey === 'name' && (sortOrder === 'asc' ? <SortAsc className="w-3.5 h-3.5" /> : <SortDesc className="w-3.5 h-3.5" />)}
            </button>
            <button 
              onClick={() => toggleSort('eventsCount')}
              className={`flex items-center gap-2 px-4 py-1.5 rounded-xl text-xs font-bold transition-all ${sortKey === 'eventsCount' ? 'bg-white text-indigo-950 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
            >
              Presenze {sortKey === 'eventsCount' && (sortOrder === 'asc' ? <SortAsc className="w-3.5 h-3.5" /> : <SortDesc className="w-3.5 h-3.5" />)}
            </button>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-indigo-950 text-white text-[10px] font-bold uppercase tracking-wider">
                <th className="px-6 py-4 cursor-pointer hover:bg-indigo-900 transition-colors" onClick={() => toggleSort('name')}>
                  <div className="flex items-center gap-2">
                    Membro {sortKey === 'name' && (sortOrder === 'asc' ? <SortAsc className="w-3 h-3 opacity-60" /> : <SortDesc className="w-3 h-3 opacity-60" />)}
                  </div>
                </th>
                <th className="px-6 py-4">Contatti</th>
                <th className="px-6 py-4 text-center cursor-pointer hover:bg-indigo-900 transition-colors" onClick={() => toggleSort('eventsCount')}>
                  <div className="flex items-center justify-center gap-2">
                    Presenze {sortKey === 'eventsCount' && (sortOrder === 'asc' ? <SortAsc className="w-3 h-3 opacity-60" /> : <SortDesc className="w-3 h-3 opacity-60" />)}
                  </div>
                </th>
                <th className="px-6 py-4">Ultimi Eventi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {list.length === 0 ? (
                <tr>
                  <td colSpan={4} className="px-6 py-24 text-center text-gray-400 italic">
                    <div className="flex flex-col items-center gap-3">
                      <div className="p-4 bg-gray-50 rounded-full"><Users className="w-8 h-8 opacity-20" /></div>
                      <p>Nessun membro trovato.</p>
                    </div>
                  </td>
                </tr>
              ) : (
                list.map((item, idx) => (
                  <tr 
                    key={idx} 
                    className="hover:bg-pink-50/30 transition-colors group cursor-pointer"
                    onClick={() => onParticipantClick(item.key)}
                  >
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-indigo-50 to-pink-50 text-indigo-700 flex items-center justify-center font-black text-sm shadow-sm group-hover:scale-110 transition-transform relative border border-gray-100">
                          {item.attendee.name.charAt(0).toUpperCase()}
                          {item.isVip && (
                            <div className="absolute -top-1.5 -right-1.5 bg-yellow-400 p-0.5 rounded-full border-2 border-white shadow-sm">
                              <Trophy className="w-2.5 h-2.5 text-white" />
                            </div>
                          )}
                        </div>
                        <div className="flex flex-col">
                          <div className="flex items-center gap-2">
                            <span className="font-bold text-gray-900 group-hover:text-pink-600 transition-colors">{item.attendee.name}</span>

                            {item.isVip && (
                              <span className="inline-flex items-center bg-yellow-100 text-yellow-700 px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-wider border border-yellow-200">
                                <Trophy className="w-2.5 h-2.5 mr-1" /> VIP
                              </span>
                            )}
                            {item.isRegular && (
                              <span className="inline-flex items-center bg-green-100 text-green-700 px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-wider border border-green-200">
                                <Star className="w-2.5 h-2.5 mr-1" /> FEDELE
                              </span>
                            )}
                          </div>
                          {item.eventsCount >= vipThreshold && (
                            <span className="text-[9px] text-yellow-600/70 font-bold uppercase tracking-tighter">Best Member</span>
                          )}
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="space-y-1">
                        {item.attendee.email && (
                          <div className="flex items-center text-[11px] text-gray-500">
                            <Mail className="w-3 h-3 mr-1.5 text-indigo-300" /> {item.attendee.email}
                          </div>
                        )}
                        {item.attendee.phone && (
                          <div className="flex items-center text-[11px] text-gray-500">
                            <Phone className="w-3 h-3 mr-1.5 text-indigo-300" /> {item.attendee.phone}
                          </div>
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-4 text-center">
                      <div className="flex flex-col items-center">
                        <span className={`inline-block px-4 py-1.5 rounded-full text-xs font-black border min-w-[3rem] shadow-sm transition-all ${
                          item.eventsCount >= vipThreshold 
                            ? 'bg-yellow-400 text-white border-yellow-500 scale-110' 
                            : item.eventsCount >= regularThreshold 
                              ? 'bg-green-500 text-white border-green-600'
                              : 'bg-indigo-50 text-indigo-700 border-indigo-100'
                        }`}>
                          {item.eventsCount}
                        </span>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex flex-wrap gap-1.5 max-w-sm">
                        {item.eventTitles.slice(-2).reverse().map((t, i) => (
                          <span key={i} className={`text-[9px] px-2 py-0.5 rounded border shadow-sm truncate max-w-[120px] ${
                            i === 0 ? 'bg-indigo-50 text-indigo-700 border-indigo-100 font-bold' : 'bg-white text-gray-500 border-gray-100'
                          }`}>
                            {t}
                          </span>
                        ))}
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};
